-- =====================================================================================
-- Surgery :: V007 — specialty content seed: indications + operative templates for all
-- fifteen specialties (SB-4 content fan-out, integrated into SB-2's empty content tables).
--
-- "Content over shared infrastructure" (surgical domain pack audit, consequence #4): the
-- shared spine (S0-S3, SB-1, SB-2) is built once; this migration is the fifteen specialties
-- CONTRIBUTING content into it rather than forking their own episode model. 118 indications
-- (7-8 per specialty) and 75 operative templates (5 per specialty), authored fresh against
-- the empty surgical_specialty_indication/surgical_operative_template tables V006 created.
--
-- Zimbabwe-service-aware throughout: open-first with laparoscopy noted only where realistic
-- at central hospitals, resource-aware alternatives named explicitly (e.g. SIGN nailing
-- alongside plating, MMF arch bars where plates are scarce, MSICS over phaco), referral-level
-- routing (district/provincial/central) named per indication where it matters. Every
-- indication and template is seeded ENGINEERING_SEED / PENDING_MOHCC_RATIFICATION (the table
-- defaults, V006) — complete engineering content, not yet clinically ratified. No citations
-- invented; therapy content limited to agent-and-timing conventions, never precise dosing.
--
-- Deliberately NOT every procedure a specialty performs — each fragment's own authoring pass
-- named specific omissions (e.g. Whipple/liver resection, valve replacement, TME) where a
-- seeded district-level template would misrepresent capability that does not exist at the
-- levels this pack targets; those indications are still named, routed to MDT/central level,
-- without a false operative template attached.
--
-- NOT included in this migration: the accompanying six-layer CDS rule content (DATA_
-- VALIDATION/DANGER_SIGN/CLASSIFICATION/THERAPY/MONITORING/FOLLOW_UP, ~145 rules across all
-- fifteen specialties) Lane C also produced. clinical-knowledge-platform-service's
-- rule_definitions schema (V001/V006) was not reviewed before this migration was written;
-- integrating rule content into a co-edited service's table needs that review first rather
-- than guessing a column mapping. Named debt, not silently dropped — the rule fragments are
-- preserved (see the programme's own working notes) for that follow-up integration.
-- =====================================================================================

INSERT INTO surgery.surgical_specialty_indication
    (tenant_id, specialty, indication_code, condition_display, typical_procedure, urgency_guidance, non_operative_alternatives, notes)
SELECT '00000000-0000-4000-8000-000000000001'::uuid, specialty, indication_code, condition_display, typical_procedure, urgency_guidance, non_operative_alternatives, notes
FROM (VALUES
('GENERAL_SURGERY', 'IND-GS-01', 'Acute appendicitis (clinical diagnosis with or without imaging confirmation)', 'Open appendicectomy via Lanz incision; laparoscopic appendicectomy where stack and skills available (central hospitals)', 'URGENT — next available emergency list; EMERGENCY if perforation or generalised peritonitis suspected', 'Antibiotic-first management is described for uncomplicated appendicitis in selected, imaging-confirmed cases with reliable follow-up; recurrence in roughly one in three within a year and not appropriate where imaging or review capacity is limited', 'District-level procedure. Faecolith on imaging, pregnancy, or immunosuppression favour operative management. Interval appendicectomy after conservatively managed mass remains individualised'),
  ('GENERAL_SURGERY', 'IND-GS-02', 'Symptomatic cholelithiasis with recurrent biliary colic', 'Laparoscopic cholecystectomy (central hospital); open cholecystectomy where laparoscopy unavailable', 'ELECTIVE — expedite if recurrent admissions, previous cholecystitis, or gallstone pancreatitis episode', 'Dietary fat reduction and analgesia; not curative — symptomatic recurrence likely and complications (cholecystitis, pancreatitis, obstructive jaundice) accrue while waiting', 'Confirm stones on ultrasound and normal-calibre common bile duct with normal liver enzymes before listing; deranged LFTs or dilated duct mandate duct assessment first (see UPPER_GI_HPB pathway)'),
  ('GENERAL_SURGERY', 'IND-GS-03', 'Acute calculous cholecystitis', 'Early cholecystectomy (ideally within 72 hours of onset, laparoscopic or open) or interval cholecystectomy after antibiotic cool-down where early surgery not feasible', 'EXPEDITED — early surgery preferred within index admission where theatre access allows', 'Intravenous antibiotics and interval surgery at 6 weeks; accepted pathway where acute theatre access or laparoscopy is constrained, but carries readmission risk during the interval', 'Low threshold for subtotal cholecystectomy or bail-out cholecystostomy in the hostile gallbladder; empyema and emphysematous change escalate urgency to URGENT'),
  ('GENERAL_SURGERY', 'IND-GS-04', 'Inguinal hernia (symptomatic, or any femoral hernia)', 'Open mesh repair (Lichtenstein); tissue repair (modified Bassini or Shouldice) where mesh supply unreliable', 'ELECTIVE — EMERGENCY if irreducible with pain, obstruction, or strangulation; femoral hernias should not wait on routine lists', 'Watchful waiting is defensible for minimally symptomatic direct inguinal hernias in frail patients; truss use discouraged; femoral hernias have no safe non-operative option given strangulation risk', 'District-level procedure under local or spinal anaesthesia. Counsel on chronic groin pain and recurrence; bilateral or recurrent hernias at central hospital where laparoscopic repair available'),
  ('GENERAL_SURGERY', 'IND-GS-05', 'Perforated peptic ulcer with peritonitis', 'Laparotomy, omental (Graham) patch repair and peritoneal lavage', 'EMERGENCY — resuscitate and operate without delay; mortality rises with every hour of established peritonitis', 'Non-operative management (nasogastric decompression, antibiotics, antisecretory therapy) only for the moribund patient unfit for any anaesthetic or a sealed perforation with localised signs and close monitoring', 'Biopsy gastric ulcer edges to exclude malignancy; prescribe post-repair proton pump inhibitor course and Helicobacter pylori eradication; definitive acid-reducing surgery rarely indicated at index operation'),
  ('GENERAL_SURGERY', 'IND-GS-06', 'Adhesive small bowel obstruction failing conservative management', 'Laparotomy and adhesiolysis; resection and anastomosis or stoma if non-viable bowel found', 'URGENT — operate for failure to resolve within 48–72 hours of nasogastric decompression, or immediately for signs of strangulation', 'Nasogastric decompression, intravenous fluids and serial examination succeed in the majority of adhesive episodes; water-soluble contrast challenge both predicts and promotes resolution where available', 'Signs of strangulation (constant pain, tachycardia, peritonism, rising lactate or white count) convert to EMERGENCY at any point; virgin abdomen obstruction warrants earlier surgery as adhesions cannot be assumed'),
  ('GENERAL_SURGERY', 'IND-GS-07', 'Necrotising soft tissue infection (necrotising fasciitis, Fournier gangrene)', 'Emergency radical surgical debridement with planned re-look at 24–48 hours; diverting colostomy occasionally required for perineal disease', 'EMERGENCY — source control within hours; antibiotics alone do not penetrate necrotic tissue', 'None once the diagnosis is made; broad-spectrum antibiotics are an adjunct, never a substitute for debridement', 'Do not close at first operation; serial debridements expected. High association with diabetes and HIV — screen both. Transfer only after first debridement if district theatre is capable; debridement must not wait for transfer'),
  ('GENERAL_SURGERY', 'IND-GS-08', 'Incisional or ventral hernia (symptomatic, enlarging, or previously incarcerated)', 'Open mesh repair (sublay preferred where expertise allows; onlay acceptable); primary suture repair only for defects under 1 cm', 'ELECTIVE — EMERGENCY if incarcerated with obstruction or strangulation', 'Abdominal binder and weight loss for the asymptomatic or high-anaesthetic-risk patient; does not prevent enlargement or incarceration', 'Optimise before elective repair: weight, glycaemic control, smoking cessation, and treat skin sepsis; large loss-of-domain defects to central hospital for component separation expertise'),
  ('COLORECTAL', 'IND-CR-01', 'Resectable colonic adenocarcinoma', 'Segmental colectomy with regional lymphadenectomy (right or extended right hemicolectomy, left hemicolectomy, or sigmoid colectomy according to site)', 'EXPEDITED — target surgery within 4–6 weeks of MDT decision; URGENT if impending obstruction or ongoing bleeding', 'No curative alternative; chemotherapy alone is palliative — defensible only where staging shows unresectable metastatic disease or the patient is unfit for resection', 'Staging CT chest-abdomen-pelvis, colonoscopy with histology, and CEA before MDT; resection at central hospital; stoma counselling and site marking before theatre'),
  ('COLORECTAL', 'IND-CR-02', 'Rectal adenocarcinoma', 'Anterior resection with total mesorectal excision for mid-upper rectum; abdominoperineal excision for low rectum with sphincter involvement', 'EXPEDITED — sequence via MDT; neoadjuvant chemoradiotherapy for locally advanced or threatened-margin disease before resection where radiotherapy accessible', 'Chemoradiotherapy alone in the unfit patient or as part of organ-preservation strategies in complete responders under strict surveillance capacity — not appropriate where surveillance cannot be guaranteed', 'MRI pelvis (or best available cross-sectional imaging) for local staging; digital rectal examination findings documented; central hospital MDT mandatory before any resection; defunctioning ileostomy usual after low anastomosis'),
  ('COLORECTAL', 'IND-CR-03', 'Sigmoid volvulus', 'Endoscopic detorsion and decompression, then elective sigmoid colectomy during same or early planned admission; Hartmann''s procedure if gangrenous bowel at presentation', 'URGENT — decompress on presentation; EMERGENCY laparotomy if peritonitis, blood on decompression, or failed detorsion', 'Decompression alone without interval resection carries high recurrence and cumulative mortality; acceptable only for patients unfit for any resection, with clear re-presentation advice', 'Common presentation in the region; recurrence after decompression alone is the rule, not the exception — book definitive resection before discharge rather than open-ended follow-up'),
  ('COLORECTAL', 'IND-CR-04', 'Perforated diverticulitis with purulent or faeculent peritonitis (Hinchey III–IV)', 'Hartmann''s procedure (sigmoid resection, end colostomy, closure of rectal stump)', 'EMERGENCY — resuscitate and operate; source control must not wait', 'Laparoscopic lavage described for selected purulent (Hinchey III) cases in specialist centres; not appropriate where relook capacity and interventional radiology are limited; percutaneous drainage applies to localised abscess (Hinchey I–II), not free perforation', 'Counsel that colostomy reversal is a second major operation and a significant proportion are never reversed; exclude perforated cancer — send resection specimen for histology and complete colonic evaluation after recovery'),
  ('COLORECTAL', 'IND-CR-05', 'Symptomatic grade III–IV haemorrhoids', 'Open haemorrhoidectomy (Milligan-Morgan)', 'ELECTIVE — URGENT for irreducible thrombosed prolapsed haemorrhoids with sepsis or urinary retention', 'Fibre, fluids and stool softeners for grade I–II; rubber-band ligation in clinic for grade I–III where equipment available — recurrence higher than excision but avoids theatre', 'Exclude proximal pathology in any patient with rectal bleeding — do not attribute bleeding to haemorrhoids in patients over 40 or with red-flag features without at least sigmoidoscopy; warn about post-operative pain and rare secondary haemorrhage around day 7–10'),
  ('COLORECTAL', 'IND-CR-06', 'Fistula-in-ano', 'Examination under anaesthesia with fistulotomy for low simple tracks; loose seton for high or sphincter-involving tracks', 'ELECTIVE — EXPEDITED if recurrent sepsis', 'No reliable non-operative cure; antibiotics manage acute flares only; in the HIV-positive or possibly tuberculous patient, biopsy the track — atypical fistulae may be tuberculous and respond to medical treatment', 'Continence assessment and documentation before any sphincter division; recurrent, multiple or anterior-in-women fistulae to central hospital; send curettings for histology and TB testing where suspicion exists'),
  ('COLORECTAL', 'IND-CR-07', 'Perianal abscess', 'Incision and drainage under anaesthesia, deroofing cavity close to the anal verge', 'EMERGENCY — same-day drainage; delay breeds sphincter destruction and necrotising infection, especially in diabetes and HIV', 'Antibiotics alone are inadequate for a collection; adjunct only for surrounding cellulitis or immunosuppression', 'Do not probe aggressively for a fistula in the acute pus-filled field; warn that up to half develop a fistula and arrange review; screen for diabetes; recurrent or bilateral (horseshoe) sepsis to a senior surgeon'),
  ('COLORECTAL', 'IND-CR-08', 'Full-thickness rectal prolapse', 'Perineal approach (Delorme''s or Altemeier''s) for the frail; abdominal suture rectopexy (open or laparoscopic) for fit patients at central hospital', 'ELECTIVE — URGENT if incarcerated or ulcerated prolapse', 'Pelvic floor exercises and bulking agents manage symptoms but do not correct full-thickness prolapse; reasonable holding measure in the unfit', 'Assess continence and constipation preoperatively — both influence procedure choice; incarcerated prolapse may reduce with sugar applied topically before emergency surgery is committed to'),
  ('UPPER_GI_HPB', 'IND-UGI-01', 'Gastric outlet obstruction from chronic peptic ulcer disease', 'Gastrojejunostomy (with biopsy of the obstructing segment); truncal vagotomy addition per senior practice where acid-reduction surgery still used', 'EXPEDITED — after correction of dehydration, hypochloraemic alkalosis and nutritional deficit', 'Endoscopic balloon dilatation plus proton pump inhibitor and Helicobacter pylori eradication for selected short strictures where endoscopy service exists; nasogastric decompression and nutritional optimisation are bridges, not destinations', 'Malignancy mimics benign outlet obstruction — endoscopic biopsy (or operative biopsy) of the obstructing lesion is mandatory before or during bypass; correct electrolytes before theatre'),
  ('UPPER_GI_HPB', 'IND-UGI-02', 'Gastric adenocarcinoma (resectable on staging)', 'Distal gastrectomy with regional lymphadenectomy for antral tumours; total gastrectomy for proximal or diffuse tumours — central hospital, after MDT', 'EXPEDITED — staging and MDT first; URGENT only for uncontrolled bleeding or obstruction', 'Palliative options for unresectable disease: gastrojejunostomy or endoscopic stent for outlet obstruction, systemic chemotherapy per oncology; best supportive care where performance status precludes treatment', 'Staging CT chest-abdomen-pelvis and, where available, staging laparoscopy for locally advanced disease to exclude peritoneal spread before committing to laparotomy; nutritional assessment and prehabilitation'),
  ('UPPER_GI_HPB', 'IND-UGI-03', 'Choledocholithiasis with obstructive jaundice', 'ERCP with sphincterotomy and stone extraction where service exists, followed by cholecystectomy; open cholecystectomy with common bile duct exploration (choledochotomy, stone clearance, T-tube or primary closure) where ERCP unavailable', 'URGENT if cholangitis (fever, jaundice, right upper quadrant pain) — biliary decompression is the priority; otherwise EXPEDITED', 'Observation for asymptomatic incidental duct stones is not recommended — cholangitis and pancreatitis risks persist; medical dissolution has no practical role', 'Cholangitis with hypotension or confusion is a biliary emergency — decompress by whatever route is fastest available; document duct calibre and stone clearance method; T-tube cholangiogram before removal where T-tube used'),
  ('UPPER_GI_HPB', 'IND-UGI-04', 'Gallbladder empyema or severe acute cholecystitis not responding to antibiotics', 'Cholecystectomy (open readily accepted in the hostile right upper quadrant); percutaneous or open cholecystostomy as bail-out in the unfit patient', 'URGENT — source control within the admission; do not discharge an undrained empyema', 'Cholecystostomy plus antibiotics defers definitive surgery in the physiologically unfit; interval cholecystectomy or tube management decision follows recovery', 'Subtotal cholecystectomy is the safe bail-out when the hepatocystic triangle is obliterated — bile duct injury prevention outranks complete gallbladder removal'),
  ('UPPER_GI_HPB', 'IND-UGI-05', 'Symptomatic pancreatic pseudocyst persisting beyond 6 weeks with mature wall', 'Internal drainage: open cystogastrostomy (or cystojejunostomy for cysts not adherent to stomach); endoscopic cystogastrostomy where advanced endoscopy exists', 'ELECTIVE — timed for wall maturity; URGENT if infected, bleeding, or causing gastric outlet/biliary obstruction', 'Observation is correct for asymptomatic pseudocysts regardless of size — many resolve; percutaneous external drainage discouraged for communicating pseudocysts (fistula risk) and reserved for infected collections without internal-drainage options', 'Confirm the lesion is a pseudocyst, not a cystic neoplasm — history of pancreatitis, imaging morphology, and where doubt persists cyst fluid analysis; suspected neoplasm changes the entire pathway and goes to MDT'),
  ('UPPER_GI_HPB', 'IND-UGI-06', 'Liver abscess (pyogenic or amoebic) large, loculated, or not responding to medical therapy', 'Percutaneous drainage under ultrasound guidance plus antibiotics as first line; open surgical drainage for rupture, multiloculation inaccessible to drains, or failed percutaneous management', 'URGENT — drainage decision within 24–48 hours of failed medical response; EMERGENCY if rupture with peritonitis', 'Amoebic abscess usually responds to metronidazole-class therapy alone — aspiration/drainage reserved for large left-lobe abscesses threatening rupture, diagnostic doubt, or non-response; small pyogenic abscesses may respond to prolonged antibiotics', 'Serology or clinical context to separate amoebic from pyogenic where possible; pyogenic abscess demands a source hunt (biliary disease, portal seeding from appendix/colon); send aspirate for culture'),
  ('UPPER_GI_HPB', 'IND-UGI-07', 'Oesophageal carcinoma with progressive dysphagia', 'Staging then oesophagectomy at central/specialist level for the resectable minority; palliative intubation/stenting or feeding gastrostomy/jejunostomy for the majority presenting late', 'EXPEDITED — nutrition deteriorates weekly; staging must not drift', 'Palliative radiotherapy or chemotherapy per oncology access; endoscopic stenting relieves dysphagia fastest where available; feeding gastrostomy maintains nutrition but does not relieve dysphagia — discuss goals honestly', 'Most regional presentations are advanced squamous carcinoma; decide curative-versus-palliative intent at MDT before any operation; document swallowing status and weight at every visit'),
  ('UPPER_GI_HPB', 'IND-UGI-08', 'Splenic rupture with haemodynamic instability, or massive symptomatic splenomegaly requiring removal', 'Emergency splenectomy for the unstable trauma patient; elective splenectomy for haematological indication after physician MDT', 'EMERGENCY for unstable rupture; ELECTIVE for haematological indications with vaccination lead time', 'Non-operative management (observation, with angioembolisation where interventional radiology exists) is standard for the stable splenic injury — grade and monitor rather than reflexively operate', 'Elective cases: vaccinate against encapsulated organisms (pneumococcus, meningococcus, Haemophilus influenzae b) at least 2 weeks before surgery; emergency cases vaccinate post-operatively before discharge; educate on lifelong overwhelming post-splenectomy infection risk and early antibiotic access — critical in malaria-endemic settings'),
  ('BREAST_ENDOCRINE', 'IND-BE-01', 'Early operable breast carcinoma (confirmed on triple assessment)', 'Wide local excision with axillary staging (sentinel node biopsy where blue dye/isotope available; axillary sampling or clearance otherwise), or mastectomy per tumour-to-breast ratio and patient choice', 'EXPEDITED — surgery within 4–6 weeks of MDT decision; delays cost stage', 'Primary endocrine therapy alone for the elderly or unfit with strongly hormone-receptor-positive disease — disease control, not cure; no defensible non-treatment option for the fit patient', 'Triple assessment (clinical, imaging, core needle biopsy with receptor status where laboratory capacity allows) complete before theatre; MDT decision recorded; breast-conserving surgery requires radiotherapy access — where radiotherapy is inaccessible, mastectomy is the honest recommendation'),
  ('BREAST_ENDOCRINE', 'IND-BE-02', 'Locally advanced breast carcinoma', 'Neoadjuvant systemic therapy first, then modified radical mastectomy; toilet mastectomy for fungation/bleeding control in advanced disease after MDT', 'EXPEDITED — systemic therapy start is the urgent step, surgery is sequenced after response', 'Systemic therapy and radiotherapy without surgery for inoperable or metastatic disease; best supportive care with wound management for end-stage fungating disease', 'Common regional presentation stage; biopsy and receptor status before systemic therapy; document response before surgery; involve palliative care early when intent is not curative'),
  ('BREAST_ENDOCRINE', 'IND-BE-03', 'Breast abscess (lactational or non-lactational)', 'Ultrasound-guided (or landmark) needle aspiration, repeated as needed, with antibiotics; incision and drainage for thick pus, overlying skin necrosis, or failed aspiration', 'URGENT — same-visit aspiration; do not book a breast abscess to a distant elective list', 'Aspiration plus antibiotics IS the first-line management and avoids scarring and milk-fistula; continue breastfeeding or expressing from the affected side in lactational abscess', 'A solid or recurrent "abscess" that does not resolve must be biopsied — inflammatory carcinoma and tuberculosis both mimic abscess; non-lactational abscess in a smoker suggests periductal mastitis with recurrence risk'),
  ('BREAST_ENDOCRINE', 'IND-BE-04', 'Fibroadenoma — large (over about 3 cm), enlarging, or causing significant symptoms/anxiety after triple assessment', 'Excision biopsy through cosmetic (periareolar or inframammary where feasible) incision', 'ELECTIVE', 'Observation is correct for small, triple-assessment-concordant fibroadenomas in young women — many regress or remain static; document a clear safety-net for enlargement', 'Rapid enlargement raises phyllodes tumour — excise with a margin rather than enucleate when suspected; all excised tissue to histology without exception'),
  ('BREAST_ENDOCRINE', 'IND-BE-05', 'Multinodular goitre with compressive symptoms, retrosternal extension, or suspicion of malignancy', 'Total or near-total thyroidectomy (central hospital — anaesthetic and recurrent laryngeal nerve considerations)', 'EXPEDITED — URGENT if stridor or rapidly enlarging; ELECTIVE for cosmesis-only complaints after counselling', 'Observation with interval assessment for asymptomatic euthyroid goitre; radioiodine where nuclear medicine exists for selected toxic goitres; levothyroxine suppression is not effective therapy for established multinodular goitre', 'Preoperative vocal cord assessment and thyroid function; check airway imaging for retrosternal extension; ensure calcium and levothyroxine supply chain understood by patient before electing total thyroidectomy'),
  ('BREAST_ENDOCRINE', 'IND-BE-06', 'Thyroid nodule with cytological suspicion of malignancy, or toxic adenoma failing medical control', 'Hemithyroidectomy (diagnostic/therapeutic) with completion thyroidectomy if histology confirms carcinoma requiring it', 'EXPEDITED for suspicious cytology; ELECTIVE for benign toxic adenoma after euthyroid preparation', 'Fine-needle aspiration surveillance for cytologically benign nodules; antithyroid drugs or radioiodine for toxic adenoma where available and acceptable', 'Render thyrotoxic patients euthyroid before theatre — thyroid storm is preventable; document preoperative voice and cord status; counsel on hypothyroidism and completion-surgery possibilities'),
  ('BREAST_ENDOCRINE', 'IND-BE-07', 'Primary hyperparathyroidism (symptomatic, or meeting biochemical/end-organ criteria)', 'Parathyroidectomy at central hospital — bilateral neck exploration where preoperative localisation unavailable; focused approach only with concordant localisation studies', 'ELECTIVE — EXPEDITED for hypercalcaemic crisis after medical stabilisation', 'Medical management (hydration, bisphosphonates where available, monitoring) for the unfit or those declining surgery — controls calcium but not the disease; surgery is the only cure', 'Confirm diagnosis biochemically (elevated calcium with non-suppressed parathyroid hormone) and exclude familial hypocalciuric hypercalcaemia where testing allows; renal imaging and bone assessment document end-organ effect; experienced neck surgeon materially changes outcomes'),
  ('UROLOGY', 'IND-URO-01', 'Acute testicular torsion (or torsion that cannot be excluded)', 'Emergency scrotal exploration with detorsion and bilateral fixation, or orchidectomy if non-viable', 'EMERGENCY — explore within 6 hours of pain onset; salvage falls steeply thereafter; when in doubt, explore', 'None where torsion cannot be excluded — ultrasound must never delay exploration when clinical suspicion is real; manual detorsion is at best a bridge to theatre, not a substitute', 'District-level emergency — do not transfer a torsion that a capable district theatre can explore; fix the contralateral testis at the same operation; document pain-onset time in every referral'),
  ('UROLOGY', 'IND-URO-02', 'Benign prostatic enlargement with refractory retention (failed trial without catheter) or complications', 'Transurethral resection of the prostate at central hospital; open simple prostatectomy (transvesical) for very large glands or where no resectoscope service exists', 'EXPEDITED — patient is catheter-dependent; each month adds infection and stone risk', 'Long-term or intermittent catheterisation with alpha-blocker where surgery is unavailable or declined — livable but with infection, stone, and dignity costs that must be stated honestly; medical therapy alone rarely rescues established retention', 'Exclude prostate cancer clinically (digital rectal examination, PSA interpretation in context) before attributing retention to benign disease; renal function and ultrasound for upper tract effect; sterile or treated urine before any instrumentation'),
  ('UROLOGY', 'IND-URO-03', 'Urethral stricture with obstructed voiding or retention', 'Direct visual internal urethrotomy for short bulbar strictures where endoscopy exists; anastomotic or substitution urethroplasty at specialist level for recurrent or long strictures; suprapubic cystostomy as the universal safe holding measure', 'ELECTIVE for definitive repair — EMERGENCY suprapubic drainage for retention where a catheter will not pass', 'Repeated dilatation manages symptoms with near-certain recurrence — acceptable holding strategy where definitive service is distant; self-dilatation programmes where supplies allow', 'Common sequel of urethritis and trauma in the region; never force a urethral catheter through resistance — suprapubic drainage is the safe answer at any level of facility; document stricture length and site (retrograde urethrogram) before definitive planning'),
  ('UROLOGY', 'IND-URO-04', 'Obstructing ureteric stone with fever or sepsis (obstructed infected kidney)', 'Emergency decompression: retrograde ureteric (JJ) stent or percutaneous nephrostomy — whichever the facility can deliver fastest; definitive stone treatment deferred until sepsis resolves', 'EMERGENCY — decompression within hours; antibiotics alone do not sterilise an obstructed system', 'None for the obstructed infected kidney; for the uninfected obstructing stone, analgesia and expectant passage is correct for small distal stones with follow-up imaging', 'This is the urological equivalent of cholangitis — escalate immediately; definitive stone surgery (ureteroscopy, ureterolithotomy where endoscopy absent) is a separate later episode; culture urine and blood before antibiotics where it will not delay them'),
  ('UROLOGY', 'IND-URO-05', 'Bladder calculus', 'Open cystolithotomy (district-appropriate); endoscopic cystolitholapaxy where equipment exists for smaller stones', 'ELECTIVE — EXPEDITED if recurrent infection, retention episodes, or haematuria', 'Small stones may pass or be managed with treatment of the underlying outflow obstruction; leaving a symptomatic stone accrues infection and (long-term) squamous carcinoma risk', 'A bladder stone is a symptom of something — outflow obstruction, stricture, neurogenic bladder, or foreign body must be sought and treated or the stone returns; send stone for analysis where laboratory exists'),
  ('UROLOGY', 'IND-URO-06', 'Symptomatic hydrocele in the adult', 'Hydrocelectomy — Jaboulay eversion for large sacs; Lord''s plication for thin-walled moderate sacs', 'ELECTIVE', 'Aspiration alone recurs almost universally and risks infection — defensible only as comfort measure in the unfit; observation for small asymptomatic hydroceles', 'Examine and, where any doubt, ultrasound the testis — a hydrocele can hide a tumour, and a young man''s new hydrocele deserves scrutiny; in filaria-endemic exposure histories consider that aetiology; day-case procedure at district level'),
  ('UROLOGY', 'IND-URO-07', 'Phimosis with recurrent balanitis, ballooning, or non-retractile scarred foreskin (balanitis xerotica obliterans)', 'Circumcision', 'ELECTIVE — URGENT only for acute severe balanoposthitis with retention or for irreducible paraphimosis after failed reduction', 'Topical corticosteroid with gentle retraction resolves many physiological/mild cases, especially in boys; hygiene measures for mild balanitis; paraphimosis is managed by urgent manual reduction first, circumcision later', 'Send scarred foreskins for histology (balanitis xerotica obliterans, occasionally carcinoma); voluntary medical male circumcision programmes run in parallel — clinical circumcision here refers to disease indications; check glycaemia in recurrent balanitis'),
  ('UROLOGY', 'IND-URO-08', 'Bladder tumour identified on imaging or cystoscopy for visible haematuria', 'Transurethral resection of bladder tumour (TURBT) at central hospital for diagnosis, staging and initial treatment', 'EXPEDITED — visible haematuria with a bladder mass is cancer until proven otherwise', 'No diagnostic alternative to resection/biopsy; palliative haemostatic measures (irrigation, fulguration) for the unfit with uncontrolled bleeding', 'In Zimbabwe schistosomiasis-associated squamous carcinoma remains relevant alongside urothelial carcinoma — ask about haematuria history and bilharzia exposure; muscle must be present in the resection specimen for staging; upper tract imaging completes the haematuria work-up'),
  ('PAEDIATRIC_SURGERY', 'IND-PS-01', 'Inguinal hernia in infancy and childhood', 'Inguinal herniotomy (high ligation of the patent processus vaginalis) — no mesh, no floor repair in children', 'EXPEDITED — infants under 1 year soon after diagnosis (incarceration risk highest); EMERGENCY if irreducible', 'None — paediatric inguinal hernias do not resolve and incarceration threatens both bowel and testis; watchful waiting is not a paediatric option as it can be for adults', 'Attempt taxis (gentle reduction with analgesia) for the incarcerated but non-toxic infant, then repair on the same admission once oedema settles; neonates and ex-premature infants need anaesthetic capability — route to a centre with paediatric anaesthesia'),
  ('PAEDIATRIC_SURGERY', 'IND-PS-02', 'Infantile hypertrophic pyloric stenosis', 'Ramstedt pyloromyotomy after full correction of dehydration and hypochloraemic hypokalaemic alkalosis', 'URGENT surgery on a NON-urgent clock — operate only after biochemical correction, typically 24–48 hours of fluid therapy; the emergency is the resuscitation, never the knife', 'None curative — atropine regimens are described but prolonged, less reliable, and not the regional standard; nasogastric feeding does not correct the obstruction', 'Diagnosis by test feed (visible peristalsis, palpable olive) with ultrasound confirmation where available; anaesthetising an uncorrected alkalotic infant risks apnoea — the correction gate is absolute'),
  ('PAEDIATRIC_SURGERY', 'IND-PS-03', 'Ileocolic intussusception', 'Non-operative reduction first (air or hydrostatic enema under imaging where service exists); laparotomy with manual reduction or resection for failed reduction, peritonitis, or perforation', 'EMERGENCY — reduce or operate on presentation; delay converts reducible bowel to gangrene', 'Enema reduction IS the first-line treatment where safe (stable child, no peritonitis, no free air) and succeeds in the majority; recurrence after enema reduction occurs and warrants re-presentation advice', 'Peritonitis, shock, or free air contraindicate enema and mandate laparotomy; a pathological lead point becomes more likely in older children and in recurrence — resect when found; late presentation with gangrene is common regionally, so resection readiness (and blood) accompany every intussusception laparotomy'),
  ('PAEDIATRIC_SURGERY', 'IND-PS-04', 'Anorectal malformation (neonate with absent or abnormal anus)', 'Divided sigmoid colostomy in the neonatal period for high malformations; primary anoplasty for low lesions with visible perineal fistula per experienced assessment; definitive posterior sagittal anorectoplasty (PSARP) later at specialist centre', 'EMERGENCY — decompression decision within the first 24–48 hours of life before obstruction and sepsis supervene', 'None — an unvented high malformation is lethal; the only choices are which operation and where', 'Examine perineum in good light after 24 hours (fistula may declare late); screen for associated anomalies (cardiac, renal, oesophageal — VACTERL pattern); cross-table lateral radiograph aids level assessment; colostomy is a life-saving district-capable operation — do not hold a neonate for transfer that decompression could make safe'),
  ('PAEDIATRIC_SURGERY', 'IND-PS-05', 'Hirschsprung disease (confirmed or strongly suspected chronic neonatal/infant obstruction)', 'Rectal washouts as a bridge; levelling colostomy where washouts fail or enterocolitis threatens; definitive pull-through at paediatric surgical centre after biopsy confirmation', 'EXPEDITED — EMERGENCY if Hirschsprung-associated enterocolitis (distension, fever, foul explosive stools) supervenes', 'Regular rectal washouts alone can maintain some infants to definitive surgery — a genuine bridge, not a destination; delayed diagnosis presenting as chronic constipation still needs biopsy-confirmed pathway', 'Diagnosis rests on rectal biopsy (suction or full-thickness) — commit to obtaining it before definitive surgery; enterocolitis is the killer complication and trumps all scheduling'),
  ('PAEDIATRIC_SURGERY', 'IND-PS-06', 'Undescended testis (cryptorchidism) persisting after 6 months of age', 'Inguinal orchidopexy, ideally between 6 and 18 months of age', 'ELECTIVE with a target window — schedule so surgery completes before 18–24 months where the child presents in time; late presenters still benefit and are listed on diagnosis', 'No effective non-surgical therapy in routine practice; observation beyond 6 months is not justified — spontaneous descent after that age is rare and fertility potential declines', 'Distinguish retractile testis (normal, needs only follow-up) from truly undescended by careful examination; impalpable testis needs examination under anaesthesia and possible laparoscopy at a centre; bilateral impalpable testes in a newborn raise disorders of sex development — urgent endocrine referral, not routine listing'),
  ('PAEDIATRIC_SURGERY', 'IND-PS-07', 'Malrotation presenting with bilious vomiting (with or without confirmed volvulus)', 'Emergency laparotomy and Ladd''s procedure; resection of non-viable midgut where volvulus has progressed', 'EMERGENCY — bilious vomiting in a neonate is a surgical emergency until malrotation with volvulus is excluded; the whole midgut is at stake', 'Upper gastrointestinal contrast study to confirm rotation only in the stable child where it does not delay surgery; the sick neonate with bilious vomiting and tenderness goes to theatre on clinical grounds', 'Minutes-to-hours pathology: an infarcted midgut is unsurvivable in most settings — escalation and transfer decisions must be made at first presentation, and district teams should decompress, resuscitate and move fast rather than observe overnight'),
  ('PAEDIATRIC_SURGERY', 'IND-PS-08', 'Typhoid ileal perforation in a child', 'Laparotomy, peritoneal toilet, and repair of perforation(s) — primary two-layer closure or wedge resection; ileostomy for the unstable child or multiple perforations', 'EMERGENCY — after focused resuscitation; source control cannot wait for full physiological normalisation', 'None once perforation has occurred; uncomplicated typhoid is medical — the surgical indication is the perforated or peritonitic child', 'Endemic-region reality: suspect in any child with peritonitis after a febrile illness; walk the whole distal ileum — perforations are frequently multiple; continue antimicrobials as treatment; nutrition and electrolytes drive survival as much as the operation'),
  ('SURGICAL_ONCOLOGY', 'IND-SO-01', 'Suspected soft tissue sarcoma (mass over 5 cm, deep to fascia, enlarging, or recurrent after previous excision)', 'Image, then core needle (or planned incisional) biopsy along the future resection axis, then planned wide local excision at central hospital after MDT — never a shell-out excision of an unbiopsied deep mass', 'EXPEDITED — biopsy within 2 weeks of suspicion; unplanned excision converts a curable tumour into a contaminated field', 'No curative alternative for resectable sarcoma; radiotherapy and chemotherapy are adjuncts or palliative options per subtype at MDT; observation only for the frail with indolent, asymptomatic disease after explicit MDT decision', 'The commonest fatal error is enucleating a "lipoma" that was a sarcoma — the biopsy-first gate exists for this; biopsy track placement matters because it must be excised en bloc later; imaging (MRI where accessible, otherwise best available) before biopsy'),
  ('SURGICAL_ONCOLOGY', 'IND-SO-02', 'Cutaneous melanoma (biopsy-proven)', 'Wide local excision with margins determined by Breslow thickness; sentinel node biopsy where technique available (central hospital); therapeutic node dissection for confirmed nodal disease', 'EXPEDITED — definitive excision within 4–6 weeks of diagnostic biopsy', 'None curative for the primary; systemic therapy per oncology access for advanced disease; amelanotic and acral (sole, palm, subungual) melanomas — the pattern most relevant to African patients — are diagnosed late, so suspicion must run higher, not lower', 'Diagnose with full-thickness excisional biopsy of the suspicious lesion with a narrow margin first — shave biopsies destroy staging; plantar lesions in the region deserve particular vigilance; document Breslow thickness as the margin-driving fact'),
  ('SURGICAL_ONCOLOGY', 'IND-SO-03', 'Persistent significant lymphadenopathy suspicious for lymphoma or metastatic carcinoma', 'Excisional (whole-node) biopsy of the most accessible representative node, specimen sent FRESH (unfixed) for lymphoma work-up where laboratory pathway allows, plus fixed specimen for histology', 'EXPEDITED — diagnosis within 2–4 weeks; treatment of lymphoma is time-sensitive and medical', 'Fine-needle aspiration triages (and diagnoses tuberculosis or metastatic carcinoma) but frequently cannot type lymphoma — a negative or inconclusive FNA of a persisting node does not close the question', 'In a high-HIV, high-TB setting the differential is tuberculosis versus lymphoma versus metastasis — send material for TB microscopy/culture/GeneXpert AND histology every time; choose cervical over inguinal nodes where possible (less reactive change); coordinate the fresh-specimen path with the laboratory before theatre'),
  ('SURGICAL_ONCOLOGY', 'IND-SO-04', 'Squamous cell carcinoma arising in a chronic wound, ulcer, scar or sinus (Marjolin ulcer)', 'Biopsy from ulcer edge (multiple quadrants), then wide local excision with reconstruction (graft/flap); amputation for extensive limb disease with bone or joint involvement; regional node assessment', 'EXPEDITED — these tumours are biologically aggressive despite their indolent-looking bed', 'None curative; radiotherapy per access for the inoperable; continued dressing care of an unbiopsied changing chronic wound is the failure mode to design against', 'Any chronic wound that changes — raised edge, new growth, contact bleeding, foul discharge — gets an edge biopsy; burns scars and chronic osteomyelitis sinuses are the classic regional substrates; plan reconstruction before excision so margins are not compromised by closure anxiety'),
  ('SURGICAL_ONCOLOGY', 'IND-SO-05', 'Malignant dysphagia or inoperable upper aerodigestive/oesophageal cancer requiring nutrition access', 'Feeding gastrostomy (open Stamm at district/central) or feeding jejunostomy; endoscopic stent where advanced endoscopy exists relieves dysphagia itself', 'EXPEDITED — nutrition failure compounds weekly; decide route within days of the palliative decision', 'Nasogastric feeding as a short bridge; oral supplementation while swallow persists; honest goals-of-care discussion is part of the indication — a gastrostomy feeds the patient but does not relieve the dysphagia or change the disease course', 'Confirm palliative intent at MDT before creating access; site the gastrostomy so it does not compromise a conduit if any curative option remains open; involve palliative care service at the same visit, not after'),
  ('SURGICAL_ONCOLOGY', 'IND-SO-06', 'Malignant large bowel obstruction in incurable disease', 'Palliative defunctioning loop colostomy (or ileostomy per level); endoscopic stent where colonic stenting exists for suitable left-sided lesions', 'URGENT — obstruction does not negotiate; surgery within 24–48 hours of the decision, after resuscitation', 'Venting nasogastric tube, fluids and anti-secretory palliation for the patient too frail for any intervention or with multilevel obstruction — a genuine palliative pathway to be chosen deliberately with the family, not by default', 'Confirm incurability and level of obstruction (imaging; multilevel small bowel obstruction from carcinomatosis often does NOT benefit from a stoma); the operation trades a laparotomy''s risks for months of symptom relief — senior, honest case selection is the entire art'),
  ('SURGICAL_ONCOLOGY', 'IND-SO-07', 'Fungating, bleeding, or septic locally advanced tumour (breast and soft tissue most commonly) in advanced disease', 'Palliative toilet excision (toilet mastectomy or debulking) for hygiene, bleeding and odour control after MDT confirms the goal is local control, not cure', 'EXPEDITED — quality-of-life deterioration is the clock; URGENT for major bleeding', 'Dressing regimens with charcoal/metronidazole-based odour control, haemostatic radiotherapy where accessible, and systemic therapy per oncology — surgery is one palliative tool among several and should win on merit, not reflex', 'Set expectations in writing: local control and dignity are the outcomes offered; flap or graft cover planned where excision leaves a defect; anaemia corrected; palliative care co-management documented'),
  ('ORTHOPAEDICS', 'IND-ORTH-01', 'Closed femoral shaft fracture (adult)', 'Antegrade intramedullary nailing (SIGN-type solid nail) or plate osteosynthesis', 'URGENT — stabilise within 24-48 hours where implant and theatre capacity allow', 'Skeletal traction (Perkins or balanced) for 6-10 weeks remains an acceptable definitive option where intramedullary implants are unavailable; accepts longer admission and higher malunion risk', 'AP and lateral radiographs including hip and knee; check ipsilateral neck of femur before nailing; district hospitals without implant stock apply traction and refer to provincial/central level; document neurovascular status before and after any manipulation'),
  ('ORTHOPAEDICS', 'IND-ORTH-02', 'Open tibial fracture (Gustilo-Anderson II-III)', 'Emergency wound excision (debridement), irrigation and external fixation', 'EMERGENCY — debridement as soon as physiologically possible, ideally within 12-24 hours of injury', 'None for the debridement itself; definitive bony management may be non-operative (cast after wound care) for low-grade injuries with stable patterns', 'IV antibiotics and tetanus prophylaxis at first contact; photograph wound then cover with saline dressing — no repeated ward inspections; Gustilo grade assigned in theatre, not in casualty; grade IIIB/IIIC or vascular involvement warrants central-level referral after damage-control fixation'),
  ('ORTHOPAEDICS', 'IND-ORTH-03', 'Displaced intracapsular neck of femur fracture in the older patient', 'Cemented or uncemented hemiarthroplasty (Austin Moore/Thompson where modular stems unavailable)', 'EXPEDITED — surgery within 48 hours of admission is associated with better survival and earlier mobilisation', 'Non-operative management (analgesia, early sitting) reserved for the non-ambulant or moribund patient after senior review; accepts non-union and persisting pain', 'Pelvis AP plus lateral hip radiograph; medical optimisation (anaemia, dehydration, delirium) must not delay surgery beyond 48 hours without documented reason; provincial/central level for arthroplasty; undisplaced fractures in younger patients considered for in-situ screw fixation instead'),
  ('ORTHOPAEDICS', 'IND-ORTH-04', 'Displaced supracondylar humerus fracture in a child (Gartland III)', 'Closed reduction and percutaneous K-wire fixation under image intensifier', 'URGENT — same-day surgery; immediate if pulseless or white hand', 'Gartland I and most II fractures: above-elbow cast in less than 90 degrees flexion with radiographic review at 1 week', 'Document radial pulse, capillary refill and median/radial/ulnar nerve function before and after reduction; a pink pulseless hand after reduction is observed closely, a white pulseless hand goes to theatre for exploration; no image intensifier on site means splint and transfer the same day'),
  ('ORTHOPAEDICS', 'IND-ORTH-05', 'Chronic osteomyelitis with radiologically mature sequestrum', 'Sequestrectomy and saucerisation with deep specimens for culture and histology', 'ELECTIVE — operate once the involucrum is sufficient to maintain structural continuity', 'Prolonged antibiotics alone rarely eradicate infection in the presence of a sequestrum; dressings and deferral are reasonable while awaiting involucrum maturity', 'Plain radiographs usually sufficient to plan surgery; premature sequestrectomy before involucrum formation risks pathological fracture and segmental defect; send tissue, not sinus swabs, for culture; consider TB and sickle cell disease in the differential'),
  ('ORTHOPAEDICS', 'IND-ORTH-06', 'Septic arthritis of the hip or knee', 'Emergency arthrotomy, joint lavage and drainage; aspiration for diagnosis first where feasible', 'EMERGENCY — irreversible cartilage damage begins within hours; operate the same day', 'Repeated large-bore needle aspiration plus IV antibiotics may be acceptable for the knee in early presentation with rapid response; the hip in a child is always surgical', 'Aspirate before antibiotics where this does not delay theatre; blood cultures and joint fluid for Gram stain, culture and cell count; in children exclude adjacent osteomyelitis; splint in position of function and start early physiotherapy once inflammation settles'),
  ('ORTHOPAEDICS', 'IND-ORTH-07', 'Idiopathic clubfoot (congenital talipes equinovarus) resistant residual equinus', 'Percutaneous Achilles tenotomy within the Ponseti casting programme', 'ELECTIVE — timed by the Ponseti sequence, usually after 4-6 corrective casts', 'Serial Ponseti casting alone corrects the deformity without tenotomy in a minority of feet; neglected older children need more extensive soft-tissue or bony surgery', 'Tenotomy is a district-level procedure under local anaesthesia in infants; post-tenotomy cast in maximal correction for 3 weeks then foot-abduction brace; counsel caregivers that bracing compliance to age 4 determines the result'),
  ('ORTHOPAEDICS', 'IND-ORTH-08', 'Acute compartment syndrome of the leg or forearm', 'Emergency open fasciotomy of all involved compartments (two-incision four-compartment release for the leg)', 'EMERGENCY — decompress within hours of diagnosis; do not wait for absent pulses', 'None once the diagnosis is made; elevation to heart level and splitting of all circumferential dressings/casts are immediate interim measures only', 'Clinical diagnosis: pain out of proportion and pain on passive stretch are the earliest signs; pulses are typically preserved until late; leave fasciotomy wounds open with planned relook at 48 hours; delayed presentation with a dead compartment may be better served by non-operative management or amputation — senior decision'),
  ('ENT', 'IND-ENT-01', 'Recurrent acute tonsillitis meeting frequency criteria', 'Tonsillectomy (cold steel dissection)', 'ELECTIVE — schedule at least 4-6 weeks after the last acute episode', 'Watchful waiting with episode-by-episode antibiotic treatment — frequency declines with age in many children; documented episode counts over 1-3 years justify surgery (around 7 in 1 year, 5/year over 2 years, or 3/year over 3 years)', 'Confirm episodes are clinician-documented, not parent-reported alone; screen for bleeding history and anaemia; district-level procedure where paediatric anaesthesia and overnight observation available; defer during active infection'),
  ('ENT', 'IND-ENT-02', 'Obstructive sleep-disordered breathing from adenotonsillar hypertrophy in a child', 'Adenotonsillectomy', 'EXPEDITED — witnessed apnoeas, failure to thrive or cor pulmonale features move the child up the list', 'Intranasal corticosteroid trial for mild symptoms with predominantly adenoidal obstruction; weight management where relevant in older children', 'Clinical diagnosis acceptable where sleep studies are unavailable — caregiver-witnessed apnoea plus tonsillar grade documented; assess for pulmonary hypertension (loud P2, ECG) in severe long-standing cases; such children need first-on-list surgery and overnight monitoring'),
  ('ENT', 'IND-ENT-03', 'Chronic suppurative otitis media with cholesteatoma', 'Mastoidectomy (canal wall down / modified radical where follow-up access is uncertain)', 'EXPEDITED — cholesteatoma is progressive; operate before intracranial or facial nerve complications', 'No effective non-operative cure; aural toilet and topical antibiotics only temporise discharge and do not arrest bone erosion', 'Otoscopy findings and any imaging documented; pure-tone audiometry (or at least voice/tuning-fork assessment) before surgery; facial nerve function recorded pre-operatively; refer to central level with otology capacity; canal-wall-down favoured where annual follow-up cannot be guaranteed'),
  ('ENT', 'IND-ENT-04', 'Suspected airway foreign body in a child', 'Rigid bronchoscopy and foreign body removal under general anaesthesia', 'EMERGENCY — complete obstruction is immediately life-threatening; even the stable child with a suggestive history goes to theatre the same day', 'None once suspicion is real; a normal chest radiograph does not exclude a radiolucent foreign body (groundnut aspiration is common) — history of a choking crisis is sufficient indication', 'Keep the child calm, upright, with caregiver present; avoid blind finger sweeps; district hospitals without rigid bronchoscopy transfer immediately with senior escort and airway-capable staff; unilateral wheeze or hyperinflation supports but is not required for the diagnosis'),
  ('ENT', 'IND-ENT-05', 'Peritonsillar abscess (quinsy)', 'Incision and drainage (or needle aspiration) under local anaesthesia, interval tonsillectomy if recurrent', 'URGENT — drain the same day; airway compromise or trismus preventing assessment escalates to theatre', 'Needle aspiration plus IV antibiotics is an acceptable first-line alternative to formal incision; antibiotics alone only for early peritonsillar cellulitis without pus', 'Drainage is a district-level bedside/clinic procedure in the cooperative adult; children usually need general anaesthesia; test-aspirate before incising; consider retropharyngeal or parapharyngeal extension when trismus and neck stiffness are marked — that patient is imaged and referred'),
  ('ENT', 'IND-ENT-06', 'Upper airway obstruction needing a surgical airway (tumour, bilateral cord palsy, prolonged intubation)', 'Tracheostomy (open surgical)', 'EMERGENCY when obstruction is acute; ELECTIVE when for prolonged ventilation or before major head-neck surgery', 'Trial of steroids/adrenaline nebulisation and non-invasive support for reversible causes; endotracheal intubation preferred first where achievable; cricothyroidotomy is the immediate rescue in cannot-intubate-cannot-oxygenate', 'Elective tracheostomy performed over an endotracheal tube in theatre; keep tube of one size smaller, dilators and suction at the bedside for 72 hours; first tube change at 5-7 days by an experienced clinician; district facilities keeping tracheostomised patients need trained cover on every shift'),
  ('ENT', 'IND-ENT-07', 'Chronic rhinosinusitis with nasal polyps failing medical therapy', 'Intranasal polypectomy (endoscopic where equipment available, snare polypectomy otherwise)', 'ELECTIVE — after an adequate trial of medical therapy', 'Intranasal corticosteroid spray for at least 3 months plus saline irrigation, with a short oral steroid course in severe obstruction — many patients avoid or defer surgery; polyps recur after surgery without ongoing steroid maintenance', 'Unilateral polyps, bleeding, or bony erosion are red flags for neoplasia — biopsy and imaging before any simple polypectomy; counsel on high recurrence rates; central-level referral for endoscopic sinus surgery with orbital/skull-base proximity'),
  ('ENT', 'IND-ENT-08', 'Deep neck space abscess (submandibular, parapharyngeal) with airway risk', 'External cervical incision and drainage with airway protection', 'EMERGENCY — the airway is secured first; drainage follows in the same sitting', 'IV antibiotics alone acceptable only for small collections in a stable patient under close observation with senior review; deterioration converts immediately to drainage', 'Anaesthetic team warned about difficult airway before induction; awake techniques or tracheostomy considered where trismus and swelling are severe; pus for culture including TB studies; look for a dental or foreign-body source and treat it in the same admission'),
  ('OPHTHALMOLOGY', 'IND-OPHT-01', 'Visually significant age-related cataract', 'Manual small-incision cataract surgery (MSICS) with posterior chamber intraocular lens', 'ELECTIVE — prioritise bilateral blindness (presenting VA worse than 3/60 in the better eye) and monocular patients', 'Updated refraction and improved lighting for early lens change; surgery deferred where the patient is visually satisfied — but counsel that dense white/brown cataracts become technically harder and complications rise', 'Visual acuity both eyes, pupil reactions (RAPD suggests retinal/optic nerve disease limiting benefit) and biometry (A-scan/keratometry) or documented standard-power IOL policy; MSICS favoured over phacoemulsification for dense cataracts and machine-scarce settings with equivalent outcomes; outreach lists batch district cases to visiting teams'),
  ('OPHTHALMOLOGY', 'IND-OPHT-02', 'Acute primary angle-closure glaucoma', 'Laser peripheral iridotomy where laser available; surgical peripheral iridectomy otherwise; fellow eye treated prophylactically', 'EMERGENCY — start medical pressure-lowering immediately; definitive iridotomy/iridectomy as soon as the cornea clears, ideally within days', 'Medical therapy alone (topical and systemic pressure-lowering agents) breaks the attack but does not remove the anatomical mechanism — recurrence is expected without iridotomy', 'Painful red eye, fixed mid-dilated pupil, hazy cornea, very high IOP; measure and record IOP; the FELLOW eye shares the anatomy and needs prophylactic treatment at the same referral — failure to treat the second eye is a recognised avoidable-blindness error'),
  ('OPHTHALMOLOGY', 'IND-OPHT-03', 'Primary open-angle glaucoma progressing despite maximal tolerated medical therapy', 'Trabeculectomy (augmented per local antimetabolite policy)', 'EXPEDITED — advancing field loss or non-affordability/non-availability of drops argues for earlier surgery', 'Continued topical therapy where affordable, available and demonstrably controlling pressure; laser trabeculoplasty where equipment exists; in Zimbabwean practice chronic drop supply is often unreliable, which legitimately shifts the balance towards earlier surgery', 'Document IOP series, cup-disc ratio and visual fields (or disc photos/clinical estimate where perimetry unavailable); counsel that surgery preserves remaining vision and does not restore lost field; lifelong follow-up of the bleb required; central or provincial eye-unit procedure'),
  ('OPHTHALMOLOGY', 'IND-OPHT-04', 'Pterygium encroaching the visual axis or repeatedly inflamed', 'Pterygium excision with conjunctival autograft', 'ELECTIVE — earlier where advancing towards the visual axis on serial review', 'Lubricants, UV-protective sunglasses and episodic anti-inflammatory drops for small static pterygia; observation with photographic/measured serial records', 'Bare-sclera excision alone has unacceptable recurrence and should not be used; conjunctival autograft materially lowers recurrence; high UV exposure makes recurrence counselling essential; district-level procedure under local anaesthesia where trained'),
  ('OPHTHALMOLOGY', 'IND-OPHT-05', 'Open globe injury (penetrating/perforating eye injury)', 'Primary globe repair under general anaesthesia', 'EMERGENCY — repair within 24 hours; protect the eye with a rigid shield (no pad, no pressure) pending theatre', 'None; delayed or no repair leads to infection, tissue extrusion and loss of the eye; in a destroyed eye with no light perception, primary repair is still generally preferred over primary enucleation, with enucleation as a considered secondary decision', 'Record visual acuity (even light perception) before anaesthesia — it is the strongest prognostic factor; no eye ointment, no pressure on the globe, nil by mouth, tetanus prophylaxis and systemic antibiotics; transfer with shield in place to a centre with ophthalmic theatre; warn about sympathetic ophthalmia during counselling'),
  ('OPHTHALMOLOGY', 'IND-OPHT-06', 'Retinoblastoma with intraocular disease (leukocoria/strabismus presentation)', 'Enucleation with long optic-nerve stump; globe to histopathology in fresh state per protocol', 'URGENT — days matter; delay risks extraocular spread which sharply worsens survival', 'Eye-salvage chemotherapy protocols exist for selected early bilateral disease at national referral level; for the common late unilateral presentation enucleation is life-saving and delay for second opinions costs lives', 'Any child with a white pupil reflex is referred the same week; examine the fellow eye under anaesthesia; family counselling addresses the strong survival benefit of timely enucleation and the availability of a prosthesis; genetic implications for siblings discussed at referral centre'),
  ('OPHTHALMOLOGY', 'IND-OPHT-07', 'Trachomatous trichiasis (lashes touching the globe)', 'Bilamellar tarsal rotation (or Trabut) lid surgery', 'EXPEDITED — each week of lash-cornea contact adds abrasion and scarring risk', 'Epilation (repeated lash removal) is an interim measure for minor trichiasis or surgery refusal and is WHO-acceptable for one or two peripheral lashes; it does not correct the entotropic lid', 'A trained cataract surgeon or dedicated TT surgeon can deliver this at district/outreach level under local anaesthesia; check corneal clarity and document acuity — co-existing corneal opacity changes visual prognosis counselling; community screening links (SAFE strategy) recorded'),
  ('OPHTHALMOLOGY', 'IND-OPHT-08', 'Blind painful eye or endophthalmitis unresponsive to treatment', 'Evisceration (or enucleation where malignancy cannot be excluded)', 'ELECTIVE for the quiescent blind painful eye; URGENT where fulminant infection threatens orbital spread', 'Cyclodestructive procedures, retrobulbar alcohol/chlorpromazine or long-term topical therapy can palliate pain in some blind eyes and are legitimate patient-preference alternatives', 'Ultrasound B-scan (where available) or careful clinical assessment to exclude intraocular tumour BEFORE evisceration — evisceration is contraindicated if malignancy is possible; discuss prosthetic shell fitting; histology sent in all cases'),
  ('VASCULAR', 'IND-VASC-01', 'Acute limb ischaemia (embolic or thrombotic)', 'Femoral (or brachial) embolectomy with balloon catheter; fasciotomy considered after reperfusion', 'EMERGENCY — muscle tolerates roughly 6 hours of warm ischaemia; anticoagulate on diagnosis and move to theatre', 'Systemic anticoagulation alone for non-threatened limbs (Rutherford I) with close serial examination; catheter-directed thrombolysis only where an interventional service exists (central level)', 'Document the 6 Ps and motor/sensory status — sensory loss and muscle tenderness mark a threatened limb; identify an embolic source (AF, valve disease) for later management; irreversible ischaemia (fixed mottling, rigid muscles) is treated by amputation, not revascularisation'),
  ('VASCULAR', 'IND-VASC-02', 'Wet gangrene or spreading diabetic foot sepsis', 'Urgent surgical debridement/open amputation of the septic part; staged definitive closure or higher amputation', 'EMERGENCY — source control the same day; sepsis from a dead extremity does not respond to antibiotics alone', 'None for wet gangrene; dry, well-demarcated gangrene without infection may be allowed to auto-demarcate before definitive elective amputation', 'Resuscitate and control glucose alongside, never instead of, surgery; probe-to-bone and radiographs for osteomyelitis; culture deep tissue; Wagner/other grade documented; involve rehabilitation early when amputation likely'),
  ('VASCULAR', 'IND-VASC-03', 'Chronic limb-threatening ischaemia with rest pain or tissue loss, limb unsalvageable or no revascularisation option', 'Major lower-limb amputation (below-knee preferred whenever the knee can be saved)', 'URGENT for uncontrolled sepsis or intractable rest pain; EXPEDITED otherwise', 'Revascularisation (open bypass or endovascular at central level) must be considered and documented as unavailable or unsuitable before major amputation; analgesia-centred palliation for the patient unfit for any surgery', 'Level selection is clinical (skin quality, warmth, bleeding at surgery) supplemented by Doppler pressures where available; preserve the knee whenever viable — below-knee amputees rehabilitate to walking far more often; prosthetics referral pathway noted at consent'),
  ('VASCULAR', 'IND-VASC-04', 'End-stage renal disease approaching or on haemodialysis', 'Autogenous arteriovenous fistula (radiocephalic first choice, brachiocephalic next)', 'EXPEDITED — fistulae need around 6 weeks to mature; create ahead of dialysis need where possible', 'Tunnelled or temporary central venous catheters bridge to fistula maturation but carry higher infection and stenosis burden; peritoneal dialysis is a system-level alternative for selected patients', 'Preserve forearm veins in CKD patients (no cannulation of the non-dominant cephalic vein — flag on the record); clinical vein/artery assessment with tourniquet, duplex mapping where available; Allen test documented; distal-first strategy preserves proximal sites for the future'),
  ('VASCULAR', 'IND-VASC-05', 'Symptomatic varicose veins with skin changes or healed/active venous ulcer', 'High saphenous ligation with stripping of the great saphenous vein and stab avulsions', 'ELECTIVE — after a documented period of conservative therapy unless ulceration progresses', 'Graduated compression therapy (bandaging then stockings) is first-line and definitive for many, and remains the mainstay for ulcer healing; endovenous ablation is an alternative only where equipment exists', 'Confirm deep venous patency clinically/handheld Doppler (stripping a collateral around an occluded deep system is harmful); document saphenofemoral reflux; treat active ulcer with compression first, surgery to prevent recurrence; district-level operation'),
  ('VASCULAR', 'IND-VASC-06', 'Penetrating or blunt vascular injury with hard signs', 'Immediate operative exploration and repair (primary repair, vein patch or reversed vein interposition graft); damage-control shunt where transfer needed', 'EMERGENCY — hard signs (pulsatile bleeding, expanding haematoma, absent distal pulse, thrill/bruit, ischaemia) mandate theatre without further imaging delay', 'Observation with serial examination only for soft signs with normal perfusion; angiography/CT where haemodynamically stable and diagnosis unclear at a centre that has it', 'Control haemorrhage with direct pressure, not blind clamping; document ischaemia time from injury; temporary intravascular shunting plus external fixation is the district damage-control pattern before central transfer; fasciotomy is liberally added after prolonged ischaemia'),
  ('VASCULAR', 'IND-VASC-07', 'Abdominal aortic aneurysm at threshold size or symptomatic', 'Open aneurysm repair with prosthetic graft at central level (endovascular repair rarely available)', 'EXPEDITED for asymptomatic aneurysm ≥5.5 cm (or rapid growth); EMERGENCY for rupture or symptomatic aneurysm', 'Surveillance ultrasound for aneurysms below threshold with cardiovascular risk-factor treatment (smoking cessation, blood pressure control); the unfit patient may be managed conservatively after documented shared decision', 'Ultrasound for surveillance; CT angiography for operative planning; refer to central vascular unit — do not open an aneurysm at a facility without vascular capability except free rupture with no transfer option; anaesthetic/ICU capacity is part of the listing decision'),
  ('VASCULAR', 'IND-VASC-08', 'Chronic venous or mixed leg ulcer failing compression, with slough/biofilm burden', 'Ulcer debridement with split-skin grafting once the bed granulates; compression continued for life', 'ELECTIVE — grafting timed to a clean granulating bed', 'Continued compression bandaging with dressings achieves healing in the majority without surgery; pinch grafting at district level is a low-resource alternative to formal split-skin grafting', 'Exclude arterial insufficiency before compression (palpable pulses or ABI > 0.8); biopsy any ulcer with raised/everted edges or atypical features — Marjolin transformation and other malignancies present as non-healing ulcers; document ulcer measurements serially'),
  ('NEUROSURGERY', 'IND-NEUR-01', 'Acute extradural haematoma with mass effect or deterioration', 'Craniotomy and evacuation; exploratory burr hole at district level only as damage control before immediate transfer', 'EMERGENCY — the lucid-interval patient who deteriorates is salvageable only with evacuation within hours', 'Close neuro-observation without surgery only for small collections (thin, minimal shift) in a fully conscious patient at a centre able to re-image and operate immediately on deterioration', 'CT where available; deteriorating patient with lateralising signs and no CT access justifies an ipsilateral temporal exploratory burr hole by a trained generalist while transfer is arranged; document GCS serially with times; airway management precedes everything'),
  ('NEUROSURGERY', 'IND-NEUR-02', 'Chronic subdural haematoma with progressive deficit or confusion', 'Burr hole drainage and irrigation (one or two burr holes), subdural drain where stocked', 'URGENT — days, not weeks; earlier with depressed conscious level', 'Observation with serial imaging for thin asymptomatic collections; steroid therapy is not an established substitute for drainage in symptomatic collections', 'Typically elderly or alcohol-related, often trivial/no remembered trauma; correct coagulopathy and stop/reverse anticoagulants before surgery; counsel about recurrence (roughly one in ten) requiring re-drainage; performable at provincial level by trained general surgeons'),
  ('NEUROSURGERY', 'IND-NEUR-03', 'Infant hydrocephalus (post-infectious, post-haemorrhagic or aqueduct stenosis)', 'Ventriculoperitoneal shunt insertion; endoscopic third ventriculostomy (with choroid plexus cauterisation) at centres with endoscopy for suitable anatomy', 'EXPEDITED — progressive head growth and raised pressure damage the developing brain; list within weeks, sooner with rapid progression', 'Serial monitoring alone only for arrested (non-progressive) ventriculomegaly with normal development; medical therapy has no durable role', 'Serial head circumference plotted against the growth standard is the core district surveillance tool; ultrasound through the open fontanelle for ventricular size; exclude active infection (CSF sampling) before shunting; caregiver education on shunt-failure signs is part of the operation''s consent'),
  ('NEUROSURGERY', 'IND-NEUR-04', 'Compound (open) depressed skull fracture', 'Wound debridement, elevation of the depressed segment and dural repair', 'URGENT — operate within 24 hours to reduce infection risk; immediately if underlying haematoma with mass effect', 'Simple (closed) depressed fractures without significant depression, deficit or cosmetic concern may be managed non-operatively with observation', 'Antibiotics and tetanus prophylaxis from arrival; assess for CSF leak and brain matter in the wound; seizure prophylaxis decision documented; imaging (CT preferred, tangential radiographs where CT absent) to plan elevation; transfer to a centre able to manage dural tears'),
  ('NEUROSURGERY', 'IND-NEUR-05', 'Open myelomeningocele in the newborn', 'Early operative closure of the defect; subsequent hydrocephalus surveillance (shunt frequently needed later)', 'URGENT — closure ideally within 48-72 hours of birth to reduce infection of the exposed neural placode', 'No effective non-operative route to closure; comfort-focused palliation is a senior, family-shared decision reserved for lethal associated anomalies', 'Cover the defect with sterile saline-moistened non-adherent dressing and cling film at birth, nurse prone, avoid latex; record leg movement and anal tone as baseline; refer to paediatric surgical/neurosurgical centre without delay; folate-programme notification and future-pregnancy counselling recorded'),
  ('NEUROSURGERY', 'IND-NEUR-06', 'Cerebral abscess with mass effect', 'Burr hole aspiration (image-guided where possible), repeated as needed; excision for refractory/multiloculated posterior fossa lesions', 'URGENT — aspirate for diagnosis, decompression and culture; EMERGENCY if deteriorating conscious level', 'High-dose IV antibiotics alone for small (under ~2.5 cm) abscesses or cerebritis stage with close imaging surveillance — accepting that failure to shrink mandates aspiration', 'Search for and treat the source: middle ear, mastoid, sinuses, dental sepsis, cyanotic heart disease, HIV-related disease (toxoplasmosis is the key differential — many centres treat empirically first when imaging is typical and serology supports); avoid lumbar puncture with mass effect'),
  ('NEUROSURGERY', 'IND-NEUR-07', 'Cauda equina syndrome from lumbar disc prolapse', 'Urgent lumbar decompression (laminectomy/discectomy) at spine-capable centre', 'EMERGENCY — decompress as soon as possible, ideally within 24-48 hours of sphincter symptom onset', 'None once the syndrome is established; analgesia and physiotherapy apply only to sciatica WITHOUT red flags', 'Bilateral sciatica, saddle anaesthesia, painless urinary retention/overflow, reduced anal tone — examine and document perianal sensation, anal tone and a post-void bladder assessment; MRI where reachable must not introduce days of delay; transfer discussion with the spine centre the same day'),
  ('NEUROSURGERY', 'IND-NEUR-08', 'Unstable thoracolumbar or cervical spine injury with or without deficit', 'Reduction/stabilisation (traction, halo, or operative instrumentation at central level); pressure-area and bladder programme from day one', 'EXPEDITED — early transfer to the spinal service; EMERGENCY where a deteriorating deficit suggests ongoing compression', 'Non-operative bracing/log-roll nursing for stable fracture patterns; complete injuries after the acute phase are frequently managed non-operatively where instrumentation is scarce, with rehabilitation as the active treatment', 'Full ATLS spine precautions from scene through transfer; neurological level charted on a standard assessment sheet with date/time; catheterise early; the district package that changes outcomes is pressure care 2-hourly, bladder/bowel management, and VTE prophylaxis — start before transfer, not after'),
  ('CARDIOTHORACIC', 'IND-CTS-01', 'Traumatic haemothorax or pneumothorax requiring drainage', 'Intercostal chest drain insertion (safe-triangle, blunt technique); thoracotomy reserved for massive or continuing haemorrhage', 'EMERGENCY — tension physiology is decompressed immediately (needle/finger) before drain placement', 'Observation with repeat imaging for a small, stable, asymptomatic simple pneumothorax; aspiration for selected primary spontaneous pneumothorax', 'A chest drain is a district-level life-saving skill; initial drainage over ~1500 ml or ongoing loss over ~200 ml/hour for 2-4 hours defines massive haemothorax and triggers thoracotomy-capable referral; autotransfusion of drained blood is a recognised resource-adapted option where kits exist'),
  ('CARDIOTHORACIC', 'IND-CTS-02', 'Empyema thoracis (pleural sepsis)', 'Chest drainage for exudative/fibrinopurulent stages; decortication for the organised fibrothorax with trapped lung', 'URGENT for drainage of pleural sepsis; ELECTIVE (but not indefinitely deferred) for decortication once organised', 'Antibiotics plus repeated aspiration only in the earliest exudative stage; intrapleural fibrinolytics where stocked may avoid surgery in the fibrinopurulent stage', 'Stage the empyema (exudative, fibrinopurulent, organised) on ultrasound/radiograph and drainage findings; always send fluid for TB studies — tuberculous empyema is common and changes management; a child''s empyema drains earlier and decorticates less often; persistent sepsis despite a well-placed drain escalates to surgery'),
  ('CARDIOTHORACIC', 'IND-CTS-03', 'Pericardial effusion with tamponade physiology (tuberculous, malignant or purulent)', 'Echocardiography-guided pericardiocentesis for immediate relief; subxiphoid pericardial window for recurrent or purulent effusions', 'EMERGENCY for tamponade; URGENT window for reaccumulation or pus', 'Medical therapy of the cause (anti-TB therapy per national programme, with steroid adjunct per guideline) without drainage only for small effusions without haemodynamic effect', 'Beck triad is late — rely on tachycardia, raised venous pressure, pulsus paradoxus and echo; send pericardial fluid for TB microscopy/culture and cytology; purulent pericarditis mandates surgical drainage, not needle alone; document baseline and post-drainage haemodynamics'),
  ('CARDIOTHORACIC', 'IND-CTS-04', 'Chronic constrictive pericarditis (usually tuberculous)', 'Pericardiectomy at the national cardiothoracic centre', 'EXPEDITED — progressive right-heart failure worsens operative risk; refer before cachexia and hepatic congestion are advanced', 'Anti-TB therapy alone may suffice for early effusive-constrictive disease; diuretics palliate but do not alter the constriction', 'Suspect in right-heart failure with clear lungs, raised JVP and a history of TB/pericardial effusion; echo, chest radiograph (calcification) support the diagnosis; complete or continue anti-TB therapy per programme around surgery; operative mortality is real and is part of consent at the referral centre'),
  ('CARDIOTHORACIC', 'IND-CTS-05', 'Post-tuberculous destroyed lung or chronic lung abscess/bronchiectasis with recurrent haemoptysis or sepsis', 'Lobectomy or pneumonectomy at the national thoracic centre after physiological assessment', 'ELECTIVE — timed between sepsis/haemoptysis episodes; URGENT referral after massive haemoptysis', 'Prolonged antibiotics, postural drainage and physiotherapy control symptoms in many; bronchial artery embolisation for haemoptysis where interventional radiology exists; aspergilloma may be observed if bleeding is minor and reserves poor', 'Confirm sputum conversion/absence of active TB where possible; CT and bronchoscopy for planning; assess contralateral lung function (spirometry, exercise tolerance) — resection in poor reserve trades sepsis for respiratory failure; massive haemoptysis is nursed affected-side-down pending transfer'),
  ('CARDIOTHORACIC', 'IND-CTS-06', 'Severe rheumatic mitral valve disease with symptoms', 'Referral for valve intervention: closed/percutaneous valvotomy for suitable pure stenosis; valve repair/replacement at cardiac-surgical referral (regional where national capacity absent)', 'EXPEDITED — symptomatic severe disease, pulmonary hypertension or AF mark the window closing', 'Medical therapy (rate control, diuretics, anticoagulation for AF) and secondary rheumatic-fever prophylaxis per national protocol palliate and slow recurrence but do not correct the lesion', 'Echocardiographic severity and valve-morphology scoring decide valvotomy suitability; ensure secondary penicillin prophylaxis is running regardless of surgical decision; anticoagulation counselling (monitoring access, pregnancy implications) is central to the mechanical-valve decision in a rural patient; document NYHA class serially'),
  ('CARDIOTHORACIC', 'IND-CTS-07', 'Recurrent or persistent spontaneous pneumothorax', 'Thoracotomy/VATS bullectomy with pleurodesis (surgical abrasion or talc per unit practice)', 'ELECTIVE — after the second ipsilateral episode, first episode in high-risk occupations, or non-resolving air leak beyond 5-7 days', 'Observation or drain alone for a first uncomplicated episode; chemical pleurodesis via the drain for patients unfit for surgery', 'Exclude secondary causes prevalent locally — TB, Pneumocystis-associated pneumothorax in advanced HIV (these behave differently and need cause-directed care); counsel against diving and note flying restrictions until resolution confirmed'),
  ('CARDIOTHORACIC', 'IND-CTS-08', 'Patent ductus arteriosus in a child with failure to thrive or heart failure', 'Surgical ligation/division of the duct at the national cardiac centre (device closure where catheter service available)', 'EXPEDITED — repair before irreversible pulmonary vascular disease; EMERGENCY-level priority in the infant failing medical therapy', 'Medical heart-failure therapy as a bridge; small haemodynamically insignificant ducts may be surveilled; once Eisenmenger physiology is established, closure is contraindicated — this is the tragedy late referral produces', 'Continuous murmur with bounding pulses in a thriving-poorly child; echocardiography confirms and grades shunt; exclude duct-dependent lesions before any closure decision; endocarditis prophylaxis counselling while awaiting repair'),
  ('MAXILLOFACIAL', 'IND-MAXF-01', 'Displaced mandibular fracture with malocclusion', 'Open reduction and internal fixation with miniplates; closed reduction with maxillomandibular fixation (arch bars/eyelet wires) where plates are unavailable', 'URGENT — fix within days; earlier for open-into-mouth fractures (most parasymphyseal/body fractures are compound via the tooth socket)', 'Closed reduction and 4-6 weeks of maxillomandibular fixation remains a fully defensible definitive treatment where plating stock or expertise is absent; soft diet alone for favourable undisplaced fractures with intact occlusion', 'Occlusion is the reduction gauge — document pre-injury occlusion and current bite; orthopantomogram plus PA mandible (or two views at right angles); antibiotics for compound fractures; a tooth in the fracture line is removed only if fractured, infected or preventing reduction; wire cutters must accompany any MMF patient'),
  ('MAXILLOFACIAL', 'IND-MAXF-02', 'Ludwig angina (bilateral submandibular/sublingual space cellulitis)', 'Airway-first management, then bilateral submandibular decompression and drainage with removal of the causative tooth', 'EMERGENCY — this kills by airway obstruction; the airway plan precedes any incision', 'IV antibiotics with intensive observation only in the earliest cellulitic phase without floor-of-mouth elevation or voice change, in a unit able to secure the airway immediately on deterioration', 'Anaesthesia forewarned: awake fibreoptic intubation or tracheostomy under local anaesthesia are the recognised routes — conventional induction may be impossible; drain both sides even if pus is scanty (decompression matters); dental source removal in the same sitting; diabetes and HIV status checked'),
  ('MAXILLOFACIAL', 'IND-MAXF-03', 'Acute odontogenic abscess (submandibular, buccal, canine space)', 'Incision and drainage (intraoral or extraoral by space involved) with extraction of the causative tooth', 'URGENT — same-day drainage; antibiotics are adjunctive, not a substitute for source control', 'Antibiotics and review within 24-48 hours only for cellulitis without a drainable collection; extraction alone may suffice where the abscess points through the socket', 'Trismus, dysphagia, floor-of-mouth swelling or voice change escalate the case towards the deep-space/Ludwig pathway; drain dependent, leave a wick/corrugated drain; district-level procedure; recurrent presentations flag for dental service linkage and glycaemic screening'),
  ('MAXILLOFACIAL', 'IND-MAXF-04', 'Zygomatic complex fracture with depression or functional deficit', 'Gillies temporal lift (with fixation only where unstable); ORIF for comminuted/unstable patterns at referral level', 'EXPEDITED — elevate within 10-14 days, before the fragments consolidate in malposition', 'No treatment for undisplaced fractures without diplopia, trismus or cosmetic deformity — review at one week confirms stability', 'Check and record eye signs before and after: acuity, diplopia, infraorbital numbness; retrobulbar haemorrhage after reduction is the sight-threatening emergency to warn staff about; occipitomental radiographs suffice where CT absent; advise no nose-blowing (orbital emphysema)'),
  ('MAXILLOFACIAL', 'IND-MAXF-05', 'Le Fort middle-third facial fracture with malocclusion or mobility', 'Reduction and fixation (MMF-based reduction with suspension/plating per available hardware) at maxillofacial referral level', 'EXPEDITED — after airway, haemorrhage and neurosurgical priorities; definitive fixation within 1-2 weeks', 'Conservative management with soft diet for minimally displaced fractures with acceptable occlusion in the frail', 'Classify Le Fort I/II/III by mobility examination and imaging; CSF rhinorrhoea and cribriform involvement route through the neurosurgical/base-of-skull discussion first; massive midface bleeding responds to reduction plus anterior-posterior packing; document occlusion and infraorbital sensation'),
  ('MAXILLOFACIAL', 'IND-MAXF-06', 'Cleft lip and/or palate in infancy', 'Staged repair at the specialist centre: lip repair around 3-6 months (rule-of-tens fitness), palate repair around 9-18 months for speech', 'ELECTIVE — but ENROLMENT IS URGENT at birth: feeding support and the surgical pathway start in week one', 'None for the cleft itself; feeding adaptation (upright posture, modified teats/cup feeding) is the essential bridge to surgical age; unrepaired clefts carry lifelong speech and social cost', 'Weight-gain surveillance decides operative timing (classical fitness thresholds around 10 weeks/10 lb/Hb 10 for lip); check for associated anomalies and hearing surveillance (palatal clefts and middle-ear effusion travel together); outreach cleft lists and mission-partner programmes are legitimate delivery channels recorded on the pathway'),
  ('MAXILLOFACIAL', 'IND-MAXF-07', 'Temporomandibular joint ankylosis (post-traumatic or post-infective)', 'Gap or interpositional arthroplasty with aggressive post-operative mouth-opening physiotherapy; costochondral graft consideration in the growing child', 'ELECTIVE at referral level — but childhood cases are prioritised for growth and airway reasons', 'No effective non-operative correction of true bony ankylosis; jaw-stretching devices apply only to fibrous limitation and post-operative maintenance', 'Usually presents as progressive mouth-opening restriction after childhood trauma or otitis-related infection; assess for sleep-apnoea symptoms and mandibular retrusion; CT where available for planning; counsel explicitly that re-ankylosis follows if physiotherapy lapses — family engagement is part of the indication'),
  ('MAXILLOFACIAL', 'IND-MAXF-08', 'Ameloblastoma or large odontogenic tumour of the mandible', 'Segmental or marginal mandibular resection with safety margin and reconstruction (plate with or without bone graft) at the central maxillofacial unit', 'EXPEDITED — benign but relentlessly destructive; large lesions cost more mandible with every month of delay', 'Enucleation/curettage accepted only for unicystic variants in selected cases, with a documented higher recurrence trade-off; aspiration/marsupialisation are temporising for cystic lesions awaiting definitive listing', 'Biopsy before resection — keratocysts, giant-cell lesions and malignancy change the plan; orthopantomogram and CT for margins; plan reconstruction and dental rehabilitation at the same consultation; late massive presentations are common — airway and nutrition assessment on referral'),
  ('PLASTICS', 'IND-PLAS-01', 'Deep partial-thickness or full-thickness burn (over ~10% TBSA, or any depth over joints, hands, face, perineum)', 'Early tangential excision and split-thickness skin grafting once resuscitated and stable', 'URGENT — excise and graft within days of demarcation; delayed grafting means infection, contracture and catabolism', 'Dressing-based healing (moist antimicrobial dressings) is appropriate for superficial partial-thickness burns and remains the pragmatic route where theatre/blood/graft capacity is saturated — at the accepted cost of slower healing and more scarring', 'Accurate %TBSA by Lund-Browder (children) or rule-of-nines; resuscitation per weight/area formula precedes any surgery; haemoglobin and nutrition optimised — excision bleeds; hand/face/perineal and large paediatric burns referred to the burns unit; document burn depth serially since burns declare over 48-72 hours'),
  ('PLASTICS', 'IND-PLAS-02', 'Post-burn contracture limiting joint function (neck, axilla, elbow, hand)', 'Contracture release and resurfacing with split/full-thickness graft or local flap (Z-plasties for linear bands)', 'ELECTIVE — but childhood contractures across growing joints are prioritised before deformity becomes fixed and bone/joint change', 'Pressure garments, silicone, massage and aggressive splinting/physiotherapy prevent and soften early contracture; established mature bands crossing joints do not stretch open without surgery', 'Assess the whole limb function and the patient''s goals, not just the scar; plan the post-release defect honestly (it is always larger than expected); splintage and physiotherapy AFTER release decide the result — book both before listing; neck contractures flag the anaesthetic airway plan'),
  ('PLASTICS', 'IND-PLAS-03', 'Necrotising fasciitis / necrotising soft-tissue infection', 'Immediate radical surgical debridement of all necrotic tissue, repeated at planned intervals; reconstruction only after clean and stable', 'EMERGENCY — hours count; resuscitation runs alongside, never instead of, source control', 'None; antibiotics without debridement are futile in established necrotising infection', 'Pain out of proportion, oedema beyond erythema, skin discoloration/blistering, crepitus, systemic toxicity; finger-sweep test in theatre confirms non-adherent fascia and dishwater fluid; mark the advancing edge hourly while preparing theatre; diabetes and HIV are common substrates — screen; relook at 12-24 hours is booked from the first operation'),
  ('PLASTICS', 'IND-PLAS-04', 'Grade III-IV pressure ulcer (sacral, trochanteric, ischial) in a stable, optimised patient', 'Debridement of the ulcer and bursa, then musculocutaneous/fasciocutaneous flap cover in selected patients', 'ELECTIVE — flap surgery only after nutrition, offloading discipline, spasm control and anaemia are corrected; debridement of wet necrosis is URGENT when septic', 'Structured conservative care (2-hourly turning, pressure-relieving surfaces, dressings, nutrition) heals many ulcers and is the default for patients who cannot maintain post-operative offloading — a flap without an offloading plan will simply break down again', 'Probe for bone involvement and treat osteomyelitis with the debridement plan; assess the SOCIAL offloading reality (caregiver, mattress, wheelchair cushion) as a listing criterion; spinal-injury patients need spasm and continence plans documented; recurrence rates are high and belong in consent'),
  ('PLASTICS', 'IND-PLAS-05', 'Traumatic soft-tissue defect with exposed bone, tendon or hardware', 'Debridement then reconstruction along the ladder: delayed closure, graft, local/regional flap (gastrocnemius/soleus for proximal/middle-third tibia; fasciocutaneous flaps elsewhere)', 'URGENT — establish a clean wound early, achieve definitive cover within days; exposed structures desiccate and infect while waiting', 'Negative-pressure or moist dressings can temporise and granulate small exposures to graftable beds; long-term dressings over exposed bone/tendon are not a definitive plan', 'The reconstruction choice is planned WITH the fracture plan (ortho-plastic decision); free-flap capability is limited to the central unit — regional/local flaps and cross-leg flap remain relevant national workhorses; document neurovascular status and photograph serially'),
  ('PLASTICS', 'IND-PLAS-06', 'Cutaneous squamous cell carcinoma (including Marjolin ulcer and lesions in persons with albinism)', 'Wide local excision with defined margin and closure/graft; regional nodes assessed and managed per findings', 'EXPEDITED — biopsy-confirmed invasive SCC is listed within weeks; fungating or bleeding lesions sooner', 'Radiotherapy (central level) for the inoperable or as adjuvant; no dressing-based alternative alters the disease', 'Persons with albinism carry a heavy SCC burden and enter skin-surveillance programmes — sun-protection counselling and follow-up are part of the surgical episode; any chronic ulcer or old burn scar that changes character is biopsied (Marjolin); examine and record regional nodes; histology margins chased and re-excision booked where involved'),
  ('PLASTICS', 'IND-PLAS-07', 'Symptomatic keloid (pain, itch, recurrent infection, functional restriction)', 'Intralesional/extralesional excision combined with adjuvant therapy (serial corticosteroid injection; pressure devices e.g. earring clips for lobules; radiotherapy only where available centrally)', 'ELECTIVE — surgery without an adjuvant plan is worse than no surgery', 'Serial intralesional corticosteroid alone flattens many keloids and is first-line; silicone and pressure therapy for early/minor disease; observation is legitimate for asymptomatic keloids given recurrence risk', 'Excision alone recurs in the majority — never list without the adjuvant pathway documented and the patient counselled on recurrence; earlobe keloids (piercing-related) respond best to excision plus pressure clip; document baseline photographs'),
  ('PLASTICS', 'IND-PLAS-08', 'Complex hand injury (flexor tendon zone II, digital nerve, or composite tissue loss)', 'Primary or delayed-primary repair of tendons/nerves with early protected mobilisation; flap cover for pulp/dorsal loss', 'URGENT — repair within days gives the best glide and sensory outcomes; immediate surgery for devascularised digits', 'Splintage and secondary reconstruction (grafts, tenolysis) accepted where primary expertise is absent — but referral within the first week keeps primary repair options open', 'Examine and record each tendon and nerve territory separately before anaesthesia; hand cases are physiotherapy-dependent — the rehabilitation protocol (early protected motion) is booked with the operation; splint in the safe position between stages; smoking/carbon-monoxide counselling for flap and replant candidates')) AS t(specialty, indication_code, condition_display, typical_procedure, urgency_guidance, non_operative_alternatives, notes)
ON CONFLICT (tenant_id, indication_code) DO NOTHING;

INSERT INTO surgery.surgical_operative_template
    (tenant_id, specialty, template_code, template_name, typical_procedure, position, preparation, incision, key_steps, technique_options, closure_plan, wound_classification, postop_instructions)
SELECT '00000000-0000-4000-8000-000000000001'::uuid, specialty, template_code, template_name, typical_procedure, position, preparation, incision, key_steps, technique_options, closure_plan, wound_classification, postop_instructions
FROM (VALUES
('GENERAL_SURGERY', 'TPL-GS-01', 'Open appendicectomy', 'Open appendicectomy via Lanz incision', 'Supine', 'Chlorhexidine-alcohol skin preparation abdomen; standard four-towel drape; cefazolin plus metronidazole at induction, within 60 minutes before incision', 'Lanz incision centred on McBurney point (lower midline if generalised peritonitis or diagnostic doubt)', '1. Incise skin and subcutaneous fat; 2. Split external oblique aponeurosis in line of fibres; 3. Muscle-split internal oblique and transversus; 4. Open peritoneum between clips, note free fluid and send pus for culture; 5. Deliver caecum and identify appendix by following taeniae; 6. Divide mesoappendix between ties to the base; 7. Crush, ligate and divide appendix base; bury stump only if surgeon preference and caecal wall healthy; 8. Lavage right iliac fossa and pelvis if contaminated; 9. Confirm haemostasis and count', 'Laparoscopic appendicectomy where stack and skills available; convert to lower midline laparotomy for appendicular mass unsuspected, caecal pathology, or inaccessible retrocaecal appendix', 'Peritoneum and muscle layers with absorbable suture; external oblique with continuous absorbable; skin subcuticular absorbable — leave skin open or loosely apposed if gross contamination', 'CONTAMINATED', 'Free fluids and diet as tolerated from the same day if uncomplicated; early mobilisation; continue antibiotics only for perforation or abscess (course, not single doses); review wound at 7–10 days at nearest facility; return advice for fever, wound discharge, or increasing pain'),
  ('GENERAL_SURGERY', 'TPL-GS-02', 'Laparoscopic cholecystectomy', 'Laparoscopic cholecystectomy with critical view of safety', 'Supine, reverse Trendelenburg, left tilt; surgeon on patient''s left (or between legs per training)', 'Chlorhexidine-alcohol preparation; square drape exposing costal margin to umbilicus; single-dose cefazolin at induction for acute cases or high-risk patients', 'Open (Hasson) umbilical entry; epigastric working port and two right subcostal ports under vision', '1. Establish pneumoperitoneum by open technique at umbilicus; 2. Diagnostic laparoscopy; 3. Retract fundus cephalad and infundibulum laterally; 4. Dissect hepatocystic triangle clearing fat and fibrous tissue; 5. Achieve the critical view of safety — two structures only entering gallbladder, lower third of cystic plate exposed; 6. Clip and divide cystic artery and cystic duct; 7. Dissect gallbladder off liver bed with diathermy; 8. Confirm haemostasis of liver bed; retrieve gallbladder via umbilical port; 9. Desufflate under vision', 'Open cholecystectomy via right subcostal (Kocher) incision where laparoscopy unavailable or after conversion; subtotal (fenestrating or reconstituting) cholecystectomy as bail-out for the hostile hepatocystic triangle — never dissect blindly toward the critical view', 'Umbilical fascial defect closed with heavy absorbable suture; skin with subcuticular absorbable; open conversion closed in mass closure with looped slowly-absorbable suture', 'CLEAN_CONTAMINATED', 'Diet as tolerated same day; mobilise same day; day-case or next-day discharge if uncomplicated; shoulder-tip pain counselling; review at 2 weeks; urgent return advice for jaundice, fever, bile-stained wound discharge, or worsening abdominal pain'),
  ('GENERAL_SURGERY', 'TPL-GS-03', 'Lichtenstein open inguinal hernia repair', 'Open mesh repair of inguinal hernia (Lichtenstein)', 'Supine', 'Chlorhexidine-alcohol preparation groin and abdomen to umbilicus; single-dose cefazolin at induction where mesh implanted; local, spinal or general anaesthesia per patient and platform', 'Oblique groin incision 2 cm above and parallel to medial two-thirds of inguinal ligament', '1. Incise skin, Camper and Scarpa fascia; 2. Open external oblique aponeurosis through superficial ring, protecting ilioinguinal nerve; 3. Mobilise cord at pubic tubercle; 4. Identify sac — indirect: dissect off cord to deep ring, transfix and reduce or invert; direct: invert with plicating suture; 5. Assess femoral canal; 6. Place flat polypropylene mesh with 2 cm overlap of pubic tubercle, tail slits around cord; 7. Fix with non-absorbable suture to inguinal ligament below and conjoint tendon above, recreating deep ring snug to cord; 8. Confirm cord and testis lie naturally; haemostasis', 'Tissue repair (modified Bassini or Shouldice) where mesh unavailable or field contaminated; laparoscopic (TEP/TAPP) at central hospitals for bilateral or recurrent hernias; strangulation converts to hernia approach plus laparotomy if bowel resection needed — avoid mesh in contaminated fields', 'External oblique with continuous absorbable suture reforming superficial ring; Scarpa with interrupted absorbable; skin subcuticular absorbable', 'CLEAN', 'Day-case where social circumstances allow; mobilise immediately; simple analgesia; no heavy lifting for 4–6 weeks; counsel on scrotal bruising and seroma; review wound at 2 weeks; return urgently for spreading redness, wound discharge, or acute testicular pain'),
  ('GENERAL_SURGERY', 'TPL-GS-04', 'Emergency midline laparotomy', 'Emergency laparotomy for peritonitis or obstruction', 'Supine, arms out; urinary catheter and nasogastric tube before knife to skin', 'Chlorhexidine-alcohol preparation nipples to mid-thigh; broad-spectrum cover at induction (cefazolin or ceftriaxone plus metronidazole, per local policy) — treatment course if established sepsis; warm theatre, active warming for long cases', 'Midline laparotomy skirting the umbilicus, extended as required', '1. Incise skin and linea alba, enter peritoneum with care near old scars; 2. Sample free fluid for microbiology; suction gross contamination; 3. Systematic four-quadrant exploration; 4. Identify and control the source — patch perforation, resect non-viable bowel, decompress obstruction, drain abscess; 5. Decide anastomosis versus stoma on physiology (shock, inotropes, gross contamination, acidosis favour stoma or damage-control); 6. Thorough warm saline lavage; 7. Recount instruments and swabs; 8. Consider relook strategy or laparostomy if damage-control physiology', 'Damage-control laparotomy with temporary closure and planned return at 24–48 hours for the unstable patient; laparoscopy has little role in the unstable emergency abdomen at district level', 'Mass closure of linea alba with looped slowly-absorbable suture, small-bite technique, suture-to-wound length at least 4:1; skin staples or interrupted sutures; leave skin open with damp dressing in gross contamination for delayed primary closure', 'DIRTY', 'HDU-level observation where available or highest-acuity ward bed; hourly observations first 6 hours; nasogastric tube until output falls and bowel function returns; chest physiotherapy and early mobilisation; VTE prophylaxis once haemostasis certain; daily wound review; stoma teaching from day 1 where formed; senior review before discharge with wound and stoma follow-up booked'),
  ('GENERAL_SURGERY', 'TPL-GS-05', 'Debridement of necrotising soft tissue infection', 'Radical debridement of necrotising fasciitis with planned relook', 'Position to expose whole affected region and its proximal extent; lithotomy for perineal (Fournier) disease', 'Chlorhexidine or povidone-iodine wide field preparation beyond visibly affected skin; broad-spectrum antibiotics as treatment (not prophylaxis) including anaerobic and streptococcal cover per local sepsis policy; cross-match blood — debridement bleeds', 'Longitudinal incisions over affected area extending into macroscopically normal tissue', '1. Incise and assess fascia — dishwater fluid, grey non-contractile muscle, and loss of fascial resistance to finger sweep confirm diagnosis; 2. Debride all non-viable skin, fat, fascia and muscle back to bleeding, contracting tissue; 3. Send tissue (not swab) for microscopy, culture and histology; 4. Extend proximally until healthy fascia reached; 5. Lavage copiously; 6. Pack open with damp gauze — do not close; 7. Mark skin edge with sutures or marker to judge progression; 8. Book mandatory relook debridement at 24–48 hours; 9. Consider diverting colostomy at relook for sphincter-involving perineal disease', 'Serial bedside dressing changes under ketamine or regional block between theatre visits where theatre access constrained; skin grafting or delayed closure only once wound clean and patient anabolic; amputation may be life-saving for circumferential limb disease', 'No primary closure; delayed closure, secondary intention, or split-skin grafting once clean granulation established', 'DIRTY', 'Manage as sepsis: fluid balance hourly, early critical-care referral where available; analgesia adequate for dressing changes; nutrition started early (high protein); glycaemic control; HIV and diabetes screening; daily senior wound review; relook theatre booking is part of the operation note, not an afterthought'),
  ('COLORECTAL', 'TPL-CR-01', 'Right hemicolectomy', 'Right hemicolectomy with ileocolic anastomosis for caecal or ascending colon cancer', 'Supine; urinary catheter; nasogastric tube if obstructed', 'Chlorhexidine-alcohol preparation nipples to groins; cefazolin (or ceftriaxone per policy) plus metronidazole within 60 minutes before incision; stoma sites marked preoperatively even when anastomosis planned', 'Midline laparotomy; laparoscopic approach at central hospitals for suitable non-obstructed cases', '1. Full laparotomy and staging — liver, peritoneum, nodal disease documented; 2. Mobilise right colon along the white line, protecting duodenum, right ureter and gonadal vessels; 3. Mobilise hepatic flexure; 4. Isolate and divide ileocolic (and right colic where present) vessels at origin for oncological clearance; 5. Divide terminal ileum and transverse colon at planned margins; 6. Fashion ileocolic anastomosis (stapled side-to-side or handsewn two-layer) with well-perfused, tension-free ends; 7. Close mesenteric window per preference; 8. Lavage, haemostasis, count', 'Handsewn anastomosis wholly acceptable where staplers unavailable; in the unstable or grossly contaminated abdomen prefer ileostomy and mucous fistula over anastomosis; extended right hemicolectomy for hepatic flexure or proximal transverse tumours', 'Mass closure of midline with looped slowly-absorbable suture, small-bite technique; skin per contamination — subcuticular if clean-contaminated, interrupted or delayed if soiled', 'CLEAN_CONTAMINATED', 'Enhanced-recovery pattern where feasible: early oral fluids, diet by day 1–2 as tolerated, mobilise day 1; avoid routine nasogastric retention; VTE prophylaxis; observe for anastomotic leak pattern day 3–5 (tachycardia, fever, pain, ileus); histology tracked to MDT; clinic review with histology at 2–4 weeks'),
  ('COLORECTAL', 'TPL-CR-02', 'Hartmann''s procedure', 'Sigmoid resection with end colostomy and rectal stump closure for perforated diverticulitis or obstructing/perforated sigmoid pathology', 'Lloyd-Davies (lithotomy-Trendelenburg) if access to rectum may be needed; otherwise supine; urinary catheter', 'Chlorhexidine-alcohol preparation nipples to mid-thigh; broad-spectrum antibiotics as treatment course for established peritonitis; left iliac fossa stoma site marked (or best-judgement siting on table with flat abdomen simulated)', 'Midline laparotomy', '1. Enter abdomen, suction contamination, sample fluid for culture; 2. Systematic exploration and peritoneal toilet; 3. Mobilise sigmoid off lateral attachments, identify and protect left ureter before any vascular division; 4. Resect perforated/diseased sigmoid segment; 5. Close rectal stump (stapled or two-layer handsewn) and consider marking with long non-absorbable suture; 6. Thorough lavage of all quadrants; 7. Fashion end colostomy through pre-marked trephine in left rectus, spouted slightly, mucocutaneous sutures; 8. Mass closure; leave skin management per contamination', 'Primary anastomosis with or without defunctioning ileostomy only for selected stable patients with limited contamination and senior decision; damage-control with stapled-off bowel ends and planned relook for the physiologically hostile patient', 'Mass closure with looped slowly-absorbable suture; skin left open or loosely closed in faeculent peritonitis for delayed primary closure', 'DIRTY', 'HDU-level care where available; sepsis bundle continued; stoma viability checked at least every shift for 48 hours (colour, spout, output) and stoma teaching started day 1; histology mandatory — perforated cancer must not be missed; counsel about reversal being a separate major decision at 3–6 months; colonoscopy or contrast evaluation of retained colon after recovery'),
  ('COLORECTAL', 'TPL-CR-03', 'Sigmoid colectomy for volvulus', 'Elective/semi-elective sigmoid colectomy after endoscopic detorsion of sigmoid volvulus', 'Supine (Lloyd-Davies if stapled anastomosis from below contemplated); urinary catheter', 'Chlorhexidine-alcohol preparation; cefazolin plus metronidazole within 60 minutes before incision; bowel preparation per unit practice — decompressed bowel often adequate without full mechanical preparation', 'Midline laparotomy (lower midline usually sufficient)', '1. Laparotomy and confirmation of redundant sigmoid loop with narrow mesenteric pedicle; 2. Assess bowel viability along the whole loop; 3. Mobilise sigmoid, identify and protect left ureter; 4. Divide mesentery close to bowel (benign disease — radical nodal clearance unnecessary); 5. Resect redundant loop to soft, well-vascularised descending colon and upper rectum/rectosigmoid; 6. Fashion tension-free colorectal/colocolic anastomosis (handsewn two-layer or stapled); 7. Lavage and haemostasis; 8. Count and close', 'If gangrene or perforation found: Hartmann''s procedure instead of anastomosis; mesosigmoidopexy is inferior to resection for recurrence and reserved for the exceptional case unfit for resection', 'Mass closure with looped slowly-absorbable suture; subcuticular skin closure if field clean-contaminated', 'CLEAN_CONTAMINATED', 'Oral fluids early, diet as bowel function returns; mobilise day 1; leak vigilance day 3–5; counsel on high recurrence risk had resection not been done (reinforces completion); routine clinic review at 2–4 weeks; no long-term surveillance needed for benign volvulus with clear histology'),
  ('COLORECTAL', 'TPL-CR-04', 'Milligan-Morgan haemorrhoidectomy', 'Open excisional haemorrhoidectomy for grade III–IV haemorrhoids', 'Lithotomy (or prone jack-knife per unit practice)', 'Perianal povidone-iodine preparation; single-dose cefazolin plus metronidazole at induction per unit policy; local anaesthetic with adrenaline infiltration for haemostasis and postoperative analgesia', 'No skin incision as such — excision of haemorrhoidal cushions at 3, 7 and 11 o''clock as required', '1. Examination under anaesthesia, confirm haemorrhoidal anatomy and exclude other pathology; 2. Gently efface each pile with artery forceps on the perianal skin and pile apex; 3. V-shaped skin incision and dissection of the pile off the internal sphincter fibres; 4. Transfix and ligate the vascular pedicle; excise pile; 5. Repeat for each column, preserving adequate mucocutaneous bridges (at least 1 cm) between wounds to prevent stenosis; 6. Meticulous haemostasis; 7. Leave wounds open (open technique); anal pack per preference', 'Rubber-band ligation in clinic for grades I–III as the standard non-excisional alternative; stapled haemorrhoidopexy only where device and expertise exist; thrombosed acute presentation — excise conservatively or manage conservatively per timing of onset', 'Wounds left open to heal by secondary intention; submucosal haemostatic suture only as needed', 'CLEAN_CONTAMINATED', 'Adequate multimodal analgesia prescribed proactively — this operation is painful; stool softeners and fibre from day 0; warm sitz baths from day 1; warn about urinary retention (first void checked before discharge) and secondary haemorrhage around day 7–10 with clear return advice; review at 2–3 weeks; check healing and exclude stenosis at 6 weeks'),
  ('COLORECTAL', 'TPL-CR-05', 'EUA and drainage of perianal abscess', 'Examination under anaesthesia and incision and drainage of perianal/ischiorectal abscess', 'Lithotomy', 'Perianal povidone-iodine preparation; antibiotics only as adjunct for surrounding cellulitis, immunosuppression, or systemic sepsis — drainage is the treatment', 'Cruciate or elliptical incision over point of maximal fluctuance, kept as close to the anal verge as the cavity allows (shortens any future fistula)', '1. Examination under anaesthesia — document induration, deep extension, horseshoe spread, and any obvious internal opening (gentle inspection only); 2. Incise over maximal fluctuance; 3. Send pus for culture (include TB studies where clinically indicated); 4. Break loculations digitally; excise skin edge (deroof) to prevent premature closure; 5. Curette cavity gently; 6. Irrigate; 7. Loose pack or wick — avoid tight packing; 8. Do NOT lay open a track or place a cutting seton in the acute field unless a superficial track is obvious and a senior decides', 'Loose draining seton at index drainage only when an obvious low track is found and the operator is experienced; bedside drainage under local acceptable only for small superficial abscesses in adults', 'No closure — heals by secondary intention with dressings', 'CONTAMINATED', 'Daily dressings/sitz baths via local clinic; analgesia and stool softeners; screen for diabetes and offer HIV testing; review at 2 weeks and again at 6 weeks specifically to detect fistula formation (up to half develop one); recurrent sepsis or persistent discharge → EUA by senior surgeon'),
  ('UPPER_GI_HPB', 'TPL-UGI-01', 'Open cholecystectomy with common bile duct exploration', 'Open cholecystectomy and common bile duct exploration for choledocholithiasis where ERCP unavailable', 'Supine with slight reverse Trendelenburg; on-table cholangiography facility (image intensifier) arranged where it exists', 'Chlorhexidine-alcohol preparation right costal margin to below umbilicus; cefazolin (or ceftriaxone per policy) within 60 minutes before incision — treatment course if cholangitis; correct coagulopathy of obstructive jaundice with vitamin K preoperatively', 'Right subcostal (Kocher) incision; extend medially as needed', '1. Enter abdomen, pack bowel away, expose porta hepatis; 2. Retrograde or fundus-first cholecystectomy with ligation of cystic artery and duct — duct left long if exploration planned; 3. Confirm duct dilatation and palpate stones; on-table cholangiogram via cystic duct where imaging available; 4. Kocherise duodenum to allow bimanual palpation of the distal duct; 5. Longitudinal choledochotomy in supraduodenal duct between stay sutures; 6. Extract stones with forceps, irrigation and Fogarty-type balloon; confirm distal patency into duodenum; 7. Close duct over T-tube (or primary closure over confirmed clear, freely draining duct per senior decision); 8. Subhepatic drain to the choledochotomy; 9. Haemostasis, count, close', 'ERCP-first pathway supersedes this operation where the service exists; choledochoduodenostomy for the grossly dilated duct with multiple or recurrent stones; refer unresolvable distal obstruction (possible malignancy) to hepatobiliary centre with a drain rather than heroic dissection', 'Mass or layered closure per incision with slowly-absorbable suture; T-tube exiting a separate stab wound, secured; subcuticular or interrupted skin', 'CLEAN_CONTAMINATED', 'Monitor drain output character daily — bile leak declared early; T-tube on free drainage with output charting; T-tube cholangiogram at 7–10 days and removal only after confirmed distal patency and no retained stones; clip drain per pathway once dry; LFT trend to confirm decompression; clinic review at 2–4 weeks with histology of gallbladder'),
  ('UPPER_GI_HPB', 'TPL-UGI-02', 'Gastrojejunostomy', 'Retrocolic or antecolic gastrojejunostomy for gastric outlet obstruction', 'Supine; nasogastric tube; urinary catheter for longer cases', 'Chlorhexidine-alcohol preparation; cefazolin plus metronidazole within 60 minutes before incision; preoperative correction of hypochloraemic alkalosis, potassium, and nutrition documented before booking', 'Upper midline laparotomy', '1. Laparotomy and assessment — confirm obstruction level, inspect for malignancy (liver, peritoneum, nodes), biopsy any suspicious tissue and the obstructing segment; 2. Identify dependent portion of the posterior stomach (greater curve, antrum); 3. Bring proximal jejunal loop (short, avoiding tension) antecolic, or retrocolic through an avascular mesocolic window per preference; 4. Fashion side-to-side isoperistaltic gastrojejunostomy at the most dependent point, two-layer handsewn or stapled, generous stoma; 5. Close mesocolic defect around the anastomosis if retrocolic; 6. Confirm patency and haemostasis of the staple/suture line from within before completing; 7. Consider feeding jejunostomy if severe malnutrition; 8. Lavage, count, close', 'Endoscopic duodenal stent for malignant outlet obstruction where advanced endoscopy exists; balloon dilatation pathway for selected benign strictures; add biopsy always — bypass without tissue diagnosis is incomplete', 'Mass closure of midline with looped slowly-absorbable suture; subcuticular skin', 'CLEAN_CONTAMINATED', 'Nasogastric decompression until output falls; delayed gastric emptying is common after bypass of a chronically obstructed stomach — patience, prokinetics per policy, and nutrition support rather than early re-operation; sips then graded diet on function; Helicobacter eradication and ulcer-dose proton pump inhibitor for benign ulcer disease; histology chased and communicated; clinic review at 2–4 weeks'),
  ('UPPER_GI_HPB', 'TPL-UGI-03', 'Distal gastrectomy', 'Distal gastrectomy with regional lymphadenectomy and gastrojejunal (Billroth II/Polya) or Roux-en-Y reconstruction for antral carcinoma', 'Supine; nasogastric tube; urinary catheter; epidural or regional analgesia planned where service exists', 'Chlorhexidine-alcohol preparation nipples to pubis; cefazolin plus metronidazole within 60 minutes before incision; blood cross-matched; MDT decision and staging documented on the operative checklist', 'Upper midline laparotomy', '1. Full staging laparotomy — peritoneum, liver, root of mesentery; abandon resection if occult carcinomatosis and switch to palliative intent decision; 2. Enter lesser sac dividing gastrocolic omentum (omentectomy en bloc for carcinoma); 3. Devascularise greater curve dividing right gastroepiploic vessels at origin, sweep nodes toward specimen; 4. Divide right gastric vessels and clear suprapyloric nodes; 5. Divide duodenum 1–2 cm beyond pylorus, secure stump; 6. Clear lesser curve and left gastric pedicle nodes, divide left gastric artery at origin; 7. Divide stomach at planned proximal margin (adequate clearance from tumour, frozen section where available); 8. Reconstruct: Polya gastrojejunostomy or Roux-en-Y; 9. Test anastomoses, place drain to duodenal stump per practice; 10. Count and close', 'Total gastrectomy with Roux-en-Y oesophagojejunostomy for proximal or diffuse tumours at specialist level; palliative distal gastrectomy or bypass for obstructing incurable tumours after MDT discussion of intent', 'Mass closure with looped slowly-absorbable suture; subcuticular or interrupted skin', 'CLEAN_CONTAMINATED', 'HDU-level care initially; nasogastric tube until output subsides; drain fluid inspected daily — bilious output suggests duodenal stump leak, an emergency review; graded oral intake per unit pathway; early small-volume frequent meals education; long-term vitamin B12 supplementation after gastrectomy; histology to MDT for adjuvant decision; clinic review at 2–3 weeks with dietitian input where available'),
  ('UPPER_GI_HPB', 'TPL-UGI-04', 'Open cystogastrostomy', 'Transgastric cystogastrostomy for mature retrogastric pancreatic pseudocyst', 'Supine; nasogastric tube', 'Chlorhexidine-alcohol preparation; cefazolin plus metronidazole within 60 minutes before incision; confirm on imaging that cyst wall is mature (generally 6 weeks or more) and adherent to posterior stomach', 'Upper midline laparotomy', '1. Laparotomy, confirm retrogastric mass bulging into posterior stomach; 2. Longitudinal anterior gastrotomy over the point of maximal bulge; 3. Needle-aspirate through posterior gastric wall to confirm cyst location and content; send fluid for amylase, culture and cytology; 4. Excise a generous disc (at least 3–4 cm) of the fused posterior gastric wall and cyst wall; send wall for histology to exclude cystic neoplasm; 5. Evacuate cyst contents and debris; gentle exploration of the cavity — no forceful disruption of septae near vessels; 6. Haemostatic running suture around the cystogastrostomy margin; 7. Close anterior gastrotomy in two layers; 8. Lavage, count, close', 'Endoscopic transgastric drainage where advanced endoscopy exists is the modern first line; Roux-en-Y cystojejunostomy for cysts not adherent to the stomach; external drainage only for infected collections with no internal option — accept fistula risk knowingly', 'Mass closure of midline with looped slowly-absorbable suture; subcuticular skin', 'CLEAN_CONTAMINATED', 'Nasogastric tube until gastric function returns; diet graded over days; monitor for haemorrhage (melaena or haematemesis from the anastomotic margin) in first 72 hours; histology of cyst wall chased — neoplasm changes everything; imaging at 6–8 weeks to confirm cavity resolution; alcohol cessation counselling and pancreatitis aetiology work-up completed before discharge'),
  ('UPPER_GI_HPB', 'TPL-UGI-05', 'Splenectomy', 'Emergency (trauma) or elective (haematological) splenectomy', 'Supine, slight right tilt with left side elevated for elective cases; full supine for trauma laparotomy', 'Chlorhexidine-alcohol preparation nipples to pubis; cefazolin within 60 minutes before incision; cross-matched blood in theatre; elective cases vaccinated at least 2 weeks preoperatively against pneumococcus, meningococcus and Haemophilus influenzae b', 'Midline laparotomy (trauma); midline or left subcostal (elective)', '1. Enter abdomen; in trauma: pack all four quadrants, then address the spleen; 2. Deliver spleen medially by dividing lienorenal and lienophrenic attachments with hand behind the spleen; 3. Pack the splenic bed; 4. Identify tail of pancreas and keep it out of clamps; 5. Divide short gastric vessels between ties, staying off the greater curve wall; 6. Clamp, divide and doubly ligate splenic artery then vein at the hilum (artery first limits engorgement); 7. Remove spleen; search for and preserve or note splenunculi in haematological cases (remove them) versus trauma (irrelevant); 8. Haemostasis of bed, short gastrics re-checked; drain only if pancreatic tail injury suspected; 9. Count and close', 'Splenic conservation (topical haemostatics, suture splenorrhaphy, partial splenectomy) for low-grade injury in stable patients, especially children; non-operative management is the default for the stable splenic injury and this operation should not be reached without instability or ongoing transfusion need', 'Mass closure with looped slowly-absorbable suture; skin per contamination of the laparotomy', 'CLEAN', 'Monitor for bleeding first 24 hours and for left lower lobe atelectasis — chest physiotherapy; watch drain (if placed) for amylase-rich fluid suggesting pancreatic tail injury; post-splenectomy thrombocytosis expected — thromboprophylaxis per policy; vaccinate before discharge if not done preoperatively; lifelong advice card: overwhelming post-splenectomy infection risk, early antibiotics for fever, and prompt malaria treatment-seeking — document that this education happened'),
  ('BREAST_ENDOCRINE', 'TPL-BE-01', 'Modified radical mastectomy', 'Modified radical mastectomy (mastectomy with level I–II axillary clearance) for breast carcinoma', 'Supine, arm on affected side abducted to 90 degrees on arm board', 'Chlorhexidine-alcohol preparation chest wall, axilla and arm to elbow; single-dose cefazolin within 60 minutes before incision (drains and larger dissection justify prophylaxis); WHO time-out includes explicit laterality confirmation against imaging and consent', 'Transverse elliptical incision incorporating nipple-areola complex and any biopsy scar, oriented to allow tension-free closure', '1. Confirm marked side and site; 2. Raise superior and inferior skin flaps in the plane between subcutaneous fat and mammary tissue — viable, even thickness; 3. Dissect breast off pectoralis major fascia from medial to lateral (fascia taken with specimen per practice); 4. Enter axilla lateral to pectoralis minor; identify and preserve axillary vein, long thoracic nerve (serratus) and thoracodorsal pedicle; 5. Clear level I–II axillary contents en bloc with the breast; preserve intercostobrachial nerves where oncologically reasonable; 6. Orient specimen with sutures/clips for pathology; 7. Meticulous haemostasis; 8. One or two closed-suction drains (axilla ± flaps); 9. Close without tension', 'Wide local excision plus axillary staging where breast conservation appropriate AND radiotherapy accessible; toilet (simple) mastectomy without axillary clearance for palliative local control of fungating disease; sentinel node biopsy replaces clearance for the clinically node-negative axilla where dye/isotope technique is available', 'Dermis with interrupted absorbable, skin with subcuticular absorbable; drains secured and their planned removal criteria written in the note', 'CLEAN', 'Shoulder exercises taught from day 1 to prevent stiffness; drain output charted daily, removal per unit threshold (commonly under 30–50 ml/day); seroma counselling and aspiration access after drain removal; histology with receptor status tracked to MDT for adjuvant therapy decision; lymphoedema prevention education; psychological support and prosthesis/reconstruction discussion documented; review at 2 weeks with results'),
  ('BREAST_ENDOCRINE', 'TPL-BE-02', 'Wide local excision with axillary staging', 'Wide local excision of breast carcinoma with sentinel node biopsy or axillary sampling', 'Supine, arm abducted on board', 'Chlorhexidine-alcohol preparation breast and axilla; single-dose cefazolin at induction per unit policy; laterality and lesion localisation (palpable, skin-marked, or wire/ultrasound-localised) confirmed at time-out', 'Cosmetically placed incision over the lesion (circumareolar or along skin lines where reach allows); separate axillary incision', '1. Confirm side, site, and localisation; 2. Excise the tumour with a macroscopic margin of normal tissue in all directions, full thickness where indicated; 3. Orient specimen with standard suture/clip convention and record it in the note; specimen radiograph where impalpable lesion and imaging available; 4. Clip the cavity walls for radiotherapy planning; 5. Achieve haemostasis and close cavity per breast-conserving technique (mobilise gland tissue to avoid deformity); 6. Axilla: sentinel node biopsy with blue dye (with isotope where available) or four-node axillary sampling; send nodes separately labelled; 7. Close both wounds', 'Mastectomy if margins unobtainable relative to breast size, multicentric disease, or radiotherapy inaccessible; completion axillary clearance per node results and MDT; re-excision of involved margins is expected practice — counsel preoperatively', 'Breast parenchyma approximated with absorbable sutures where feasible; dermis interrupted absorbable; skin subcuticular; axilla usually drainless for sampling/sentinel', 'CLEAN', 'Simple analgesia; supportive bra advice; margin and node histology tracked — re-excision or clearance decision at MDT within 4 weeks; radiotherapy referral is part of the operation''s completion, not an optional extra — flag if radiotherapy pathway is not confirmed; review at 2 weeks with results; annual surveillance imaging per protocol thereafter'),
  ('BREAST_ENDOCRINE', 'TPL-BE-03', 'Drainage of breast abscess', 'Needle aspiration (preferred first line) or incision and drainage of breast abscess', 'Supine', 'Skin antisepsis over the abscess; antibiotics covering staphylococci per local policy as adjunct; ultrasound guidance for aspiration where available', 'Aspiration: no incision. Drainage: incision over maximal fluctuance following skin lines, placed to allow dependent drainage and cosmesis (periareolar where anatomy permits)', '1. Confirm collection (ultrasound or aspiration of pus); 2. First line: aspirate to dryness with a wide-bore needle, send pus for culture (include TB studies if indicated); plan repeat aspiration at 2–3 day intervals until dry; 3. If skin necrosis, thick loculated pus, or failed serial aspiration: incise over fluctuance; 4. Break loculations digitally; 5. Irrigate cavity; 6. Loose wick or corrugated drain — avoid tight packing; 7. Biopsy the abscess wall if anything atypical (solid areas, non-lactational recurrence, systemic features)', 'Serial aspiration under antibiotics is the default modern pathway and preserves breastfeeding; formal drainage under general anaesthesia reserved for failures and necrotic skin; recurrent subareolar sepsis suggests periductal mastitis — definitive duct surgery electively, not acutely', 'Aspiration: none. Drainage: wound left open with light dressing to heal by secondary intention', 'CONTAMINATED', 'Continue breastfeeding or expressing from both sides in lactational abscess — engorgement worsens sepsis; analgesia; dressings via local clinic; review at 48–72 hours (repeat aspiration if refilling); culture results actioned; ANY abscess not resolving on schedule or with a residual mass gets imaging and core biopsy to exclude carcinoma and tuberculosis — book this check explicitly'),
  ('BREAST_ENDOCRINE', 'TPL-BE-04', 'Total thyroidectomy', 'Total or near-total thyroidectomy for multinodular goitre or carcinoma', 'Supine with neck extended (shoulder roll), head ring, slight reverse Trendelenburg', 'Chlorhexidine preparation chin to upper chest; single-dose cefazolin per unit policy (clean neck surgery — many units omit); euthyroid state confirmed; preoperative cord check documented; calcium and levothyroxine availability confirmed for aftercare', 'Transverse cervical (collar) incision two fingerbreadths above sternal notch in a skin crease', '1. Raise subplatysmal flaps superiorly and inferiorly; 2. Separate strap muscles in midline (divide only for very large goitres); 3. Mobilise one lobe: divide middle thyroid vein; 4. Ligate superior pole vessels close to the gland, protecting external branch of superior laryngeal nerve; 5. Identify recurrent laryngeal nerve in the tracheo-oesophageal groove and trace it to entry; preserve throughout; 6. Identify parathyroids and preserve on their vascular pedicles; autotransplant any devascularised gland into sternocleidomastoid after confirmation; 7. Divide inferior thyroid artery branches distal to parathyroid supply; 8. Free lobe off trachea dividing ligament of Berry with the nerve in view; 9. Repeat on contralateral side for total; 10. Haemostasis with Valsalva check; drain per unit practice', 'Hemithyroidectomy for unilateral disease; near-total leaving a protective remnant at the ligament of Berry where nerve or parathyroid risk demands; retrosternal goitre usually deliverable through the neck — sternotomy contingency noted for the largest cases (central hospital, cardiothoracic backup)', 'Strap muscles loosely approximated; platysma with interrupted absorbable; skin subcuticular absorbable or clips; drain (if used) exits laterally and is documented', 'CLEAN', 'Overnight observation minimum; airway watch — neck haematoma is an airway emergency and clip/suture removers stay at the bedside; observe for hypocalcaemia symptoms (perioral tingling, carpopedal spasm) with serum calcium checked per protocol after total thyroidectomy; start levothyroxine after total thyroidectomy; voice documented before discharge; histology tracked; calcium and thyroid function follow-up booked at 2 and 6 weeks'),
  ('BREAST_ENDOCRINE', 'TPL-BE-05', 'Hemithyroidectomy', 'Thyroid lobectomy and isthmusectomy for solitary nodule (diagnostic or therapeutic)', 'Supine with neck extended (shoulder roll), slight reverse Trendelenburg', 'Chlorhexidine preparation chin to upper chest; antibiotic prophylaxis usually unnecessary (clean case, no implant) per unit policy; euthyroid state confirmed for toxic adenoma; preoperative voice/cord assessment documented', 'Transverse cervical (collar) incision in a skin crease', '1. Subplatysmal flaps and midline strap separation; 2. Deliver the affected lobe; divide middle thyroid vein; 3. Ligate superior pole vessels on the capsule, protecting external branch of superior laryngeal nerve; 4. Identify and preserve the recurrent laryngeal nerve along its course; 5. Identify and preserve both ipsilateral parathyroids on their blood supply; 6. Divide ligament of Berry with the nerve in view; 7. Take the isthmus and pyramidal lobe with the specimen; suture-ligate the cut contralateral isthmus edge; 8. Haemostasis with Valsalva check; close', 'Fine-needle aspiration surveillance instead of surgery for cytologically benign nodules; total thyroidectomy upfront where contralateral disease or confirmed carcinoma with high-risk features; completion thyroidectomy later if histology mandates', 'Strap muscles loosely approximated; platysma interrupted absorbable; skin subcuticular; drains rarely needed', 'CLEAN', 'Day-case or overnight per unit practice; airway/haematoma vigilance as for any neck exploration; significant hypocalcaemia unusual after hemithyroidectomy but symptoms still checked; thyroid function at 6 weeks — a proportion need levothyroxine; histology reviewed and communicated with a completion-surgery decision where malignant; voice change beyond 2 weeks referred for cord assessment'),
  ('UROLOGY', 'TPL-URO-01', 'Scrotal exploration for torsion', 'Emergency scrotal exploration, detorsion and bilateral orchidopexy (or orchidectomy)', 'Supine', 'Chlorhexidine or povidone-iodine scrotal and groin preparation; single-dose cefazolin at induction; consent covers detorsion, fixation, orchidectomy and contralateral fixation — obtained without delaying theatre', 'Midline raphe incision (or transverse incisions per preference) giving access to both sides', '1. Open the affected hemiscrotum and tunica vaginalis; deliver the testis; 2. Untwist the cord fully, noting number of turns and direction; 3. Wrap in warm saline-soaked swab and observe colour return over several minutes; 4. Assess viability — colour, arterial bleeding on tunica albuginea incision if in doubt; 5. Viable: three-point fixation with non-absorbable or dartos-pouch fixation per practice; 6. Non-viable: orchidectomy with transfixed cord ligation; 7. Fix the contralateral testis at the same anaesthetic in all cases (bell-clapper anatomy is bilateral); 8. Haemostasis; layered closure', 'Manual detorsion in the emergency room only as a bridge while theatre is prepared — exploration proceeds regardless; ultrasound has no role in delaying exploration of a clinically suspected torsion', 'Dartos with continuous absorbable; skin with interrupted or subcuticular absorbable', 'CLEAN', 'Day-case or overnight; scrotal support and analgesia; counsel on findings (salvage or orchidectomy) and on fertility and prosthesis options where orchidectomy performed; wound review at 1–2 weeks; return advice for fever, spreading redness, or wound discharge; adolescent counselled to report any future acute pain in the remaining testis immediately'),
  ('UROLOGY', 'TPL-URO-02', 'Open transvesical prostatectomy', 'Open simple (transvesical) prostatectomy for large-gland benign prostatic enlargement', 'Supine, slight Trendelenburg; urinary catheter in field', 'Chlorhexidine-alcohol preparation umbilicus to genitalia; prophylaxis guided by urine culture — treat established bacteriuria before elective surgery; otherwise single-dose gentamicin (with cefazolin per policy) at induction; cross-match blood — the adenoma bed bleeds', 'Lower midline or Pfannenstiel incision; longitudinal or transverse cystotomy', '1. Extraperitoneal exposure of bladder; stay sutures and cystotomy; 2. Inspect bladder interior — stones removed, ureteric orifices identified and protected, tumours noted; 3. Incise mucosa around the protruding adenoma at the bladder neck; 4. Develop the plane between adenoma and surgical capsule with the finger; enucleate lobes completely; 5. Control the bed: haemostatic sutures at 5 and 7 o''clock at the bladder neck (main arterial pedicles), packing pressure while completing; 6. Trigonise/advance mucosa over the posterior bladder neck per practice; 7. Large-calibre three-way catheter with balloon seated in the fossa or bladder per bleeding control preference; 8. Close cystotomy in two layers; extraperitoneal drain; 9. Establish continuous bladder irrigation before leaving theatre; 10. Send adenoma for histology', 'Transurethral resection at central hospitals for glands within resectable size; catheter-dependent palliation where no surgical option exists; incidental bladder tumour found at cystotomy changes the operation — biopsy and staged planning rather than simultaneous heroics', 'Bladder in two layers with absorbable suture; rectus sheath with slowly-absorbable; skin subcuticular or interrupted; retropubic drain documented with removal plan', 'CLEAN_CONTAMINATED', 'Continuous bladder irrigation until effluent clears (usually 24–48 hours) with clot-retention vigilance — a blocked catheter with a distending bladder is an urgent bedside problem; haemoglobin monitored; drain out when dry; catheter removed at 5–7 days per unit practice with trial of void; histology chased (incidental carcinoma changes follow-up); counsel on retrograde ejaculation; review at 4–6 weeks with flow assessment'),
  ('UROLOGY', 'TPL-URO-03', 'Jaboulay hydrocelectomy', 'Hydrocelectomy by sac eversion (Jaboulay) for adult hydrocele', 'Supine', 'Chlorhexidine or povidone-iodine scrotal preparation; single-dose cefazolin per unit policy; day-case pathway; local/regional anaesthesia acceptable in selected adults', 'Transverse or longitudinal incision over the hydrocele, through dartos onto the sac', '1. Incise through scrotal layers onto the tense sac without opening it prematurely; 2. Deliver the intact sac by blunt sweep; 3. Open the sac, drain fluid, inspect testis and epididymis — any suspicion of tumour converts the operation (inguinal approach principles) and mandates senior input; 4. Excise redundant sac leaving a margin; 5. Evert remaining sac behind the cord and approximate edges with absorbable suture (Jaboulay) without constricting the cord; 6. Meticulous haemostasis — scrotal haematoma is the signature complication; 7. Return testis to natural lie; consider small drain for large dissections', 'Lord''s plication for thin-walled sacs (less dissection, less haematoma); aspiration alone only as comfort measure in the unfit — near-universal recurrence; young man with any solid element: stop, image, and treat as possible tumour via inguinal approach', 'Dartos continuous absorbable; skin interrupted or subcuticular absorbable; scrotal support applied in theatre', 'CLEAN', 'Day-case; scrotal support for 1–2 weeks; expect bruising, warn about haematoma with return advice; analgesia; avoid heavy exertion 2 weeks; wound review at 1–2 weeks; histology only if sac/testis abnormality excised'),
  ('UROLOGY', 'TPL-URO-04', 'Adult circumcision', 'Circumcision for phimosis, recurrent balanitis, or balanitis xerotica obliterans', 'Supine', 'Povidone-iodine or chlorhexidine preparation; antibiotic prophylaxis unnecessary for elective clean cases; penile block or ring block with plain local anaesthetic (no adrenaline) where done under local; treat active balanoposthitis before elective surgery', 'Circumferential incisions: outer skin marked at corona level with penis on gentle stretch, inner preputial layer incised leaving a small cuff below the corona', '1. Retract or dorsally slit a non-retractile foreskin to clean and inspect the glans; 2. Mark and incise outer skin circumferentially at the coronal level; 3. Incise inner layer leaving a few millimetres of mucosal cuff; 4. Excise the sleeve of foreskin; 5. Secure haemostasis with bipolar or fine ties — the frenular artery specifically; 6. Approximate skin to mucosal cuff with fine interrupted absorbable sutures, first sutures at frenulum and dorsum for alignment; 7. Send specimen for histology where scarring or lesion present; 8. Non-adherent dressing', 'Dorsal slit alone as a quicker emergency measure for acute retention from severe phimosis or irreducible paraphimosis, with completion circumcision later; preputioplasty for selected boys; topical steroid trial precedes surgery in physiological childhood phimosis', 'Fine interrupted absorbable sutures, mucosa to skin; no deep layers', 'CLEAN', 'Day-case; dressing off at 24–48 hours; warn about swelling, appearance, and nocturnal erection discomfort; abstinence from intercourse until healed (about 4–6 weeks); simple analgesia; review only if concerns unless histology pending — histology of scarred foreskins reviewed and communicated; return advice for bleeding more than spotting or spreading redness'),
  ('UROLOGY', 'TPL-URO-05', 'Open cystolithotomy', 'Open removal of bladder calculus', 'Supine, slight Trendelenburg; urethral catheter to fill bladder', 'Chlorhexidine-alcohol preparation lower abdomen and genitalia; urine culture obtained beforehand and bacteriuria treated; single-dose gentamicin (with cefazolin per policy) at induction', 'Pfannenstiel or lower midline incision; small transverse or longitudinal cystotomy between stay sutures', '1. Fill bladder via catheter to aid extraperitoneal exposure; 2. Expose anterior bladder wall between stay sutures; 3. Cystotomy; suction urine; 4. Deliver stone(s) intact where possible; irrigate out debris and re-inspect for fragments; 5. Inspect mucosa and bladder neck — document trabeculation, diverticula, tumours, and the state of the outflow tract; biopsy anything suspicious; 6. Confirm ureteric orifices clear and effluxing; 7. Close cystotomy in two layers over a urethral catheter; leak-test gently; 8. Extraperitoneal drain; count and close', 'Endoscopic cystolitholapaxy where equipment and stone size permit; address the cause (prostatectomy for outflow obstruction may be combined or staged per fitness and bleeding risk); percutaneous approaches at specialist level', 'Bladder two layers absorbable; rectus sheath slowly-absorbable; skin subcuticular; drain with removal plan documented', 'CLEAN_CONTAMINATED', 'Catheter free drainage 7–10 days then removal (per unit practice, with or without cystogram for concern); drain out when dry; encourage fluids; stone sent for analysis where available and result actioned (infection stones need infection eradication; urate stones need medical prevention); the underlying cause consultation booked — a stone removed without treating the cause is a stone rescheduled; review at 4–6 weeks'),
  ('PAEDIATRIC_SURGERY', 'TPL-PS-01', 'Inguinal herniotomy (child)', 'Open inguinal herniotomy with high ligation of the processus vaginalis', 'Supine; warming measures active for infants (theatre warm, limbs wrapped, warmed fluids)', 'Chlorhexidine preparation groin (alcohol-based used with care on infant skin, allowed to dry); single weight-appropriate dose of cefazolin per unit policy or none for clean day-case per local practice; caudal or local block for postoperative analgesia', 'Short transverse incision in the lowest inguinal skin crease', '1. Incise skin and Scarpa-equivalent layer; 2. In infants the sac may be reached at the superficial ring without opening external oblique; open external oblique in older children; 3. Identify and gently deliver the sac anteromedial to the cord; 4. Separate vas and vessels off the sac under vision with atraumatic technique — the vas is friable and unforgiving; 5. Twist and transfix-ligate the sac at the deep ring (high ligation); 6. Excise redundant distal sac (or leave open edge — no dissection of distal sac from cord in scrotum); 7. Confirm testis drawn back to natural scrotal position; 8. Haemostasis and closure', 'No mesh, no floor repair in children — high ligation is the complete operation; laparoscopic repair at specialist centres offers contralateral inspection; incarcerated hernia: attempt taxis then repair same admission; if reduction impossible or child toxic, emergency exploration with bowel assessment', 'External oblique (where opened) and Scarpa layer with fine absorbable; skin subcuticular fine absorbable; wound dressing minimal', 'CLEAN', 'Day-case for healthy term children; overnight apnoea monitoring for ex-premature infants below the unit''s corrected-age threshold; feed on waking; simple analgesia; parents warned about scrotal swelling/bruising; review at 2 weeks or sooner locally; return advice for redness, discharge, or a swollen tender scrotum'),
  ('PAEDIATRIC_SURGERY', 'TPL-PS-02', 'Ramstedt pyloromyotomy', 'Open pyloromyotomy for infantile hypertrophic pyloric stenosis', 'Supine; active warming; stomach emptied by nasogastric tube before induction', 'Chlorhexidine preparation (alcohol dried fully on infant skin); single weight-appropriate cefazolin dose at induction per policy; theatre proceeds ONLY after documented correction of dehydration and hypochloraemic alkalosis', 'Right upper quadrant transverse incision over the rectus (or supraumbilical curved incision per practice)', '1. Deliver the pyloric tumour into the wound with gentle traction on the stomach — never on the duodenum; 2. Confirm the olive and its distal margin (pyloric vein landmark); 3. Longitudinal seromuscular incision along the avascular anterior surface from antrum to just proximal of the duodenal margin; 4. Split hypertrophied muscle down to bulging intact mucosa with a spreader or blunt handle; 5. Check completeness — independent movement of the two muscle edges; 6. Test for perforation: insufflate air via the nasogastric tube and watch the mucosa, especially at the duodenal end; 7. Any perforation: close with fine suture and omental patch, note it clearly, and manage feeding accordingly; 8. Haemostasis of the muscle edges; return stomach; close', 'Laparoscopic pyloromyotomy at centres with paediatric laparoscopy; the open operation remains the regional standard and is fully adequate; an incomplete myotomy re-presents with persistent vomiting — re-operation decision at specialist level', 'Rectus sheath with fine slowly-absorbable suture; skin subcuticular fine absorbable', 'CLEAN', 'Structured refeeding per unit protocol starting within hours of surgery; occasional post-feed vomits are expected early and do not mean failure — persistent projectile vomiting beyond several days raises incomplete myotomy; discharge when feeding established and weight trajectory turning; parent education on feeding volumes; review at 1–2 weeks with weight check'),
  ('PAEDIATRIC_SURGERY', 'TPL-PS-03', 'Laparotomy for intussusception', 'Laparotomy with manual reduction or resection for irreducible/complicated ileocolic intussusception', 'Supine; active warming; nasogastric tube and urinary catheter; intravenous access secured and volume state corrected as far as the emergency allows', 'Chlorhexidine-alcohol preparation whole abdomen; cefazolin plus metronidazole (weight-appropriate) at induction — treatment course if perforation or gangrene; blood availability confirmed before knife to skin', 'Right-sided transverse supraumbilical incision (workhorse paediatric access) or right lower quadrant transverse per level of mass', '1. Deliver the intussusception into the wound; 2. Attempt reduction by RETROGRADE MILKING of the apex from distal to proximal with warm packs — never pull the proximal bowel out of the distal; 3. Accept failure gracefully: serosal splitting or dusky non-recovering bowel ends the attempt; 4. Assess viability after reduction with warm packs and patience; 5. Non-viable or irreducible: segmental resection (usually ileocolic) with primary anastomosis in the stable child; ileostomy where physiology or contamination dictates; 6. Search for a pathological lead point (Meckel diverticulum, polyp, lymphoma) — especially in children over 2 and recurrences — and resect with the specimen; 7. Incidental appendicectomy per unit practice when the caecum is in the field; 8. Lavage if contaminated; count and close', 'Air or hydrostatic enema reduction under imaging is the first-line pathway for the stable child and precedes this operation; laparoscopic-assisted reduction at specialist centres; recurrence after operative reduction is uncommon but re-presentation advice still given', 'Mass or layered closure with absorbable suture appropriate to age; skin subcuticular; leave skin for delayed closure only in gross contamination', 'CLEAN_CONTAMINATED', 'Nasogastric decompression until function returns; graded refeeding; strict fluid balance with paediatric maintenance plus losses; observe for recurrence (re-presentation with colic/red-currant stool) and for anastomotic complications where resection done; histology of any resected specimen chased — lymphoma changes everything; review at 2 weeks; parents given explicit early-return criteria'),
  ('PAEDIATRIC_SURGERY', 'TPL-PS-04', 'Neonatal divided sigmoid colostomy', 'Divided sigmoid colostomy for high anorectal malformation (or as levelling/defunctioning stoma in Hirschsprung disease)', 'Supine; neonatal warming imperative (radiant heat, warmed theatre, head covered); nasogastric decompression; glucose-containing maintenance fluids running', 'Chlorhexidine preparation with alcohol allowed to dry fully (neonatal skin burns are real); cefazolin plus metronidazole (weight-appropriate) at induction; vitamin K status of the newborn confirmed', 'Left lower quadrant oblique or transverse incision', '1. Confirm sigmoid loop and orientation — proximal limb must be certain (follow taeniae, trace from descending colon; an inverted stoma is a disaster); 2. Deliver the loop; divide between clamps; 3. Fashion PROXIMAL end colostomy at one end of the incision, everted slightly, mucocutaneous fine sutures; 4. Fashion distal limb as a separated MUCOUS FISTULA at the other end — divided and separated stomas reduce spill-over urinary contamination in malformations with urinary fistulae; 5. Leave adequate skin bridge between stomas for appliance care; 6. Irrigate the distal limb to clear meconium; 7. In Hirschsprung levelling: seromuscular biopsies to select ganglionic level before siting; 8. Close abdominal wall; document limb identity unambiguously in the note and on a diagram', 'Primary anoplasty without colostomy only for clearly low lesions with visible perineal fistula and experienced assessment; transverse colostomy is discouraged for anorectal malformation (compromises later pull-through); high-lesion definitive PSARP happens months later at a specialist centre after distal contrast study via the mucous fistula', 'Abdominal wall in layers with fine absorbable suture; skin subcuticular; stomas matured with interrupted fine absorbable mucocutaneous sutures', 'CLEAN_CONTAMINATED', 'Neonatal unit care: warmth, glucose, fluid balance, and stoma output charting (high-output stomas dehydrate a neonate in hours); stoma viability each shift for 48 hours; carer stoma training before discharge is a discharge criterion; screen for associated anomalies (cardiac echo, renal ultrasound) before discharge; distal loopogram and PSARP referral pathway booked; weight and stoma review at 2 weeks then monthly until definitive surgery'),
  ('PAEDIATRIC_SURGERY', 'TPL-PS-05', 'Inguinal orchidopexy', 'Inguinal orchidopexy for palpable undescended testis', 'Supine', 'Chlorhexidine preparation groin and scrotum; antibiotic prophylaxis generally unnecessary (clean day-case) per unit policy; caudal or ilioinguinal block for analgesia', 'Inguinal skin-crease incision; separate small scrotal incision for pouch fixation', '1. Open inguinal canal (or reach sac at superficial ring in infants); identify testis and cord; 2. Divide gubernacular attachments preserving any long-loop vas; 3. Separate the patent processus vaginalis off the cord and transfix-ligate it high — this step IS most of the operation; 4. Gain length by retroperitoneal mobilisation of cord vessels as needed; test tension-free reach to the scrotum; 5. Create a subdartos pouch via scrotal incision; 6. Deliver testis without torsion of the cord into the pouch; fix per practice (pouch itself, or fine fixation sutures); 7. Confirm lie and vascularity; close both wounds', 'Impalpable testis: examination under anaesthesia then laparoscopy at a centre (not blind groin exploration); staged (Fowler-Stephens) approaches for the high intra-abdominal testis at specialist level; atrophic nubbin excision with contralateral assessment per findings and counselling', 'Inguinal wound in layers with fine absorbable; scrotal skin fine absorbable; subcuticular skin closure', 'CLEAN', 'Day-case; simple analgesia; avoid straddle toys and rough play for 2 weeks; review at 4–6 weeks and again at 6–12 months specifically documenting testicular position and size (atrophy check); counsel parents about long-term fertility and the (modest) malignancy surveillance conversation for adolescence — teach self-examination at puberty'),
  ('SURGICAL_ONCOLOGY', 'TPL-SO-01', 'Wide local excision of soft tissue sarcoma', 'Planned wide local excision of biopsy-proven soft tissue sarcoma', 'Positioned for full exposure of the compartment, prior biopsy scar visible and marked; tourniquet for limb cases per practice (exsanguinate by elevation, not compression of the tumour)', 'Chlorhexidine-alcohol preparation of the whole region; single-dose cefazolin within 60 minutes before incision; imaging on display in theatre; MDT decision and biopsy histology confirmed at time-out', 'Elliptical incision excising the biopsy track and scar en bloc with the specimen, oriented along the limb/compartment axis', '1. Confirm biopsy-proven diagnosis, imaging and MDT plan at time-out; 2. Excise biopsy track and scar en bloc with the tumour; 3. Dissect wide of the tumour through macroscopically normal tissue planes — the pseudocapsule is tumour, never the plane; 4. Take the barrier fascial plane where the tumour abuts it; resect adherent muscle cuff as required; 5. Preserve major neurovascular structures where an oncologically sound plane exists; document any planned marginal area; 6. Orient the specimen with sutures and a diagram in the note; margins inked where pathology service supports it; 7. Clip the tumour bed for radiotherapy planning; 8. Meticulous haemostasis after tourniquet release; drain placed exiting IN LINE with the incision close to its end (a future re-excision or radiotherapy field consideration); 9. Closure without tension — plan flap/graft in advance rather than compromise margins', 'Amputation where compartment involvement or neurovascular encasement precludes limb-sparing excision with acceptable function — an MDT decision; unplanned prior excision (whoops procedure) mandates formal re-excision of the whole previous field; radiotherapy sequencing per MDT', 'Layered closure over suction drain; skin per tension — primary, graft, or flap as planned preoperatively', 'CLEAN', 'Drain management per output; wound review early if radiotherapy planned (radiation waits for healing); histology with margin status to MDT within 4 weeks — margin-positive disease returns for re-excision discussion; rehabilitation/physiotherapy referral for limb cases; surveillance schedule initiated per MDT (periodic local examination and chest imaging, commonly 3-monthly initially); patient shown the scar and taught to report new lumps in or around it'),
  ('SURGICAL_ONCOLOGY', 'TPL-SO-02', 'Wide local excision of melanoma', 'Definitive wide local excision of biopsy-proven cutaneous melanoma with Breslow-directed margins', 'Positioned for lesion access; regional node basin examable in the field where sentinel biopsy planned', 'Chlorhexidine-alcohol preparation; prophylaxis usually unnecessary for primary closure cases, single-dose cefazolin where graft or flap planned; Breslow thickness from the diagnostic biopsy confirmed at time-out — it sets the margin', 'Elliptical incision around the biopsy scar with the planned radial margin measured and marked before infiltration or incision (thin lesions about 1 cm; thicker lesions up to 2 cm per protocol), long axis along lymphatic drainage/skin lines', '1. Confirm site against biopsy diagram and photographs — the scar, not memory, defines the target; 2. Mark the measured radial margin around the entire scar before incising; 3. Excise down to (not usually including) deep fascia as a cylinder, not a cone — the deep margin matters as much as the radial; 4. Orient specimen with a marking suture and diagram; 5. Sentinel node biopsy at the same anaesthetic where technique (dye/isotope) available and Breslow criteria met; separate instruments/field per practice; 6. Close primarily where tension allows; split-skin graft or local flap otherwise — plantar and acral sites frequently need grafts; 7. Dress grafts with secure bolster', 'Completion/therapeutic regional node dissection for confirmed nodal disease as a separate planned procedure; amputation of a digit for subungual melanoma at the appropriate joint level; systemic therapy pathways per oncology access for advanced disease', 'Layered closure where primary; graft with bolster dressing or flap per defect; donor site dressed per unit practice', 'CLEAN', 'Graft/flap care per unit protocol with first inspection timed to practice; histology margin status reviewed — involved margins return for re-excision; node results to MDT; structured skin and nodal basin surveillance schedule per stage initiated (commonly 3–6 monthly examination in early years); patient taught whole-skin self-examination including soles and nails — the regional pattern makes this teaching load-bearing'),
  ('SURGICAL_ONCOLOGY', 'TPL-SO-03', 'Excisional lymph node biopsy', 'Excisional biopsy of a suspicious lymph node for tissue diagnosis (lymphoma, tuberculosis, metastasis)', 'Position per node basin — supine with head turned for cervical; supine for axillary/inguinal', 'Chlorhexidine-alcohol preparation; prophylaxis single-dose cefazolin per policy or omitted for small clean excisions; LABORATORY COORDINATION CONFIRMED BEFORE INDUCTION — a fresh (unfixed) specimen path for lymphoma work-up and TB studies must exist before the node is out', 'Short incision in skin crease directly over the selected node', '1. Select the most representative accessible node (avoid tiny reactive satellites); cervical preferred over inguinal where a choice exists; 2. Incise and dissect onto the node capsule; 3. Excise the node WHOLE with capsule intact — fragmented nodes defeat architecture-based diagnosis; diathermy kept off the specimen; 4. Ligate the hilar vessel; 5. Divide the specimen pathway: fresh portion (saline-moist, unfixed, straight to laboratory) for lymphoma immunophenotyping where the pathway exists, material for TB microscopy/culture/molecular testing, and formalin-fixed remainder for histology; 6. Haemostasis; close in layers; 7. Record in the note exactly what went where — specimen routing is part of the operation', 'Fine-needle aspiration and core biopsy as first-line triage in clinic — this operation is for FNA-inconclusive or lymphoma-suspected nodes; image-guided core at centres with radiology; never simply incise-and-curette a node suspicious for malignancy', 'Platysma/subcutaneous with fine absorbable; skin subcuticular; no drain for routine cases', 'CLEAN', 'Day-case; wound review at 1–2 weeks; THE OPERATION IS NOT COMPLETE UNTIL RESULTS ARE ACTIONED — histology, TB studies and any immunophenotyping tracked to a named clinician with a booked results visit; TB-confirmed cases routed to the TB programme same week; lymphoma-confirmed cases routed to oncology/haematology within 2 weeks; document the safety-net for the patient who does not return'),
  ('SURGICAL_ONCOLOGY', 'TPL-SO-04', 'Open Stamm feeding gastrostomy', 'Open (Stamm) feeding gastrostomy for malignant dysphagia or long-term enteral access', 'Supine', 'Chlorhexidine-alcohol preparation upper abdomen; single-dose cefazolin within 60 minutes before incision; goals-of-care and palliative intent confirmed and documented at time-out; local or regional anaesthesia with sedation is often preferable to general in the frail — plan deliberately', 'Short upper midline or left upper transverse incision', '1. Limited laparotomy; identify the anterior gastric body along the greater curve, chosen to reach the abdominal wall without tension; 2. Two concentric purse-string sutures on the anterior gastric wall; 3. Gastrotomy at the centre; insert a balloon or de Pezzer-type catheter of adequate calibre; 4. Tie purse-strings sequentially, inverting the gastric wall around the tube (Stamm invagination); 5. Bring tube out through a separate stab wound in the left upper quadrant — not through the main incision; 6. Suture the gastric wall to the parietal peritoneum around the exit site (gastropexy) at four quadrants — this stitch line is what prevents intraperitoneal leakage if the tube migrates; 7. Secure the tube externally with a fixation plate or sutures, note the length-at-skin marking; 8. Close the main incision', 'Percutaneous endoscopic gastrostomy where endoscopy service and a passable lumen exist — less invasive and preferred when available; feeding jejunostomy when the stomach is unusable or needed for a future conduit; nasogastric feeding as a short-term bridge only', 'Midline/transverse closure with slowly-absorbable suture; skin subcuticular or interrupted; tube exit site dressed flat', 'CLEAN_CONTAMINATED', 'Start feeds per unit protocol (commonly water first, then graded feeds within 24 hours); daily exit-site care and length-at-skin check — early tube dislodgement before tract maturity (about 2–4 weeks) is a surgical review, NOT a blind reinsertion at ward level; carer feeding training before discharge is a discharge criterion; dietitian/palliative care co-management documented; replacement pathway and emergency advice (blocked tube, dislodged tube, leaking site) written on the discharge summary'),
  ('SURGICAL_ONCOLOGY', 'TPL-SO-05', 'Palliative loop colostomy', 'Palliative defunctioning loop colostomy for malignant large bowel obstruction in incurable disease', 'Supine; nasogastric decompression running; resuscitation objectives met as far as the obstruction allows', 'Chlorhexidine-alcohol preparation; cefazolin plus metronidazole at induction; stoma site marked (or best-judgement sited) preoperatively; goals-of-care conversation documented — this operation buys symptom relief, not cure, and the record must say so', 'Trephine incision directly over the marked site where the level is known (left iliac fossa for recto-sigmoid obstruction); short midline laparotomy where the level or extent needs confirmation', '1. Confirm the obstruction level distal to the planned stoma (imaging beforehand; limited exploration if open); carcinomatosis with multilevel small bowel involvement found at surgery changes the plan — defunctioning a colon above small bowel obstruction helps nobody; 2. Choose mobile proximal colon that reaches the skin without tension (transverse or sigmoid per level); 3. Deliver the loop through a trephine in the rectus; 4. Confirm orientation — proximal limb identified beyond doubt (follow taeniae/insufflation per practice); a rotated stoma defunctions nothing; 5. Support the loop with a rod/bridge; 6. Open the colon transversely on its apex AFTER wall fixation; 7. Mature edges with mucocutaneous absorbable sutures, spouting the functional (proximal) side; 8. Decompress the obstructed proximal colon on table gently as needed; 9. Close any laparotomy; appliance fitted in theatre', 'Endoscopic colonic stent for suitable left-sided lesions where the service exists; venting/pharmacological palliation for the patient too frail for any procedure; resection is NOT the palliative default — the smallest operation that relieves the symptom wins', 'Trephine needs no closure beyond the matured stoma; midline (if used) mass closure; rod removed per unit practice around day 5–7', 'CLEAN_CONTAMINATED', 'Stoma viability and output per shift for 48 hours; appliance and self/carer care training started day 1 and completed before discharge; electrolytes watched during post-obstructive decompression; palliative care team co-management with symptom control plan on the discharge summary; oncology/MDT routing for any systemic options; explicit review booking and a named contact for stoma problems — a palliative stoma without support services traded one misery for another'),
  ('ORTHOPAEDICS', 'TPL-ORTH-01', 'Antegrade femoral intramedullary nailing (SIGN-type)', 'Intramedullary nailing of femoral shaft fracture', 'Supine on radiolucent or standard table with sandbag under buttock; lateral position acceptable without a fracture table', 'General or spinal anaesthesia; prophylactic IV antibiotic at induction; whole limb prepped hip to knee; image intensifier if available — SIGN technique permits nailing without one', 'Longitudinal incision proximal to the greater trochanter in line with the femoral shaft', '1. Incise fascia and split gluteal fibres to palpate trochanter; 2. Open entry point at tip of greater trochanter or piriform fossa with awl; 3. Reduce fracture by traction and manipulation (open the fracture through a lateral approach only if closed reduction fails); 4. Pass reamer/guide then advance nail across the fracture; 5. Confirm length and rotation against the contralateral limb; 6. Insert proximal and distal interlocking screws using the jig with slot-finder; 7. Confirm stability through range of motion; 8. Irrigate and close in layers', 'Retrograde nailing for distal-third or ipsilateral pelvic injury; plate osteosynthesis where nail stock exhausted; Perkins traction as the fallback definitive care', 'Fascia and subcutaneous layer with absorbable suture, skin with interrupted non-absorbable or staples', 'CLEAN', 'Free diet when awake; touch to partial weight-bearing with crutches from day 1-2 as fracture pattern allows; check radiograph before discharge; wound review at 2 weeks, radiographic review at 6 weeks and 3 months; report fever, discharge or increasing thigh pain immediately'),
  ('ORTHOPAEDICS', 'TPL-ORTH-02', 'Wound excision and external fixation of open tibial fracture', 'Debridement, irrigation and monolateral external fixation', 'Supine with bump under ipsilateral buttock; tourniquet applied but inflated only if needed to identify structures', 'IV antibiotics continued from admission; tetanus status confirmed; both legs prepped for comparison of rotation; remove field dressing only after prep', 'Extend the traumatic wound longitudinally as needed for full inspection; separate anteromedial incisions for pin placement', '1. Excise wound edges and all devitalised skin, fat, fascia and muscle back to bleeding, contracting tissue; 2. Deliver and inspect bone ends, remove free devascularised cortical fragments; 3. Irrigate with copious saline (low pressure); 4. Assign Gustilo grade now and record it; 5. Place two half-pins in the proximal and two in the distal fragment out of the zone of injury; 6. Reduce and align the fracture on the frame — length, alignment, rotation; 7. Confirm distal perfusion; 8. Leave the traumatic wound open or approximate loosely; apply non-adherent dressing', 'Definitive cast management for low-grade wounds after excision; conversion to intramedullary nail within 7-14 days at referral level if wound clean; circular frame for segmental defects at central level', 'Traumatic wound left open for planned relook at 48 hours; pin sites dressed dry; delayed primary closure or split-skin graft once clean', 'CONTAMINATED', 'Elevate limb; analgesia and continued antibiotics per protocol; planned second look at 48 hours booked before leaving theatre; pin-site care daily with saline; non-weight-bearing until relook decision; refer grade IIIB/IIIC for soft-tissue cover without delay'),
  ('ORTHOPAEDICS', 'TPL-ORTH-03', 'Hip hemiarthroplasty for displaced intracapsular neck of femur fracture', 'Austin Moore or cemented Thompson hemiarthroplasty', 'Lateral decubitus with pelvis stabilised; affected side up', 'Spinal or general anaesthesia; prophylactic IV antibiotic at induction; urinary catheter; whole limb prepped and draped free', 'Posterior (Moore) approach: curved incision centred on the posterior aspect of the greater trochanter, or direct lateral (Hardinge) per surgeon preference', '1. Divide fascia lata and split gluteus maximus fibres; 2. Detach short external rotators with a stay suture, protecting the sciatic nerve; 3. Capsulotomy and delivery of the femoral head, measure head diameter; 4. Deliver the femoral neck cut face, complete the neck osteotomy; 5. Broach the femoral canal to size; 6. Trial then insert the definitive stem (cemented if bone quality poor and cement available) with matched head; 7. Reduce and test stability in flexion-internal rotation; 8. Reattach the rotators, close in layers over the capsule', 'Cemented Thompson for wide osteoporotic canals; internal fixation (cannulated screws) instead for undisplaced fractures or the young; total hip arthroplasty at central level for the fit, active patient', 'Capsule and rotators to bone or through trochanteric drill holes, fascia lata and fat with absorbable suture, skin closure to preference', 'CLEAN', 'Sit out of bed day 1 and mobilise full weight-bearing with a frame; posterior precautions (no deep flexion, adduction or internal rotation) for 6 weeks after a posterior approach; VTE prophylaxis per protocol until fully mobile; wound review at 2 weeks; report dislocation symptoms — sudden pain, shortening, inability to weight-bear — urgently'),
  ('ORTHOPAEDICS', 'TPL-ORTH-04', 'Arthrotomy and lavage of the septic knee', 'Open drainage and washout of septic arthritis of the knee', 'Supine, thigh tourniquet applied (inflate only if bleeding obscures the field)', 'General or spinal anaesthesia; where possible aspirate for culture before antibiotics — otherwise antibiotics continue uninterrupted; limb prepped mid-thigh to ankle', 'Medial or lateral parapatellar mini-arthrotomy; anteromedial standard', '1. Incise retinaculum and capsule, take pus/fluid immediately into culture bottles and for Gram stain; 2. Open the suprapatellar pouch; 3. Debride fibrinous debris and loculations, biopsy synovium if chronic infection or TB suspected; 4. Lavage with copious warmed saline until effluent clear; 5. Assess articular cartilage and record findings; 6. Wash the gutters and posterior recesses with the knee through range; 7. Close capsule loosely over a drain (remove at 24-48 h); 8. Apply padded dressing and back-slab in extension', 'Arthroscopic washout where equipment and skills exist; serial aspiration acceptable only for early presentation with rapid clinical response', 'Capsule with interrupted absorbable suture, skin closed primarily; drain to gravity', 'DIRTY', 'IV antibiotics rationalised to culture results, usual total course 3-6 weeks with oral switch on clinical response; remove drain by 48 hours; begin quadriceps exercises and gentle range of motion as pain settles — do not immobilise beyond a few days; review inflammatory markers and temperature daily; repeat washout if not settling by 48-72 hours'),
  ('ORTHOPAEDICS', 'TPL-ORTH-05', 'Two-incision four-compartment fasciotomy of the leg', 'Emergency decompression for acute compartment syndrome', 'Supine; NO tourniquet', 'Do not delay for imaging or pressure measurement when the clinical diagnosis is made; prep entire leg; keep limb at heart level, not elevated, before decompression', 'Anterolateral incision midway between fibular shaft and tibial crest; posteromedial incision 2 cm posterior to the medial tibial border — both full length of the compartment (ankle to knee level)', '1. Anterolateral: incise skin generously then open anterior compartment fascia along its full length; 2. Identify the intermuscular septum and superficial peroneal nerve, open the lateral (peroneal) compartment; 3. Posteromedial: open superficial posterior compartment along its length; 4. Detach soleus origin from the tibia to expose and release the deep posterior compartment, protecting the posterior tibial neurovascular bundle and saphenous vein/nerve; 5. Assess muscle in each compartment — colour, consistency, contractility, capacity to bleed; 6. Excise clearly dead muscle only; 7. Confirm all four compartments soft; 8. Dress wounds open with non-adherent bulky dressing or vessel-loop shoelace technique', 'Single lateral (perifibular) incision approach where surgeon preference dictates; forearm decompression uses volar Henry plus dorsal incisions with carpal tunnel release', 'Wounds ALWAYS left open; planned relook and debridement at 48 hours; delayed primary closure or split-skin graft thereafter', 'CLEAN_CONTAMINATED', 'Elevate to heart level after release; analgesia and generous IV fluids — monitor urine output and urine colour for myoglobinuria; relook at 48 hours mandatory; splint foot plantigrade to prevent equinus; begin physiotherapy once closed; counsel about possible skin graft and sensory changes near incisions'),
  ('ENT', 'TPL-ENT-01', 'Cold steel tonsillectomy', 'Bilateral tonsillectomy by dissection', 'Supine with head extended (Rose position), shoulder roll; surgeon at head of table', 'General anaesthesia with secured (preferably south-facing RAE) tube; Boyle-Davis gag with appropriate blade; confirm no loose teeth; suction checked', 'No skin incision; mucosal incision along the anterior pillar at the upper pole of the tonsil', '1. Insert and suspend Boyle-Davis gag, confirm ventilation unchanged; 2. Grasp upper pole of tonsil and incise anterior pillar mucosa; 3. Develop the peritonsillar (capsular) plane with blunt dissection; 4. Dissect the tonsil from upper pole towards lower pole staying on the capsule; 5. Control the lower pole pedicle with snare or ligature; 6. Pack the fossa and repeat on the opposite side; 7. Achieve absolute haemostasis with ties or bipolar — inspect both fossae after removing packs; 8. Release gag briefly and re-inspect for bleeding before waking', 'Bipolar dissection where diathermy available; unilateral tonsillectomy for asymmetric enlargement (send for histology); interval vs quinsy tonsillectomy per department policy', 'No closure — fossae heal by secondary intention; ties or bipolar for vessels only', 'CLEAN_CONTAMINATED', 'Encourage early oral fluids and normal diet including rough foods; regular analgesia by the clock for 7-10 days; expect white slough in the fossae (not infection) and referred ear pain; overnight observation minimum; counsel that bleeding at any point up to day 10 mandates immediate return — secondary haemorrhage peaks day 5-9'),
  ('ENT', 'TPL-ENT-02', 'Adenoidectomy by curettage', 'Adenoidectomy (usually combined with tonsillectomy or grommets)', 'Supine, Rose position with shoulder roll', 'General anaesthesia, secured tube; gag inserted as for tonsillectomy; soft palate palpated to exclude submucous cleft (notched hard palate posterior edge) before curettage', 'No incision; transoral curettage of the nasopharynx', '1. Palpate the nasopharynx to size the adenoid pad and exclude aberrant vessels and submucous cleft; 2. Seat the adenoid curette against the posterior nasopharyngeal wall at the choanae; 3. Sweep the pad in one controlled stroke, keeping midline; 4. Remove residual tags with smaller curette or punch; 5. Pack the nasopharynx with a swab for timed pressure haemostasis; 6. Remove pack, inspect via mirror or palpation; 7. Confirm haemostasis before waking', 'Suction diathermy ablation where equipment available; partial adenoidectomy in submucous cleft (or abandon and refer)', 'No closure; haemostasis by packing pressure, diathermy only if persistent bleeding', 'CLEAN_CONTAMINATED', 'Day-case where observed 6 hours and bleeding-free; normal diet; nasal blockage and hyponasal voice settle over 1-2 weeks; return immediately for fresh bleeding from nose or mouth; review only if symptoms persist at 6 weeks'),
  ('ENT', 'TPL-ENT-03', 'Open surgical tracheostomy', 'Elective/urgent tracheostomy in adult', 'Supine with shoulder roll and neck extended (as far as airway safety allows)', 'Ideally over an existing endotracheal tube in theatre; tube selection and cuff checked; anaesthetist briefed on the moment of airway exchange; suction and two tube sizes ready', 'Transverse skin incision midway between cricoid cartilage and sternal notch', '1. Divide skin, platysma and fascia in the midline, retracting strap muscles laterally; 2. Divide or retract the thyroid isthmus with control of its vessels; 3. Confirm the cricoid and count tracheal rings — window at rings 2-4, never ring 1; 4. Haemostasis before opening the airway; 5. Anaesthetist withdraws the endotracheal tube tip under vision as the trachea is opened (window or Bjork flap per preference); 6. Insert the tracheostomy tube, inflate the cuff, confirm end-tidal CO2/chest movement; 7. Secure with tapes AND stay sutures (label the Bjork flap/stay sutures for emergency reintubation); 8. Loose skin approximation only — never airtight around the tube', 'Vertical incision in the emergency; cricothyroidotomy as the immediate rescue converted to formal tracheostomy within 72 hours; percutaneous technique only in ICU settings with bronchoscopic guidance', 'Loose skin approximation around the tube; tapes plus flange sutures; keep dressing simple to allow inspection', 'CLEAN_CONTAMINATED', 'Humidified air/oxygen continuously; suction as needed with clean technique; spare tube (same size and one smaller), dilators and stitch cutter fixed to the bed; nil by mouth until swallow assessed; first tube change at day 5-7 by experienced staff; cuff pressure checked each shift; emergency algorithm poster at the bedside'),
  ('ENT', 'TPL-ENT-04', 'Modified radical (canal wall down) mastoidectomy', 'Mastoid exploration and cholesteatoma clearance', 'Supine, head turned away on a head-ring; ear uppermost; facial nerve monitoring where available (not a substitute for anatomy)', 'General anaesthesia; hair shaved 2 cm around the postauricular crease; microscope draped and checked; pre-operative audiogram and facial function documented on the consent', 'Postauricular (Wilde) incision 5 mm behind the crease', '1. Elevate the postauricular flap and harvest temporalis fascia graft; 2. Expose Macewen triangle and cortical mastoid; 3. Cortical mastoidectomy with burr, identifying tegmen, sigmoid sinus and antrum; 4. Follow disease forward, taking down the canal wall to exteriorise the attic and mesotympanum; 5. Identify the facial nerve (vertical segment) and lateral semicircular canal — the two constant landmarks — and clear cholesteatoma matrix off them with utmost care; 6. Lower the facial ridge sufficient for a self-cleaning cavity; 7. Perform wide meatoplasty; 8. Graft the tympanic membrane remnant/line the cavity with fascia; 9. Pack cavity with antiseptic-impregnated ribbon gauze or dissolvable packing', 'Canal-wall-up with staged second look where reliable follow-up exists; atticotomy alone for disease limited to the attic; ossicular reconstruction deferred to a second stage', 'Postauricular wound in two layers; meatal packing left 2-3 weeks', 'CLEAN_CONTAMINATED', 'Keep ear strictly dry; analgesia; warn about taste disturbance (chorda tympani) and transient dizziness; facial function checked and charted in recovery and daily; pack removal at 2-3 weeks in clinic; lifelong (at least annual) cavity inspection and cleaning — book before discharge; report vertigo, facial weakness or foul discharge immediately'),
  ('ENT', 'TPL-ENT-05', 'Drainage of peritonsillar abscess (quinsy)', 'Needle aspiration and/or incision and drainage under local anaesthesia', 'Patient sitting upright, head supported; good light and suction essential; standby suction ON before incision', 'Topical/local anaesthetic spray to the mucosa; cooperative adult — children and the trismus-bound go to theatre; wide-bore needle, scalpel with blade guarded to 1 cm, tonsil forceps ready', 'Point of maximal bulging of the anterior pillar, classically at the intersection of a horizontal line through the uvula base and a vertical line along the anterior pillar', '1. Confirm the diagnosis and mark the point of maximal fluctuance; 2. Aspirate with a wide-bore needle — pus confirms and partially decompresses; 3. Make a short stab incision through mucosa at the same point, blade guarded shallow (the internal carotid lies posterolateral); 4. Open the cavity with closed forceps and spread; 5. Suction pus, send sample for culture; 6. Encourage the patient to gargle and spit; 7. Reassess trismus and swallowing before discharge decision', 'Repeated needle aspiration alone (no incision) is acceptable first-line; immediate quinsy tonsillectomy only where recurrent disease and theatre resources align', 'No closure; cavity drains into the mouth', 'CONTAMINATED', 'IV then oral antibiotics covering streptococci and anaerobes per local policy; analgesia and warm saline gargles; oral fluids as tolerated — most swallow noticeably better within hours; review in 24-48 hours or sooner if swallowing worsens; counsel about interval tonsillectomy if this is a recurrence'),
  ('OPHTHALMOLOGY', 'TPL-OPHT-01', 'Manual small-incision cataract surgery (MSICS) with PCIOL', 'MSICS with posterior chamber intraocular lens implantation', 'Supine under operating microscope; head stabilised, drape tented off the face with oxygen under the drape', 'Local anaesthesia (peribulbar/sub-Tenon) with monitored sedation as needed; pupil dilated per drop protocol; povidone-iodine to conjunctival sac before draping — the single most evidence-supported endophthalmitis precaution; IOL power from biometry confirmed on the whiteboard', 'Frown-shaped sclerocorneal tunnel 6-7 mm, 1.5-2 mm behind the limbus, self-sealing internal corneal lip', '1. Fornix-based conjunctival flap and light cautery; 2. Construct the scleral tunnel in one-half scleral depth, dissect forward into clear cornea; 3. Side-port paracentesis; 4. Enter the anterior chamber through the tunnel with keratome; viscoelastic to maintain chamber; 5. Continuous curvilinear capsulorhexis (can-opener acceptable for white/intumescent cataract with trypan blue staining); 6. Hydrodissect and prolapse the nucleus into the anterior chamber; 7. Deliver the nucleus through the tunnel with irrigating vectis protecting the endothelium; 8. Aspirate cortical remnants with Simcoe cannula; 9. Implant PCIOL into the capsular bag, dial into position; 10. Wash out viscoelastic, confirm the tunnel is watertight, reposition conjunctiva', 'Phacoemulsification where machine, consumables and case-mix suit; extracapsular extraction with sutured wound for very large nuclei; anterior chamber IOL or aphakic spectacles where posterior capsule support is lost', 'Sutureless self-sealing tunnel; single 10-0 nylon suture if any doubt about wound integrity; subconjunctival antibiotic and steroid at close per unit policy', 'CLEAN', 'Eye shield overnight and at sleep for 1 week; topical antibiotic-steroid drops per tapering protocol; no eye rubbing, no dirty water contact for 2 weeks; review day 1 (acuity, wound, IOP, anterior chamber), week 1-2, and refraction at 4-6 weeks; counsel immediate return for pain with worsening vision — see endophthalmitis danger rule'),
  ('OPHTHALMOLOGY', 'TPL-OPHT-02', 'Trabeculectomy', 'Guarded filtration surgery for glaucoma', 'Supine under operating microscope; superior approach with bridle/corneal traction suture for downgaze exposure', 'Local (peribulbar/sub-Tenon) or general anaesthesia; povidone-iodine preparation; review target pressure and antimetabolite decision per unit policy before starting', 'Fornix- or limbus-based conjunctival flap at the superior limbus; partial-thickness scleral flap approximately 4x3 mm', '1. Raise the conjunctival/Tenon flap and clear the limbal bed with light cautery; 2. Outline and dissect a half-thickness scleral flap into clear cornea; 3. Apply antimetabolite-soaked sponges under flap per policy, then irrigate copiously; 4. Paracentesis for later chamber control; 5. Excise an inner sclerostomy block under the flap with punch or blade; 6. Peripheral iridectomy through the sclerostomy; 7. Close the scleral flap with releasable or fixed 10-0 nylon sutures titrated to controlled flow; 8. Close conjunctiva watertight; 9. Reform the chamber via paracentesis and confirm bleb formation without leak (Seidel check)', 'Combined phaco/MSICS-trabeculectomy for coexisting cataract; tube-shunt surgery at central level for failed filtration; cyclophotocoagulation for refractory/blind painful eyes', 'Scleral flap 10-0 nylon (releasable where postop titration planned); conjunctiva closed watertight with 10-0/8-0 vicryl; subconjunctival steroid/antibiotic away from the bleb', 'CLEAN', 'Topical steroid intensively then tapered over 2-3 months, topical antibiotic for 2 weeks; do NOT stop steroids early — bleb fibrosis is the main failure mode; review day 1, week 1, then per bleb behaviour (suture release/massage as needed); lifelong risk of bleb infection: any red sticky painful eye is an emergency; avoid heavy lifting and eye rubbing for a month'),
  ('OPHTHALMOLOGY', 'TPL-OPHT-03', 'Pterygium excision with conjunctival autograft', 'Excision of pterygium and free conjunctival autografting', 'Supine under operating microscope', 'Topical plus subconjunctival local anaesthesia; povidone-iodine preparation; operating loupe acceptable where no microscope, but graft handling favours the microscope', 'Incision around the pterygium body onto clear cornea at the head; separate superior bulbar harvest site for the graft', '1. Infiltrate under the pterygium body to balloon it off sclera; 2. Avulse/dissect the head off the cornea aiming for a smooth Bowman plane, minimal scraping; 3. Excise the body with associated Tenon tissue, sparing the medial rectus — positively identify it before cutting; 4. Light haemostasis leaving some vessels open for graft nutrition; 5. Measure the bare-sclera defect; 6. Harvest a thin superior bulbar conjunctival autograft of matching size, Tenon-free; 7. Orient limbus-to-limbus and fix the graft with 8-0/10-0 sutures or fibrin glue where stocked; 8. Confirm graft edges apposed and not inverted', 'Conjunctival rotation flap where autograft not possible; amniotic membrane at units that stock it; bare sclera technique NOT acceptable (recurrence); adjunctive mitomycin per senior policy only for recurrent disease', 'Graft sutured or glued; harvest site left to epithelialise; pad the eye for the first day', 'CLEAN', 'Topical antibiotic-steroid combination for 3-4 weeks tapering; oral analgesia for the first 48 hours (corneal defect pain); sunglasses and UV avoidance long term; review week 1 (graft in place, epithelial defect closing) and month 1-3 for recurrence; warn that recurrence is possible and re-presents as regrowth of vessels onto the cornea'),
  ('OPHTHALMOLOGY', 'TPL-OPHT-04', 'Primary repair of open globe injury', 'Corneal/scleral laceration repair', 'Supine under operating microscope; general anaesthesia strongly preferred — avoid peribulbar injection into an open eye and avoid depolarising pressure on the globe per anaesthetic planning', 'Rigid shield stays on until draped; povidone-iodine gently, no pressure; final documented pre-anaesthetic acuity confirmed on record; systemic antibiotics and tetanus already running', 'No new incision unless needed to explore the wound; peritomy to expose scleral extension of the laceration', '1. Examine gently under the microscope, map the full wound extent — follow scleral wounds posteriorly with progressive peritomy; 2. Excise or reposit prolapsed tissue per viability (reposit uvea where clean, abscise devitalised tissue); 3. Close the cornea with interrupted 10-0 nylon, first suture at the limbus to restore the anatomical landmark, long bites at the limbus grading shorter centrally, knots buried; 4. Reform the anterior chamber (air/balanced solution) and confirm watertightness; 5. Close sclera anteriorly-to-posteriorly with 8-0/9-0 nylon as the wound is progressively exposed; 6. Stop posterior dissection where the wound extends beyond safe reach — document rather than pursue; 7. Subconjunctival antibiotics; 8. Shield (not pad) applied', 'Primary evisceration/enucleation is NOT performed at primary repair except in exceptional destroyed-globe cases after senior two-surgeon agreement; intraocular foreign body management staged to vitreoretinal referral', 'Cornea 10-0 nylon buried knots; sclera 8-0/9-0; conjunctiva closed over scleral repairs; rigid shield always', 'CONTAMINATED', 'Systemic antibiotics continued per protocol; topical antibiotic and steroid, cycloplegic for comfort; strict no eye rubbing, shield at all times initially; daily review while inpatient for infection signs; early referral for vitreoretinal assessment where posterior involvement; counsel about sympathetic ophthalmia symptoms in the FELLOW eye (photophobia, blurring) mandating urgent review; suture removal planned at microscope in clinic'),
  ('OPHTHALMOLOGY', 'TPL-OPHT-05', 'Bilamellar tarsal rotation for trachomatous trichiasis', 'Correction of cicatricial entropion with trichiasis (upper lid)', 'Supine; procedure suited to field/outreach theatre with good lighting and loupes', 'Local infiltration of the upper lid; lid everted to confirm tarsal conjunctival scarring; corneal state and acuity documented beforehand', 'Full-thickness horizontal lid incision 3 mm from and parallel to the lash margin, across the width of the trichiatic segment', '1. Place a lid guard/plate to protect the globe; 2. Infiltrate and mark the incision line 3 mm above the lash line; 3. Full-thickness incision through skin, orbicularis, tarsus and conjunctiva; 4. Mobilise the distal (marginal) fragment; 5. Pass three double-armed everting sutures from the proximal tarsus emerging through skin just above the lashes, rotating the margin outwards; 6. Tie over the skin to hold the margin in slight over-correction; 7. Confirm no lash-globe contact in all gaze positions; 8. Antibiotic ointment and pad', 'Trabut (posterior approach) technique per surgeon training; epilation only as an interim measure for minor peripheral trichiasis', 'Everting sutures left 8-14 days then removed; skin edges usually need no separate closure', 'CLEAN', 'Antibiotic eye ointment for 2 weeks; pad off next day; suture removal at 8-14 days at the nearest facility; review corneal surface at removal; counsel that under- or over-correction and recurrence occur and re-operation is possible; record in trachoma programme register where applicable'),
  ('VASCULAR', 'TPL-VASC-01', 'Femoral embolectomy', 'Balloon catheter embolectomy of the femoral artery', 'Supine; both groins and the whole affected limb prepped and visible (foot in a clear bag to observe reperfusion)', 'Can be performed under local anaesthesia with sedation in the unfit; systemic heparinisation before arterial clamping per anaesthetic coordination; embolectomy catheters of appropriate sizes confirmed present before incision', 'Vertical groin incision over the common femoral artery', '1. Expose and sling common, superficial and profunda femoral arteries; 2. Systemic heparin given, then clamp all three vessels; 3. Transverse arteriotomy over the common femoral bifurcation; 4. Pass the balloon catheter proximally, inflate and withdraw to retrieve thrombus until forceful inflow; 5. Pass distally down superficial and profunda vessels repeatedly until no further clot and backbleeding obtained; 6. Flush with heparinised saline; 7. Close the arteriotomy transversely (vein patch if the vessel is small or diseased); 8. Release clamps in sequence, confirm distal perfusion — foot colour, capillary return, Doppler signal; 9. Assess calf compartments and decide on fasciotomy before leaving theatre', 'Over-the-wire catheters and completion imaging where available; catheter-directed thrombolysis at interventional centres for distal thrombus; primary amputation for the irreversibly ischaemic limb', 'Arteriotomy with fine monofilament vascular suture; groin closed in layers over the repair; skin per preference', 'CLEAN', 'Continue anticoagulation per protocol and investigate the embolic source (ECG for AF, echocardiography); hourly foot perfusion and compartment checks for 24 hours; watch urine output and colour for reperfusion injury (myoglobinuria, hyperkalaemia); mobilise once stable; long-term anticoagulation decision documented before discharge'),
  ('VASCULAR', 'TPL-VASC-02', 'Below-knee amputation (long posterior flap)', 'Below-knee amputation by Burgess long posterior flap technique', 'Supine; thigh tourniquet optional (often avoided in ischaemic limbs); sandbag under thigh', 'Regional (spinal) or general anaesthesia; prophylactic IV antibiotic at induction, therapeutic antibiotics if amputating for sepsis; mark the level — bone section a hand''s breadth (10-12 cm) below the tibial tuberosity; consent covers possible conversion to above-knee', 'Skin incision marking a short anterior flap and long posterior myocutaneous flap (posterior flap length approximately one-third limb circumference plus 1 cm)', '1. Incise skin and deep fascia along the marked flaps; 2. Divide anterior and lateral compartment muscles at the level of bone section, ligating the anterior tibial vessels; 3. Divide and gently retract, then section the tibia with a bevelled anterior cut, file edges smooth; 4. Divide the fibula 1-2 cm shorter than the tibia; 5. Develop the long posterior flap of gastrocnemius/soleus, tapering the muscle bulk; 6. Ligate posterior tibial and peroneal vessels; divide nerves under gentle traction with sharp knife so they retract proximally (tibial nerve ligated with its vessels); 7. Release tourniquet (if used) and achieve complete haemostasis; 8. Bring the posterior flap forward over the bone ends; 9. Close fascia to anterior fascia/periosteum over a drain', 'Skew flap technique per training; guillotine amputation as the first stage in gross sepsis with delayed definitive closure; through-knee or above-knee where the calf is non-viable', 'Myofascial layer with interrupted absorbable sutures, skin with interrupted non-absorbable sutures without tension; suction or corrugated drain 24-48 h; soft bulky dressing — no constricting bandage', 'CLEAN_CONTAMINATED', 'Analgesia including pre-emptive management of phantom limb pain; drain out at 24-48 h; stump elevated on a board, NOT on a pillow under the knee (flexion contracture risk); daily stump checks; knee extension exercises from day 1 and prone lying daily; physiotherapy and prosthetic referral before discharge; sutures 14-21 days; stump bandaging/shrinker socks taught to patient and family'),
  ('VASCULAR', 'TPL-VASC-03', 'Radiocephalic arteriovenous fistula', 'Autogenous wrist arteriovenous fistula for haemodialysis access', 'Supine with arm on an arm board, non-dominant wrist preferred; loupes recommended', 'Local anaesthesia infiltration; confirm Allen test and preserve-vein history; tourniquet-free technique; fine vascular instruments and monofilament sutures ready', 'Longitudinal or lazy-S incision between radial artery and cephalic vein at the wrist', '1. Mobilise the cephalic vein over 2-3 cm, ligating tributaries; 2. Expose the radial artery, sling with vessel loops; 3. Confirm vein calibre and free flow by gentle saline distension; 4. Systemic/local heparin per unit policy; 5. Arteriotomy 6-8 mm; spatulate the vein; 6. End-of-vein to side-of-artery anastomosis with continuous fine monofilament; 7. Release clamps — confirm a palpable thrill (a pulse without thrill suggests outflow problem: revise now); 8. Haemostasis with patience and light pressure, not diathermy near the anastomosis', 'Brachiocephalic fistula at the elbow where wrist vessels are inadequate; basilic vein transposition or graft at central level as later options', 'Subcutaneous tissue loosely approximated, skin with interrupted sutures; NO circumferential dressing', 'CLEAN', 'Arm elevated on a pillow, no blood pressure cuffs, cannulation or tight sleeves on that arm — flag the limb in the record; teach the patient to check the thrill daily and report its loss the same day; hand exercises (ball squeezing) to encourage maturation; review at 2 and 6 weeks for maturation; first cannulation not before 6 weeks and by trained dialysis staff'),
  ('VASCULAR', 'TPL-VASC-04', 'High saphenous ligation and stripping', 'Saphenofemoral junction ligation with stripping of the great saphenous vein and stab avulsions', 'Supine with slight head-down tilt and leg externally rotated; varicosities marked pre-operatively with the patient STANDING', 'General or spinal anaesthesia; prophylactic antibiotic only per local policy for redo/ulcerated cases; marking verified before prep', 'Oblique groin incision over the saphenofemoral junction 2-3 cm below and lateral to the pubic tubercle; small distal incision at knee level for the stripper; 2-3 mm stab incisions over marked varicosities', '1. Dissect to the saphenofemoral junction and positively identify the common femoral vein above and below the junction — this identification is the safety step of the operation; 2. Ligate and divide all junction tributaries; 3. Flush-ligate and divide the great saphenous vein at the junction; 4. Pass the stripper down the vein to knee level (strip to knee only — below-knee stripping risks saphenous nerve injury); 5. Strip the vein with distal counter-pressure; 6. Complete stab avulsions of marked varicosities with hook or forceps; 7. Elevate and compress the strip track for several minutes; 8. Confirm haemostasis at all sites', 'Endovenous thermal/foam ablation where equipment exists; isolated junction ligation with foam for the frail; small-saphenous surgery prone with popliteal fossa caution', 'Groin in two layers; stab incisions closed with adhesive strips; firm bandaging from foot to thigh applied in theatre', 'CLEAN', 'Day-case where social circumstances allow; keep bandages 5-7 days then graduated compression stockings for 4-6 weeks; walk immediately and frequently — avoid standing still; analgesia; bruising along the strip track is expected; review at 6 weeks; advise that recurrence over years is possible and compression habits reduce it'),
  ('VASCULAR', 'TPL-VASC-05', 'Debridement of diabetic foot sepsis', 'Incision, drainage and radical debridement of diabetic foot infection (ray amputation where a toe source)', 'Supine; ankle tourniquet only if perfusion adequate — usually omitted in the ischaemic foot', 'Do not wait for glycaemic perfection to drain pus — resuscitate and operate in parallel; broad-spectrum IV antibiotics after deep cultures planned; radiographs reviewed for gas and osteomyelitis', 'Incision directly over the fluctuant/indurated area, extended proximally along the tracking plantar spaces as pus dictates', '1. Open the abscess and take deep tissue (not swab) cultures immediately; 2. Lay open all tracking collections — follow the pus along tendon sheaths and plantar compartments; 3. Excise all necrotic skin, fat, fascia, tendon and infected bone back to healthy bleeding tissue; 4. Ray amputation of the source toe and metatarsal head where the toe is unsalvageable; 5. Irrigate copiously; 6. Assess perfusion of remaining tissue and record it — poor bleeding raises the revascularisation/higher-amputation question; 7. Leave the wound OPEN, loosely packed; 8. Plan and book the relook at 24-48 hours before leaving theatre', 'Guillotine/open ankle-level amputation for extensive non-salvageable sepsis; negative-pressure dressings where devices exist, saline-gauze packing otherwise', 'Never closed primarily; healing by secondary intention, delayed closure or later grafting once clean', 'DIRTY', 'IV antibiotics rationalised to deep-culture results; strict offloading of the foot (no weight-bearing — crutches or bed rest with heel protection); daily dressings; glycaemic control programme and diabetic team involvement; relook debridement at 24-48 h as booked; before discharge: footwear/offloading plan, dressing supply, and review of the OTHER foot documented'),
  ('NEUROSURGERY', 'TPL-NEUR-01', 'Burr hole drainage of chronic subdural haematoma', 'Single or double burr hole evacuation and irrigation of chronic subdural haematoma', 'Supine with head turned, haematoma side up, on a head-ring; head-up tilt slight', 'Can be done under local anaesthesia with sedation in the frail elderly; coagulopathy corrected and anticoagulants reversed beforehand; imaging on display in theatre; prophylactic antibiotic at induction', 'Scalp incisions over the parietal boss and (if second hole) frontal region, planned so they could be joined into a trauma flap if conversion needed', '1. Infiltrate, incise scalp to bone and place a self-retaining retractor; 2. Drill the burr hole with perforator; 3. Coagulate then open the dura in a cruciate fashion — expect dark motor-oil fluid under pressure; 4. Let the haematoma drain spontaneously, do not suck at the brain; 5. Irrigate gently with warmed saline in multiple directions until returns are clear; 6. Second burr hole if drainage/irrigation incomplete; 7. Place a soft subdural drain directed away from cortex where stocked; 8. Fill the cavity with saline to exclude air before closure', 'Twist-drill bedside drainage in selected fragile patients; craniotomy for the organised, membranous or acutely rebled collection', 'Scalp in two layers (galea then skin); drain tunnelled and secured, connected to a closed gravity system (not vacuum) for 24-48 h', 'CLEAN', 'Nurse FLAT or slightly head-down for the first 24-48 hours to encourage brain re-expansion (unit protocol); hourly neuro-observations for 24 hours; drain out at 24-48 h; mobilise gradually thereafter; restart anticoagulation only after documented senior decision; counsel patient and family about recurrence symptoms — drowsiness, worsening headache, new weakness — and give a direct return route'),
  ('NEUROSURGERY', 'TPL-NEUR-02', 'Trauma craniotomy for acute extradural haematoma', 'Craniotomy and evacuation of extradural haematoma', 'Supine, head on ring turned to expose the affected side; whole hemicranium shaved and prepped; head-up 15-20 degrees', 'General anaesthesia with neuroprotective conduct (normotension, normocapnia, avoid hypoxia); blood available; imaging displayed; osmotherapy per anaesthetic team for pupil signs while draping', 'Question-mark trauma flap centred on the haematoma (commonly temporoparietal), or a linear temporal incision extended as needed when performed as a resource-limited rescue', '1. Raise the scalp flap preserving the superficial temporal artery pedicle where possible; 2. Burr holes and free bone flap over the haematoma; 3. Evacuate clot with suction and irrigation; 4. Find and control the bleeding source — commonly the middle meningeal artery: coagulate or plug the foramen spinosum if needed; 5. Inspect dural edges circumferentially for continued oozing; 6. Hitch the dura to the bone edge with peripheral tack-up sutures to close the extradural space; 7. Central dural hitch through the bone flap; 8. Replace and fix the bone flap; 9. Close over a subgaleal drain', 'Single exploratory temporal burr hole (side of the fixed pupil first) at non-CT district level as damage control before transfer; craniectomy with flap left off where brain swelling supervenes', 'Dura tacked up, bone flap replaced and secured (sutures/miniplates per stock), galea and skin in layers over a subgaleal drain', 'CLEAN', 'ICU/HDU with hourly GCS and pupils for at least 24 hours; head-up 30 degrees once stable; analgesia that does not obscure assessment; repeat imaging for any deterioration; drain out at 24-48 h; seizure-prophylaxis decision documented; wound review and suture/clip removal at 7-10 days; head-injury advice sheet to family on discharge'),
  ('NEUROSURGERY', 'TPL-NEUR-03', 'Ventriculoperitoneal shunt insertion', 'Frontal or parieto-occipital ventriculoperitoneal shunt for hydrocephalus', 'Supine, head turned away from the shunt side, neck and trunk in one exposed line from scalp to abdomen; roll under shoulders', 'Meticulous asepsis is the heart of this operation: minimal implant handling, antibiotic prophylaxis at induction, double gloving, shunt opened last and soaked per unit protocol; exclude active CSF infection beforehand', 'Small scalp incision at Kocher point (or parieto-occipital flap point); separate small transverse upper-quadrant abdominal incision; subcutaneous tunnel connecting the two', '1. Position and mark burr hole site and abdominal incision; 2. Scalp incision, burr hole, coagulate and nick the dura minimally; 3. Open the abdominal incision to the peritoneum and confirm entry (or prepare for open mini-laparotomy passage); 4. Pass the tunneller from abdominal to cranial wound in the subcutaneous plane, delivering the distal catheter; 5. Cannulate the ventricle with the ventricular catheter (frontal: aim perpendicular, roughly towards inner canthus/tragus planes), confirm CSF flow, note opening pressure; 6. Connect catheter-valve-distal system with secure ties, orientation of valve confirmed; 7. Confirm distal CSF dripping from the abdominal end; 8. Place the distal catheter into the peritoneal cavity with generous length for growth; 9. Close both wounds in layers without tension over the hardware', 'Endoscopic third ventriculostomy (with choroid plexus cauterisation in infants) at endoscopy-capable centres for obstructive patterns; ventriculo-atrial shunt only where peritoneum unusable', 'Galea and skin over the burr hole; abdominal wall in layers; no drains; dressings kept minimal over hardware', 'CLEAN', 'Observe for CSF leak from either wound (report immediately); feed when awake; head circumference (infants) recorded before discharge as the new baseline; caregiver taught the shunt-failure triad — vomiting, drowsiness, bulging fontanelle/headache — and the infection signs, with a direct return pathway; review at 2 weeks and 3 months with head-circumference chart; document valve type and setting on the discharge record'),
  ('NEUROSURGERY', 'TPL-NEUR-04', 'Elevation of compound depressed skull fracture', 'Debridement and elevation of open depressed skull fracture with dural inspection', 'Supine or lateral per fracture site, head on ring; wide shave and prep around the wound', 'General anaesthesia; IV antibiotics continued from admission, tetanus confirmed; imaging displayed; blood available if venous-sinus proximity suspected — do NOT elevate fragments over a major venous sinus without senior/central support', 'Extend the scalp laceration or incorporate it into a formal flap providing exposure of the whole depressed segment', '1. Debride the scalp wound edges and remove foreign material and hair; 2. Expose the fracture margins fully; 3. Place a burr hole adjacent to intact bone at the fracture edge; 4. Elevate the depressed fragments working from intact bone towards the centre; remove contaminated loose fragments, wash and preserve clean large ones; 5. Inspect the dura: if torn, enlarge exposure enough to inspect underlying cortex, remove in-driven debris and achieve haemostasis; 6. Repair the dura primarily or with pericranial graft to a watertight closure; 7. Replace cleaned viable bone fragments (or leave a defect for later cranioplasty if heavily contaminated); 8. Irrigate copiously throughout; 9. Close scalp in two layers without tension', 'Non-operative care for closed depressions without dural injury, deficit or cosmetic concern; craniectomy leaving the defect where contamination or swelling dictates', 'Watertight dural closure is the non-negotiable step; scalp galea-then-skin; subgaleal drain if raw surface large', 'CONTAMINATED', 'Continue antibiotics per protocol; hourly neuro-observations for 24 hours; seizure counselling and prophylaxis decision documented (early seizures are a recognised risk); wound review at 48-72 h; advise family about late infection signs (fever, swelling, discharge) and CSF leak (clear fluid from wound or nose) as immediate-return triggers; cranioplasty planning at 3-6 months where a defect was left'),
  ('NEUROSURGERY', 'TPL-NEUR-05', 'Myelomeningocele closure', 'Layered closure of open lumbosacral myelomeningocele in the neonate', 'Prone on chest-and-pelvis rolls, abdomen free; theatre warmed for the neonate; latex-free set-up', 'Neonatal anaesthesia team; cross-matched blood aware (rarely needed); defect kept moist with saline swabs until draped; antibiotics at induction; head circumference and leg movement documented pre-operatively as baseline', 'Elliptical incision at the junction of the zone of thin abnormal epithelium and normal skin, planned around the placode', '1. Incise the junctional zone and free the neural placode from the surrounding epithelium, trimming all epithelial remnants (dermoid prevention); 2. Allow the placode to drop into the canal; pial edges may be loosely approximated to re-tube the placode; 3. Identify and mobilise the dural edges laterally; 4. Close the dura in a watertight tube over the placode; 5. Mobilise fascia (thoracolumbar) as flaps and close as a second layer where achievable; 6. Undermine skin widely in the plane above fascia to achieve tension-free midline skin closure; relaxing techniques/rotation only if required; 7. Confirm no CSF leak with gentle Valsalva by anaesthetist; 8. Dress with a non-adherent dressing protected from stool contamination', 'Skin-only closure as damage control where layered closure defeats the available expertise, with early referral; plastic-surgical flap assistance for very large defects', 'Watertight dura, fascial layer where possible, tension-free skin; occlusive dressing shielded from the nappy area', 'CLEAN_CONTAMINATED', 'Nurse prone or lateral, wound off pressure, meticulous stool/urine barrier care; observe fontanelle tension and DAILY head circumference — hydrocephalus commonly declares after closure and a shunt decision follows; document leg movement and bladder pattern; feed normally; wound review at 48-72 h; refer to spina bifida multidisciplinary follow-up (urology bladder programme, orthopaedics, physiotherapy) before discharge; folate counselling for the mother recorded'),
  ('CARDIOTHORACIC', 'TPL-CTS-01', 'Intercostal chest drain insertion (safe triangle, blunt technique)', 'Tube thoracostomy for pneumothorax, haemothorax or effusion', 'Semi-recumbent at 45 degrees with the arm abducted behind the head; emergency cases as found', 'Local anaesthetic infiltration to skin, muscle and pleura (generous, includes rib periosteum); sterile field; drain size chosen for content (large-bore for blood/pus); underwater-seal bottle primed and BELOW the patient before starting', 'Skin incision one intercostal space within the safe triangle (anterior to mid-axillary line, above the 5th intercostal space, below the axilla), placed just above the lower rib of the space', '1. Confirm side against imaging AND clinical signs — mark and time-out; 2. Infiltrate and confirm air/fluid aspiration with the exploring needle; 3. Incise skin 2-3 cm; 4. Blunt-dissect with forceps over the top of the rib through intercostal muscle; 5. Puncture the pleura with the closed forceps, feel the give, and sweep a finger to confirm the space and exclude adherent lung; 6. Insert the drain WITHOUT the trocar, directing apically for air, basally for fluid; 7. Connect to the underwater seal and confirm swinging/bubbling or drainage; 8. Anchor with a heavy suture and place an untied closure suture; occlusive dressing; 9. Post-procedure radiograph', 'Needle thoracocentesis (2nd space mid-clavicular or 5th space anterior-axillary) then finger thoracostomy as the tension-decompression sequence; small-calibre Seldinger drains for simple effusions where kits exist', 'Drain anchored with heavy non-absorbable suture; closure suture pre-placed for removal day; no purse-string', 'CLEAN_CONTAMINATED', 'Never clamp a bubbling drain; keep the bottle below chest at all times; daily output and swing/bubble charting; analgesia sufficient for deep breathing and physiotherapy; remove when criteria met (see monitoring rule) with breath-hold technique and immediate occlusion; post-removal radiograph; drain safety card at the bedside for transfers'),
  ('CARDIOTHORACIC', 'TPL-CTS-02', 'Posterolateral thoracotomy and decortication of empyema', 'Decortication of organised empyema (fibrothorax) with trapped lung', 'Lateral decubitus over a break in the table, affected side up, arm forward on a support; single-lung ventilation where anaesthetic capability exists', 'General anaesthesia (double-lumen tube preferred, not mandatory); blood cross-matched — decortication bleeds; recent CT reviewed; TB status and therapy documented; two suctions available', 'Posterolateral thoracotomy through the 5th or 6th intercostal space, dividing latissimus dorsi and sparing serratus where possible', '1. Enter the chest carefully — the lung may be adherent to the wall; develop the extrapleural plane if the space is obliterated; 2. Evacuate pus and debris, samples to microbiology including TB studies and histology; 3. Define the visceral cortex (peel) over the trapped lung; 4. Incise the peel cautiously to the correct plane and strip it from the visceral pleura with blunt/sharp dissection, working systematically — the anaesthetist inflates intermittently to demonstrate re-expansion and the plane; 5. Repair significant air leaks; small raw-surface leaks are accepted; 6. Free the diaphragm and costophrenic recess; strip parietal peel where restricting the wall; 7. Meticulous haemostasis of the raw surfaces; 8. Confirm full re-expansion under vision; 9. Two drains: apical (air) and basal (fluid)', 'Rib-resection open drainage (Eloesser-type window) for the frail patient unfit for decortication; VATS debridement at equipped centres for earlier-stage disease', 'Layered closure with pericostal sutures, muscle repair, skin; two intercostal drains to underwater seal', 'CONTAMINATED', 'HDU-level observation; aggressive chest physiotherapy and incentive spirometry from day 1 — re-expansion is the point of the operation; antibiotics per cultures, anti-TB therapy continued/started per programme findings; apical drain out when air leak resolved, basal when serous and low-volume; analgesia adequate for coughing (regional techniques valuable); nutrition assessment — empyema patients are catabolic; review radiograph before each drain removal and at 6-week clinic'),
  ('CARDIOTHORACIC', 'TPL-CTS-03', 'Subxiphoid pericardial window', 'Subxiphoid pericardiostomy for recurrent, purulent or tuberculous pericardial effusion', 'Supine with slight head-up; prepped from mid-chest to umbilicus; echo images available in theatre', 'General anaesthesia with the tamponade caveat: induction can collapse venous return — where tamponade physiology persists, needle decompression under local anaesthesia BEFORE induction is the safe sequence, coordinated with the anaesthetist', 'Vertical 5-6 cm midline incision over and below the xiphisternum', '1. Excise or laterally displace the xiphoid; 2. Develop the plane behind the sternum, sweeping the pleura laterally and staying midline; 3. Identify the diaphragmatic pericardium; 4. Grasp with forceps, confirm fluid by needle aspiration in situ; 5. Open the pericardium sharply between stay sutures — expect fluid under pressure, suck and collect for TB studies, cytology and culture; 6. Excise a generous window of pericardium (send for histology); 7. Explore gently with a finger to break loculations; 8. Place a soft drain within the pericardial sac; 9. Confirm haemodynamic improvement with the anaesthetist before closure', 'Echo-guided pericardiocentesis with pigtail catheter as the immediate non-surgical alternative; anterior thoracotomy window where subxiphoid access fails; pericardiectomy at referral level for constriction', 'Linea alba approximated, subcutaneous and skin closure; pericardial drain to a closed system', 'CLEAN_CONTAMINATED', 'Monitor haemodynamics closely for 24 hours (recurrent tamponade from drain blockage is the early hazard); chart drain output; remove when output minimal and echo shows no reaccumulation; start/continue anti-TB therapy with steroid adjunct per national guideline when TB confirmed or probable; histology and fluid results chased and actioned — malignant effusions route to oncology; echocardiographic review at 4-6 weeks for constriction surveillance'),
  ('CARDIOTHORACIC', 'TPL-CTS-04', 'Emergency thoracotomy for massive haemothorax', 'Anterolateral thoracotomy for control of intrathoracic haemorrhage after trauma', 'Supine with the affected side elevated 15-30 degrees on a roll; whole chest and abdomen prepped; performed where the surgeon and blood are — do not transfer an exsanguinating patient for the incision', 'Massive-transfusion response activated; two suctions, autotransfusion set-up where available; anaesthetic team warned about circulatory collapse on opening; time-out abbreviated but side re-confirmed', 'Anterolateral thoracotomy through the 5th intercostal space on the injured side, extendable across the sternum (clamshell) if bilateral access needed', '1. Enter the chest rapidly, retractor in, evacuate clot and identify the bleeding source; 2. Control lung haemorrhage with hilar compression or a hilar twist if massive; 3. For peripheral lung wounds: stapled/clamp-and-oversew non-anatomical wedge or tractotomy with selective vessel ligation; 4. For chest-wall/intercostal or internal mammary bleeding: suture ligation above and below; 5. Inspect the pericardium — open longitudinally anterior to the phrenic nerve if distended or injury suspected; repair cardiac wounds with pledgeted sutures or staples as damage control; 6. Pack and reassess physiology with the anaesthetist — abbreviate to damage control if cold/coagulopathic; 7. Wash, place apical and basal drains; 8. Close if physiology allows, otherwise temporary closure and escalate/transfer', 'Resuscitative (ED) thoracotomy limited to witnessed arrest with penetrating chest injury per local policy; VATS has no role in the unstable patient', 'Pericostal and layered closure where completed; temporary packing/closure in damage-control mode with planned return', 'CONTAMINATED', 'ICU/HDU; continue balanced blood-product resuscitation and warm the patient; hourly drain output — renewed loss over ~200 ml/hour prompts return to theatre; ventilator weaning per gases; antibiotics per protocol for contaminated trauma; physiotherapy as soon as extubated; document retained-packs plan with explicit return-to-theatre time if damage control was used'),
  ('CARDIOTHORACIC', 'TPL-CTS-05', 'Surgical ligation of patent ductus arteriosus', 'PDA ligation via left thoracotomy in infant/child', 'Right lateral decubitus (left side up), arm forward; paediatric cardiac anaesthesia; done at the national cardiac surgical centre', 'Echocardiogram re-reviewed on the day (duct anatomy, exclusion of duct-dependent circulation); cross-matched blood in theatre; pre-ligation and post-ligation saturations/BP documented', 'Left posterolateral muscle-sparing thoracotomy through the 4th intercostal space', '1. Retract the lung anteriorly and open the mediastinal pleura over the aortic isthmus; 2. Identify the vagus nerve and its recurrent laryngeal branch looping the duct — positive identification before any dissection; 3. Define the triangle: aortic arch, descending aorta, duct; confirm the duct against the echo anatomy (test-occlude and observe pressures/saturation stability); 4. Dissect the duct circumferentially with utmost gentleness — the friable duct tears; 5. Double-ligate with heavy ties (or apply clips per unit practice); division between ligatures per surgeon judgement; 6. Confirm murmur abolition/haemodynamic change with the anaesthetist; 7. Check the recurrent laryngeal nerve visually; 8. Re-expand the lung under vision, single intercostal drain', 'Transcatheter device closure where a catheterisation service and suitable duct anatomy exist; video-assisted clipping in equipped centres', 'Mediastinal pleura loosely approximated, layered chest closure, single drain to underwater seal', 'CLEAN', 'Extubate early where stable; drain out at 24 hours if dry with expanded lung; observe for stridor/weak cry (recurrent laryngeal injury) and chylothorax (milky drainage — dietary fat modification pathway); routine analgesia; echo before discharge confirming no residual duct; growth and feeding review at 6-week paediatric follow-up; no endocarditis prophylaxis needed 6 months after complete closure per standard practice'),
  ('MAXILLOFACIAL', 'TPL-MAXF-01', 'ORIF of mandibular fracture (transoral miniplate)', 'Open reduction and miniplate fixation of parasymphyseal/body mandibular fracture', 'Supine with head-up tilt; nasal endotracheal intubation so the occlusion can be checked intra-operatively; throat pack placed and RECORDED', 'Prophylactic IV antibiotic at induction (fracture is compound into the mouth); chlorhexidine mouth preparation; arch bars/MMF capability ready even when plating — occlusion drives the reduction', 'Intraoral vestibular (gingivobuccal sulcus) incision over the fracture, leaving a cuff of mucosa for closure; mental nerve identified and protected in the premolar region', '1. Apply MMF (arch bars/eyelet wires or MMF screws) and set the teeth into pre-injury occlusion — this IS the reduction; 2. Raise the vestibular flap and expose the fracture subperiosteally; 3. Identify and protect the mental nerve; 4. Debride the fracture line, remove a non-salvageable tooth only when indicated; 5. Reduce anatomically, checking the lower border and lingual cortex; 6. Fix per Champy principles: miniplate along the ideal osteosynthesis line, second plate at the lower border for symphyseal torsional control; 7. Release MMF and verify the occlusion reproduces freely; 8. Irrigate, close mucosa; 9. Remove and DOCUMENT throat pack removal', 'Closed reduction with 4-6 weeks MMF where plating unavailable — an acceptable definitive pathway; external fixation for grossly comminuted/infected fractures; load-bearing reconstruction plate for defect fractures at referral level', 'Watertight mucosal closure with resorbable suture; no drains in routine cases; elastics guidance retained per stability', 'CLEAN_CONTAMINATED', 'Soft (non-chew) diet 4-6 weeks; chlorhexidine mouthwash after every meal; analgesia; if any guiding elastics/MMF retained: wire cutters attached to the patient''s bed/person and airway instructions given to the ward; review at 1 week (occlusion, wound), 6 weeks (union, function); dental review for the tooth in the line of fracture at 6-8 weeks'),
  ('MAXILLOFACIAL', 'TPL-MAXF-02', 'Closed reduction and maxillomandibular fixation (arch bars)', 'Closed reduction of jaw fracture with Erich arch bars and MMF', 'Supine, head-up; nasal intubation; throat pack placed and recorded', 'Full dental charting first — loose teeth, caries and periodontal state alter wire anchorage; prophylactic antibiotic for compound fractures; anti-emetic plan (vomiting in MMF is the feared event) discussed with anaesthesia', 'No incision; circumdental wiring of arch bars to upper and lower arches', '1. Adapt Erich arch bars to each dental arch; 2. Secure with circumdental wires around stable teeth, tails rosetted away from mucosa; 3. Manipulate the fracture and seat the patient''s occlusion by wear facets; 4. Apply intermaxillary wires or elastics to lock the occlusion; 5. Confirm reduction clinically (occlusion, lower-border palpation) and radiographically post-operatively; 6. Confirm the throat pack is OUT and the nose/airway clear before waking; 7. Attach wire cutters to the patient before leaving theatre', 'MMF screws where dentition poor; eyelet (Ivy) wiring as the minimal-stock technique; elastic-only guidance for favourable fractures needing partial immobilisation', 'No wound closure; wire ends turned in and checked against mucosa; MMF period typically 4-6 weeks with weekly checks', 'CLEAN_CONTAMINATED', 'Liquidised high-energy diet with dietetic input — weight loss is expected and monitored; oral hygiene after every intake (syringe rinses, chlorhexidine); wire cutters with the patient AT ALL TIMES and ward staff briefed on emergency release (cut the intermaxillary wires, not the arch bars); anti-emetics prescribed; weekly wire check and occlusion review; fixation off at 4-6 weeks with mobilisation exercises'),
  ('MAXILLOFACIAL', 'TPL-MAXF-03', 'Gillies temporal elevation of zygoma', 'Gillies lift for depressed zygomatic complex/arch fracture', 'Supine, head ring, face turned; temporal region shaved 2-3 cm above and in front of the ear', 'General anaesthesia; eye signs (acuity, diplopia, pupil) documented pre-operatively; imaging displayed; warn recovery staff to observe for retrobulbar haemorrhage post-reduction', 'Oblique 2-2.5 cm incision in the temporal hairline, angled parallel to hair follicles', '1. Incise skin and superficial temporal fascia, avoiding the superficial temporal vessels; 2. Divide the DEEP temporal fascia to enter the plane between it and temporalis muscle — the elevator must pass DEEP to the fascia, superficial to muscle, to slide under the arch; 3. Pass the Bristow/Rowe elevator beneath the zygomatic arch/body; 4. Lift with controlled force in the direction opposite the depression — never lever on the temporal bone; 5. Feel and hear the reduction, palpate the arch, orbital rim and buttress for step correction; 6. Assess stability; an unstable fracture converts to fixation (referral if no plating on site); 7. Check globe: pupil, gentle assessment for proptosis; 8. Close in layers', 'Percutaneous hook reduction for isolated arch fractures; ORIF (rim/buttress miniplates) for unstable or comminuted injuries at referral level', 'Temporal fascia loosely approximated, skin closed; light dressing avoiding pressure over the reduced arch — no tight head bandage', 'CLEAN', 'HOURLY eye observations for the first 12 hours: pain, proptosis, acuity, pupil — retrobulbar haemorrhage is the emergency (immediate senior call, canthotomy pathway); no nose-blowing for 3 weeks (orbital emphysema); no pressure on the cheek — sleep supine, no spectacles resting on the arch for 2 weeks; soft diet if trismus; review at 1 week for position and infraorbital sensation mapping'),
  ('MAXILLOFACIAL', 'TPL-MAXF-04', 'Extraoral drainage of submandibular space abscess', 'Incision and drainage of submandibular/deep neck odontogenic abscess with source-tooth extraction', 'Supine with neck extended and head turned away; airway plan agreed BEFORE induction — trismus and floor-of-mouth swelling may mandate awake techniques', 'IV antibiotics running; glucose checked (diabetic ketoacidosis frequently coexists); anaesthetic airway assessment documented; suction doubled', 'Transverse skin-crease incision 2-3 cm below the lower border of the mandible (protecting the marginal mandibular nerve), centred over the fluctuant area', '1. Incise skin and platysma in the crease; 2. Blunt-dissect with closed forceps/finger superiorly towards the collection, staying deep to platysma and below the gland capsule as needed; 3. Enter the abscess cavity — take pus immediately for culture (include TB where chronic); 4. Explore all loculations digitally, communicating sublingual/submental extensions opened; 5. Irrigate copiously; 6. Extract the causative tooth in the same sitting (intraoral step); 7. Place corrugated/glove drain(s) secured to skin; 8. Loose closure around drains only', 'Intraoral drainage alone for collections pointing into the mouth without deep-space involvement; bilateral decompression with airway protection for Ludwig angina; repeated needle aspiration is not adequate for deep neck pus', 'Loose skin approximation around corrugated drains; drains shortened/removed as drainage settles over 48-72 h', 'DIRTY', 'Airway observations prominently charted for 24 hours (swelling can progress early); IV antibiotics rationalised to culture; drain care and daily assessment, removal by 72 h when dry; encourage oral fluids and chlorhexidine rinses after extraction; glycaemic work-up completed before discharge; dental follow-up for remaining carious teeth booked — the next abscess is prevented in the dental chair'),
  ('MAXILLOFACIAL', 'TPL-MAXF-05', 'Primary cleft lip repair (rotation-advancement)', 'Unilateral cleft lip repair by Millard-pattern rotation-advancement', 'Supine with head ring and shoulder roll at the table head; specialist centre/outreach cleft list; loupes; oral RAE tube secured midline to the chin', 'Fitness thresholds confirmed and recorded (age/weight/haemoglobin per unit rule-of-tens practice); anaesthesia by paediatric-experienced team; markings BEFORE infiltration; adrenaline-containing local infiltration per protocol for haemostasis', 'Skin incisions per the marked rotation-advancement design: rotation incision on the medial element, advancement flap on the lateral element, preserving Cupid''s bow landmarks tattooed/marked beforehand', '1. Mark the anthropometric points (Cupid''s bow peaks, columellar base, alar base, commissures) with the lip at rest — the marks are the operation; 2. Infiltrate and allow vasoconstriction; 3. Incise the rotation component and release the medial lip until the Cupid''s bow rotates level; 4. Raise the lateral advancement flap with alar-base freeing; 5. Dissect and repair the orbicularis oris as a complete muscular sphincter across the cleft — the functional heart of the repair; 6. Set the nasal floor and alar base symmetry; 7. Close skin matching the marked vermilion border precisely; 8. Align the wet-dry vermilion junction and mucosa', 'Straight-line or Tennison techniques per surgeon training; staged lip adhesion for very wide clefts; palate repair is a SEPARATE later operation (9-18 months) on the pathway', 'Muscle with fine absorbable sutures, skin with fine monofilament (removed day 5-7) or subcuticular absorbable; mucosa absorbable; light antibiotic-ointment dressing only', 'CLEAN_CONTAMINATED', 'Feed early per unit protocol (breast/cup feeding generally resumed same day); arm splints only per unit policy; keep the wound moist with ointment, no crust picking; suture removal day 5-7 where non-absorbable; review at 2 weeks and enrol in the longitudinal cleft pathway — palate timing, hearing surveillance, speech review and school-age revision assessment all booked on the same record; document family counselling'),
  ('PLASTICS', 'TPL-PLAS-01', 'Split-thickness skin graft harvest and application', 'Split-thickness skin grafting of a granulating or freshly excised wound', 'Position by donor and recipient sites — thigh donor with the limb held for a flat harvest surface', 'Confirm the recipient bed is graftable: red granulation or freshly excised bleeding bed, no slough, low bacterial load (beta-haemolytic streptococcus is a graft killer — swab-positive wounds are deferred and treated); donor site shaved and lubricated', 'No incision as such: dermatome or humby-knife harvest from the marked donor site (lateral thigh standard)', '1. Set knife/dermatome depth and confirm with the blade-gap check; 2. Lubricate and tension the donor skin with boards; 3. Harvest with steady strokes — an even translucent sheet with punctate bleeding signals correct depth; 4. Mesh or fenestrate the graft (hand-fenestration with a blade where no mesher; meshing extends cover and lets exudate escape); 5. Prepare the bed: final haemostasis — haematoma is the commonest cause of graft loss; 6. Lay the graft dermis-down, trim to fit with slight overlap; 7. Fix with sutures/staples/glue at edges and quilting where mobile; 8. Non-adherent layer, then a firm conforming bolster/pressure dressing; splint across joints; 9. Dress the donor site with a low-adherence retained dressing', 'Full-thickness grafts for face/hand aesthetic-functional units; pinch grafts under local anaesthesia for small ulcers at district level; negative-pressure fixation where devices exist', 'Graft secured with edge fixation plus bolster; joints splinted in the safe/functional position; first graft inspection at day 3-5 unless soaked or smelly earlier', 'CLEAN_CONTAMINATED', 'Elevate grafted limbs strictly; first dressing take-down at day 3-5 by trained staff (shear destroys grafts — soak dressings off); donor site is often the more painful wound — analgesia and leave the retained dressing 10-14 days; once taken, daily moisturising and sun protection of graft and donor; physiotherapy resumes when the graft is stable; counsel on long-term itching and pigment change'),
  ('PLASTICS', 'TPL-PLAS-02', 'Tangential excision and grafting of a deep burn', 'Staged tangential excision of deep dermal/full-thickness burn with immediate autografting', 'Per burn location; theatre WARMED for large excisions; tourniquets for limb excisions where feasible', 'Resuscitation completed and patient stable; cross-matched blood IN THEATRE — tangential excision loses substantial blood (limit each session''s excised area per unit policy); %TBSA chart and excision plan agreed at team brief; adrenaline-soaked gauze and tourniquets planned for blood conservation', 'Tangential (layered) shaving of the burn wound with graft knife until viable bleeding dermis or fat', '1. Confirm the day''s excision map — stage large burns over multiple sessions; 2. Excise tangentially in thin layers until uniform punctate bleeding (dermis) or healthy yellow fat; under tourniquet judge by colour then confirm on release; 3. Immediate haemostasis: adrenaline gauze, pressure, selective diathermy; 4. Reassess: any doubtful areas re-shaved; 5. Harvest split-thickness grafts (mesh to extend where donor skin is scarce); 6. Apply grafts to excised beds, fix and bolster; 7. Prioritise hands/joints/face for sheet (unmeshed) graft where supply allows; 8. Warm, dress, and splint joints in anti-contracture positions; 9. Record %TBSA excised, grafted, and donor sites used', 'Delayed grafting of granulating beds after eschar separation where blood/theatre scarce; amnion or allograft/xenograft as temporary biological cover where banked; escharotomy is a separate emergency bedside procedure — see rules', 'Grafts bolstered and joints splinted; unexcised areas continue antimicrobial dressings between stages', 'CLEAN_CONTAMINATED', 'ICU/HDU for large excisions: temperature, haemoglobin and clotting watched overnight; high-protein high-energy feeding (enteral early) with dietetic targets — burns are a nutrition disease; graft check day 3-5; anti-contracture splintage and physiotherapy daily from day 1; pressure-garment and scar programme enrolment before discharge; psychological support and, for children, safeguarding review where the story does not fit the burn'),
  ('PLASTICS', 'TPL-PLAS-03', 'Burn contracture release and resurfacing', 'Release of post-burn flexion contracture (neck/axilla/elbow/hand) with graft or local flap resurfacing', 'Position to place the contracture on maximal stretch; neck releases need the anaesthetic airway plan documented (intubation may be impossible until partial release under local anaesthesia)', 'Physiotherapy and splinting arranged pre-operatively for immediately after surgery; graft donor sites planned and consented; tourniquet for limb work', 'Transverse incision(s) across the contracture band at the point(s) of maximal tension, or multiple Z-plasty design for linear bands with adjacent supple skin', '1. Incise transversely through scar until the joint releases — the defect opens far larger than the incision; 2. Deepen through all tethering bands; protect underlying neurovascular structures which may be drawn into and displaced by scar; 3. Extend the release until full passive correction is achieved (serial capsular/tendon issues are recognised and staged, not forced); 4. Measure the defect; 5. Resurface: thick split or full-thickness graft for broad defects, Z-plasty transposition for linear bands, local fasciocutaneous flap over exposed tendon/joint; 6. Quilt/bolster grafts; 7. Splint the joint in the CORRECTED position; 8. Confirm distal perfusion after dressing and splint', 'Z-plasty chains alone where lateral tissue is supple; pre-expansion or regional flaps for massive neck releases at the central unit', 'Grafts bolstered; flaps closed in layers with drain as needed; THE SPLINT IS PART OF THE CLOSURE — applied in theatre, not on the ward later', 'CLEAN', 'Splint continuously until graft stable, then structured day-splint/night-splint physiotherapy programme for months — recurrence follows abandoned splintage; graft care as per grafting template; serial photographs at each review; review at 1, 3 and 6 months with range-of-motion measurements recorded; children reviewed through growth (bands re-tighten as the child grows)'),
  ('PLASTICS', 'TPL-PLAS-04', 'Radical debridement for necrotising soft-tissue infection', 'Emergency debridement of necrotising fasciitis with planned serial relooks', 'Per site; theatre warmed; two suctions; the operation proceeds regardless of hour — delay is the mortality driver', 'Aggressive resuscitation running in parallel; broad-spectrum antibiotics including anti-toxin cover per formulary already given; blood products available; the advancing-edge markings from the ward visible after prep', 'Generous longitudinal incision over the most affected area, extended as findings dictate — small incisions are the classic error', '1. Incise and assess: dishwater fluid, grey non-bleeding fascia, and fascia that sweeps off muscle with a finger confirm the diagnosis; 2. Excise ALL necrotic skin, fat and fascia until tissue bleeds and adheres normally — margins are dictated by tissue viability, not by cosmesis; 3. Send tissue (not swabs) for urgent Gram stain and culture; 4. Assess muscle compartment by compartment; excise dead muscle; 5. Extend incisions along the limb/trunk until the leading edge of viable fascia is clearly passed; 6. Pulse-lavage/irrigate copiously; 7. Haemostasis; 8. Pack wounds OPEN with moist dressings; 9. Book the mandatory relook at 12-24 hours before leaving theatre; amputate a non-salvageable limb as a life-saving decision made with a second senior where possible', 'Amputation as source control for extensive limb disease; negative-pressure dressings between debridements where devices exist; hyperbaric oxygen is not a national option and never delays surgery', 'Never closed at the index operation; delayed closure/grafting after serial clean relooks and clinical recovery', 'DIRTY', 'ICU-level care: ongoing resuscitation, organ support, glycaemic control; scheduled relook at 12-24 hours REGARDLESS of apparent improvement, then serially until a clean stable wound; antibiotics rationalised to culture; nutrition support early; reconstruction (grafts/flaps) planned only after the infection phase is closed; document cumulative debrided area and photograph at each stage; mortality risk discussed early with family'),
  ('PLASTICS', 'TPL-PLAS-05', 'Wide local excision of cutaneous SCC with reconstruction', 'Wide excision of squamous cell carcinoma with split-skin graft or local flap closure', 'Per lesion site; regional node basin exposed in the field for examination', 'Biopsy-proven diagnosis on the consent; margin plan documented (commonly around 6-10 mm clinical margin for higher-risk lesions per unit protocol); nodes examined and findings recorded; photograph with scale before excision', 'Elliptical or circular excision around the marked clinical margin, orientation suture placed for histology mapping', '1. Mark the palpable/visible tumour edge under good light, then the measured margin around it; 2. Excise perpendicular through to an appropriate deep plane (including deep margin fascia where indicated); 3. Place the orientation suture and complete the histology form with a margin map/diagram; 4. Haemostasis; 5. Assess the defect honestly — do not compromise the margin to make closure easier; 6. Reconstruct up the ladder: direct closure, split-skin graft, or local flap by site and exposure of structures; 7. Graft/flap secured per standard technique; 8. Dress and splint as the reconstruction requires', 'Delayed reconstruction awaiting margin histology for high-risk/recurrent lesions (graft or dress open, definitive closure after clearance); referral for radiotherapy or nodal dissection per histology and stage', 'By reconstruction chosen: layered closure, bolstered graft, or flap with drain; specimen orientation confirmed with the scrub team before leaving theatre', 'CLEAN', 'Standard graft/flap aftercare; chase histology actively — involved margins are re-excised, not watched; enrol persons with albinism in skin-surveillance and sun-protection programmes (hat, clothing, sunscreen supply route documented); node basin examined at every review; follow-up schedule per risk (commonly 3-6 monthly for 2 years, then annually) booked before discharge')) AS t(specialty, template_code, template_name, typical_procedure, position, preparation, incision, key_steps, technique_options, closure_plan, wound_classification, postop_instructions)
ON CONFLICT (tenant_id, template_code) DO NOTHING;
